var QNA=[{"id": "2211-29", "short": "22년 11월 29번", "group": "22년 11월", "num": 29, "topic_ko": "선매 행위의 의미와 두 가지 방법(광고, 제품 확산)", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "선매 행위는 경쟁자가 어떤 활동을 시작하지 못하게 막는 전략이며 타이밍이 중요함"}, {"n": 2, "label": "방법 1", "from": 4, "to": 5, "summary_ko": "신규 진입자가 시장에 들어오기 전과 들어와 있는 동안 광고 가중치를 높여 진입자의 광고 효과를 떨어뜨림"}, {"n": 3, "label": "방법 2", "from": 6, "to": 8, "summary_ko": "다양한 제품 변형을 출시해 경쟁자가 파고들 빈틈을 줄이는 제품 확산 전략"}], "gloss": [{"w": "pre-emption", "m": "선매 행위, 선제 조치"}, {"w": "rival", "m": "경쟁자", "form": "rivals", "note": "명사 rival의 복수형"}, {"w": "discourage", "m": "단념시키다"}, {"w": "intent", "m": "의도, 취지"}, {"w": "rewarding", "m": "득이 되는, 보람 있는", "form": "rewarding", "note": "동사 reward(보상하다)에서 나온 형용사(-ing형)"}, {"w": "entrant", "m": "신규 진입자"}, {"w": "launch", "m": "출시하다, 진출하다", "form": "launches", "note": "동사 launch의 3인칭 단수 현재형(주어 a new entrant가 단수)"}, {"w": "impression", "m": "인상"}, {"w": "proliferation", "m": "확산, 급증"}, {"w": "variant", "m": "변형, 다른 형태", "form": "variants", "note": "명사 variant의 복수형"}, {"w": "accommodate", "m": "수용하다", "form": "accommodated", "note": "동사 accommodate의 과거분사형(is not accommodated 수동 의미)"}, {"w": "untapped", "m": "아직 개발되지 않은, 점유되지 않은"}, {"w": "arguably", "m": "거의 틀림없이"}], "qa": [{"chunk": 1, "q": "본문에서 설명하는 선매 행위(pre-emption)란 무엇인가?", "opts": ["경쟁자의 전략을 그대로 따라 하기 위해 만든 전략", "시장에서 서둘러 철수하기 위해 만든 전략", "경쟁자가 어떤 특정 활동을 시작하는 것을 방지하기 위해 만든 전략"], "ans": 2, "why": ["1번 문장에서 선매 행위는 경쟁자가 특정 활동을 시작하는 것을 방지하려는 전략이라고 정의함.", "경쟁자를 따라 하거나 시장에서 철수한다는 내용은 지문에 없음."], "ev_en": "Pre-emption means that a strategy is designed to prevent a rival from starting some particular activity.", "ev_ko": "선매 행위는 어떤 전략이 경쟁자로 하여금 어떤 특정한 활동을 시작하는 것을 방지하기 위해 만들어진다는 것을 의미한다."}, {"chunk": 2, "q": "선매 행위로서 광고의 가중치를 높이는 목적은 무엇인가?", "opts": ["신규 진입자의 광고가 잠재적 구매자에게 인상을 남기기 더 어렵게 만들기 위해", "기존 제품의 가격을 낮추기 위해", "신규 진입자와 공동으로 광고하기 위해"], "ans": 0, "why": ["5번 문장에서 그 취지는 신규 진입자의 광고가 잠재적 구매자에게 인상을 남기기 더 어렵게 만드는 것이라고 함.", "가격 인하나 공동 광고는 지문에 나오지 않음."], "ev_en": "The intent is to make it more difficult for the new entrant\u2019s advertising to make an impression on potential buyers.", "ev_ko": "그 취지는 신규 진입자의 광고가 잠재적 구매자들에게 인상을 남기는 것을 더 어렵게 만드는 것이다."}, {"chunk": 3, "q": "제품 확산(product proliferation) 전략의 일반적인 아이디어는 무엇인가?", "opts": ["제품 종류를 줄여 하나의 제품에 집중하는 것", "시장 수요 중 수용되지 않는 부분이 거의 없도록 다양한 제품 변형을 출시하는 것", "새로운 광고 모델을 자주 바꾸는 것"], "ans": 1, "why": ["7번 문장에서 다양한 제품 변형을 출시해 수용되지 않는 시장 수요가 거의 없게 하는 것이라고 함.", "제품 수를 줄이는 것은 정반대 내용이고, 광고 모델 교체는 지문에 없음."], "ev_en": "The general idea is to launch a large variety of product variants so that there is very little in the way of market demand that is not accommodated.", "ev_ko": "일반적인 아이디어는 수용되지 않는 시장 수요가 거의 없도록 다양한 제품 변형을 출시하는 것이다."}], "tf": [{"s": "선제적 조치는 경쟁자가 같은 행동을 하는 것을 단념시킬 수 있는 의도의 공표일 수도 있다.", "t": true, "why": ["2번 문장의 내용과 일치함."], "ev_en": "In some case a pre-emptive move may simply be an announcement of some intent that might discourage rivals from doing the same.", "ev_ko": "어떤 경우에는 선제적 조치는 단순히 경쟁자들이 같은 행동을 하는 것을 단념시킬 수 있는 어떤 의도의 공표일 수도 있다."}, {"s": "선매 행위에서는 어느 시점에 결정하거나 행동하는지가 중요하지 않다.", "t": false, "why": ["틀린 부분은 \"중요하지 않다\"임.", "3번 문장에서 타이밍이 매우 중요하고, 어떤 시점의 결정이 다른 시점보다 훨씬 더 득이 될 수 있다고 함."], "ev_en": "The idea of pre-emption implies that timing is sometimes very important \u2014 a decision or an action at one point in time might be much more rewarding than doing it at a different time point.", "ev_ko": "선매 행위 개념은 때로 타이밍이 매우 중요하다는 것을 암시하는데, 즉 어떤 시점의 결정이나 조치는 다른 시점에 그것을 하는 것보다 훨씬 더 득이 될 수 있다."}, {"s": "선매 행위로서의 광고 가중치 상향은 신규 진입자가 시장에 진출한 뒤에만 이루어진다.", "t": false, "why": ["틀린 부분은 \"진출한 뒤에만\"임.", "4번 문장에서 진출하기 이전과 진출해 있는 동안에 광고 가중치를 높일 수 있다고 함."], "ev_en": "Pre-emption may involve up-weighting advertising for a period before and during when a new entrant launches into a market.", "ev_ko": "선매 행위는 새로운 진입자가 시장에 진출하기 이전과 진출해 있는 동안에 광고의 가중치를 높이는 것을 포함할 수 있다."}, {"s": "제품 확산은 또 다른 잠재적인 선매 행위 전략이다.", "t": true, "why": ["6번 문장의 내용과 일치함."], "ev_en": "Product proliferation is another potential pre-emption strategy.", "ev_ko": "제품 확산은 또 다른 잠재적인 선매 행위 전략이다."}, {"s": "시장이 이미 제품 변형으로 채워져 있으면 경쟁자가 아직 점유되지 않은 수요를 찾기가 더 쉬워진다.", "t": false, "why": ["틀린 부분은 \"더 쉬워진다\"임.", "8번 문장에서 시장이 제품 변형으로 이미 채워져 있으면 경쟁자가 점유되지 않은 시장 수요를 찾기가 더 어렵다고 함."], "ev_en": "Arguably, if a market is already filled with product variants it is more difficult for competitors to find untapped pockets of market demand.", "ev_ko": "거의 틀림없이, 만약 시장이 제품 변형으로 이미 채워져 있다면 경쟁자들은 아직 점유되지 않은 시장 수요 주머니를 찾기가 더 어렵다."}], "flow": {"fixed": "선매 행위는 경쟁자가 어떤 활동을 시작하지 못하게 막으려는 전략으로, 의도를 공표하는 것도 포함되며 타이밍이 중요하다는 점을 암시한다.", "order": ["한 가지 방법은 신규 진입자가 시장에 들어오기 전과 들어와 있는 동안 광고 가중치를 높여, 진입자의 광고가 구매자에게 인상을 남기기 어렵게 만드는 것이다.", "또 다른 방법은 제품 확산으로, 다양한 제품 변형을 내놓아 수용되지 않는 시장 수요가 거의 없도록 하는 것이다.", "이렇게 시장이 이미 제품 변형으로 채워져 있으면, 경쟁자는 아직 점유되지 않은 수요를 찾기가 더 어렵다."], "clue": ["\"한 가지 방법\"으로 앞의 선매 행위 설명 뒤에 첫 번째 구체적 방법을 소개함", "\"또 다른 방법\"이 앞의 \"한 가지 방법\"을 받아 두 번째 방법을 제시함", "\"이렇게 ... 채워져 있으면\"이 앞의 제품 변형 출시의 결과를 설명함"], "why": ["선매 행위의 뜻 -> 첫 번째 방법(광고) -> 두 번째 방법(제품 확산) -> 제품 확산의 효과 순서임."], "cards": ["한 가지 방법은 신규 진입자가 시장에 들어오기 전과 들어와 있는 동안 광고 가중치를 높여, 진입자의 광고가 구매자에게 인상을 남기기 어렵게 만드는 것이다.", "이렇게 시장이 이미 제품 변형으로 채워져 있으면, 경쟁자는 아직 점유되지 않은 수요를 찾기가 더 어렵다.", "또 다른 방법은 제품 확산으로, 다양한 제품 변형을 내놓아 수용되지 않는 시장 수요가 거의 없도록 하는 것이다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "Pre-emption means that a strategy is designed to prevent a rival from starting some particular activity.", "ko": "선매 행위는 어떤 전략이 경쟁자로 하여금 어떤 특정한 활동을 시작하는 것을 방지하기 위해 만들어진다는 것을 의미한다."}, {"n": 2, "en": "In some case a pre-emptive move may simply be an announcement of some intent that might discourage rivals from doing the same.", "ko": "어떤 경우에는 선제적 조치는 단순히 경쟁자들이 같은 행동을 하는 것을 단념시킬 수 있는 어떤 의도의 공표일 수도 있다."}, {"n": 3, "en": "The idea of pre-emption implies that timing is sometimes very important \u2014 a decision or an action at one point in time might be much more rewarding than doing it at a different time point.", "ko": "선매 행위 개념은 때로 타이밍이 매우 중요하다는 것을 암시하는데, 즉 어떤 시점의 결정이나 조치는 다른 시점에 그것을 하는 것보다 훨씬 더 득이 될 수 있다."}, {"n": 4, "en": "Pre-emption may involve up-weighting advertising for a period before and during when a new entrant launches into a market.", "ko": "선매 행위는 새로운 진입자가 시장에 진출하기 이전과 진출해 있는 동안에 광고의 가중치를 높이는 것을 포함할 수 있다."}, {"n": 5, "en": "The intent is to make it more difficult for the new entrant\u2019s advertising to make an impression on potential buyers.", "ko": "그 취지는 신규 진입자의 광고가 잠재적 구매자들에게 인상을 남기는 것을 더 어렵게 만드는 것이다."}, {"n": 6, "en": "Product proliferation is another potential pre-emption strategy.", "ko": "제품 확산은 또 다른 잠재적인 선매 행위 전략이다."}, {"n": 7, "en": "The general idea is to launch a large variety of product variants so that there is very little in the way of market demand that is not accommodated.", "ko": "일반적인 아이디어는 수용되지 않는 시장 수요가 거의 없도록 다양한 제품 변형을 출시하는 것이다."}, {"n": 8, "en": "Arguably, if a market is already filled with product variants it is more difficult for competitors to find untapped pockets of market demand.", "ko": "거의 틀림없이, 만약 시장이 제품 변형으로 이미 채워져 있다면 경쟁자들은 아직 점유되지 않은 시장 수요 주머니를 찾기가 더 어렵다."}]}, {"id": "2211-30", "short": "22년 11월 30번", "group": "22년 11월", "num": 30, "topic_ko": "카운터셰이딩이 동물을 배경과 섞이게 하는 원리", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 1, "summary_ko": "카운터셰이딩은 동물에게 위장을 제공하는 시각적 평평화 과정"}, {"n": 2, "label": "원리", "from": 2, "to": 5, "summary_ko": "빛을 받은 물체는 아래로 갈수록 어두워져 모양이 드러나므로, 균일한 색의 동물은 눈에 띔"}, {"n": 3, "label": "결과", "from": 6, "to": 10, "summary_ko": "대부분 동물은 윗부분이 더 어두워 빛을 받으면 한 색처럼 보여 배경과 섞임"}], "gloss": [{"w": "countershading", "m": "카운터셰이딩(명암역위형 보호색)"}, {"w": "camouflage", "m": "위장"}, {"w": "illuminate", "m": "(빛을) 비추다", "form": "illuminated", "note": "동사 illuminate의 과거분사형, 'be illuminated'는 '빛을 받다'"}, {"w": "gradually", "m": "점차"}, {"w": "shade", "m": "음영이 생기다, 그늘지게 하다", "form": "shaded", "note": "동사 shade의 과거분사형, 수동 의미('음영이 생기다')"}, {"w": "distinguish", "m": "식별하다, 구별하다"}, {"w": "uniformly", "m": "균일하게"}, {"w": "substrate", "m": "밑바탕, 바탕면(동물이 놓인 표면)"}, {"w": "belly", "m": "복부, 배"}, {"w": "blend in", "m": "섞이다, 어우러지다", "form": "blends in", "note": "동사구 blend in의 3인칭 단수형(주어 The animal이 단수)"}, {"w": "coloration", "m": "배색, 색깔 배치"}, {"w": "visible", "m": "눈에 보이는, 눈에 띄는"}], "qa": [{"chunk": 1, "q": "첫 문장에서 설명하는 카운터셰이딩은 무엇인가?", "opts": ["동물에게 위장을 제공하는, 시각적으로 평평하게 만드는 과정", "동물이 빛을 흡수해 체온을 높이는 과정", "동물의 모양을 더 뚜렷하게 보이게 하는 과정"], "ans": 0, "why": ["첫 문장이 곧 정의임.", "카운터셰이딩은 시각적으로 평평하게 만들어 동물에게 위장을 제공하는 과정임.", "체온을 높이는 과정이라는 말은 지문에 없음.", "모양을 뚜렷하게 하는 것이 아니라 오히려 모양의 인상을 없애 줌."], "ev_en": "Countershading is the process of optical flattening that provides camouflage to animals.", "ev_ko": "카운터셰이딩(명암역위형보호색)은 동물에게 위장을 제공하는 시각적으로 평평하게 하는 과정이다."}, {"chunk": 2, "q": "동물이 밑바탕과 정확히 같지만 균일한 색이라면, 빛을 받을 때 어떻게 되는가?", "opts": ["쉽게 눈에 띈다.", "배경과 섞여 보이지 않게 된다.", "몸 윗부분이 아랫부분보다 어둡게 보인다."], "ans": 0, "why": ["위에서 빛을 받으면 물체는 위가 가장 밝고 아래로 갈수록 어두워짐.", "이 음영 때문에 보는 사람이 모양을 알아봄.", "그래서 색이 균일해도 빛을 받으면 쉽게 눈에 띔.", "'윗부분이 더 어둡게 보인다'는 지문과 다름. 색이 균일한 동물은 위에서 빛을 받으면 맨 위가 가장 밝음(brightest on top, 맨 위에서 가장 밝은).", "윗부분이 더 어두운 동물은 다음 덩어리(6번 문장 이후)의 경우이고, 그런 동물이 배경과 섞임."], "ev_en": "Thus even if an animal is exactly, but uniformly, the same color as the substrate, it will be easily visible when illuminated.", "ev_ko": "따라서 비록 동물이 밑바탕과 정확하지만 균일하게 같은 색일지라도 빛이 비춰질 때 쉽게 눈에 띌 것이다."}, {"chunk": 3, "q": "대부분의 동물이 위에서 빛을 받으면 어떻게 보이는가?", "opts": ["등과 복부가 뚜렷하게 나뉘어 보인다.", "하나의 색처럼 보여 밑바탕과 쉽게 섞인다.", "등이 더 어두워져 눈에 잘 띈다."], "ans": 1, "why": ["대부분의 동물은 아랫부분보다 윗부분이 더 어두움.", "빛을 받으면 어두운 등은 밝아지고 밝은 복부는 음영이 생김.", "결과적으로 하나의 색처럼 보여 배경과 섞임.", "등이 더 어두워지는 것이 아니라 오히려 밝아지고, 등과 복부가 뚜렷이 나뉘어 보이는 것이 아니라 하나의 색처럼 보임."], "ev_en": "The animal thus appears to be a single color and easily blends in with the substrate.", "ev_ko": "따라서 동물은 하나의 색처럼 보이고 밑바탕과 쉽게 섞인다."}], "tf": [{"s": "물체가 위에서 빛을 받으면 맨 위가 가장 밝게 보인다.", "t": true, "why": ["위에서 빛이 비치면 윗부분이 가장 밝음.", "지문 내용과 일치함."], "ev_en": "When sunlight illuminates an object from above, the object will be brightest on top.", "ev_ko": "햇빛이 물체를 위에서 비출 때, 그 물체는 맨 위에서 가장 밝을 것이다."}, {"s": "빛을 받은 물체의 색은 아래로 갈수록 점차 더 밝게 변한다.", "t": false, "why": ["아래로 갈수록 더 어두워지므로 틀림.", "올바른 내용은 '아래로 갈수록 점차 더 어두운색으로 음영이 생긴다'임."], "ev_en": "The color of the object will gradually shade darker toward the bottom.", "ev_ko": "물체의 색깔은 맨 아래로 향할수록 점차 더 어두운색으로 음영이 생기게 될 것이다."}, {"s": "대부분의 동물은 아랫부분보다 윗부분이 더 어둡다.", "t": true, "why": ["대부분의 동물은 등이 어둡고 배가 밝음.", "지문 내용과 일치함."], "ev_en": "Most animals, however, are darker above than they are below.", "ev_ko": "그러나 대부분의 동물은 아랫부분보다 윗부분이 더 어둡다."}, {"s": "위에서 빛을 받으면 동물의 어두운 등은 더 어두워지고 밝은 복부는 더 밝아진다.", "t": false, "why": ["방향이 반대임.", "올바른 내용은 어두운 등은 밝아지고 밝은 복부는 음영이 생긴다는 것임."], "ev_en": "When they are illuminated from above, the darker back is lightened and the lighter belly is shaded.", "ev_ko": "그들이 위에서 빛을 받을 때, 더 어두운 등은 밝아지고 더 밝은 복부는 음영이 생긴다."}, {"s": "카운터셰이딩은 생물체의 모양에 대한 시각적 인상을 없애 준다.", "t": true, "why": ["카운터셰이딩은 모양의 시각적 인상을 파괴함.", "그 결과 동물이 배경과 섞임."], "ev_en": "This pattern of coloration, or countershading, destroys the visual impression of shape in the organism.", "ev_ko": "이러한 형태의 배색 즉, 카운터셰이딩은 생물체의 모양의 시각적 인상을 파괴한다."}], "flow": {"fixed": "카운터셰이딩은 동물에게 위장을 제공하는, 시각적으로 평평하게 만드는 과정이다.", "order": ["물체는 위에서 빛을 받으면 맨 위가 가장 밝고 아래로 갈수록 점차 어두워지는데, 이 음영 덕분에 보는 사람은 그 모양을 알아볼 수 있다.", "그래서 동물이 밑바탕과 똑같은 색이라도 색이 균일하기만 하면, 이런 음영 때문에 모양이 드러나 빛을 받을 때 쉽게 눈에 띈다.", "하지만 대부분의 동물은 그렇게 균일한 색이 아니라 윗부분이 더 어두워서, 빛을 받으면 하나의 색처럼 보이고 그 결과 배경과 쉽게 섞인다."], "clue": ["첫 덩어리가 말한 과정의 원리(빛과 음영)를 풀어 주는 설명이 이어짐", "'이런 음영'이 앞 덩어리의 음영 설명을 가리키고 '그래서'로 균일한 색 동물이 눈에 띄는 결과를 이끎", "'그렇게 균일한 색이 아니라'가 앞 덩어리의 균일한 색 동물과 대비되고 '하지만'으로 반대 경우를 제시함"], "why": ["정의, 원리, 눈에 띄는 경우, 반대로 섞이는 경우 순으로 흐름."], "cards": ["하지만 대부분의 동물은 그렇게 균일한 색이 아니라 윗부분이 더 어두워서, 빛을 받으면 하나의 색처럼 보이고 그 결과 배경과 쉽게 섞인다.", "그래서 동물이 밑바탕과 똑같은 색이라도 색이 균일하기만 하면, 이런 음영 때문에 모양이 드러나 빛을 받을 때 쉽게 눈에 띈다.", "물체는 위에서 빛을 받으면 맨 위가 가장 밝고 아래로 갈수록 점차 어두워지는데, 이 음영 덕분에 보는 사람은 그 모양을 알아볼 수 있다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Countershading is the process of optical flattening that provides camouflage to animals.", "ko": "카운터셰이딩(명암역위형보호색)은 동물에게 위장을 제공하는 시각적으로 평평하게 하는 과정이다."}, {"n": 2, "en": "When sunlight illuminates an object from above, the object will be brightest on top.", "ko": "햇빛이 물체를 위에서 비출 때, 그 물체는 맨 위에서 가장 밝을 것이다."}, {"n": 3, "en": "The color of the object will gradually shade darker toward the bottom.", "ko": "물체의 색깔은 맨 아래로 향할수록 점차 더 어두운색으로 음영이 생기게 될 것이다."}, {"n": 4, "en": "This shading gives the object depth and allows the viewer to distinguish its shape.", "ko": "이러한 음영은 물체에 농도를 주고 보는 사람이 그것의 모양을 식별하게 해 준다."}, {"n": 5, "en": "Thus even if an animal is exactly, but uniformly, the same color as the substrate, it will be easily visible when illuminated.", "ko": "따라서 비록 동물이 밑바탕과 정확하지만 균일하게 같은 색일지라도 빛이 비춰질 때 쉽게 눈에 띌 것이다."}, {"n": 6, "en": "Most animals, however, are darker above than they are below.", "ko": "그러나 대부분의 동물은 아랫부분보다 윗부분이 더 어둡다."}, {"n": 7, "en": "When they are illuminated from above, the darker back is lightened and the lighter belly is shaded.", "ko": "그들이 위에서 빛을 받을 때, 더 어두운 등은 밝아지고 더 밝은 복부는 음영이 생긴다."}, {"n": 8, "en": "The animal thus appears to be a single color and easily blends in with the substrate.", "ko": "따라서 동물은 하나의 색처럼 보이고 밑바탕과 쉽게 섞인다."}, {"n": 9, "en": "This pattern of coloration, or countershading, destroys the visual impression of shape in the organism.", "ko": "이러한 형태의 배색 즉, 카운터셰이딩은 생물체의 모양의 시각적 인상을 파괴한다."}, {"n": 10, "en": "It allows the animal to blend in with its background.", "ko": "그것은 동물이 그것의 배경과 섞이게 해 준다."}]}, {"id": "2211-31", "short": "22년 11월 31번", "group": "22년 11월", "num": 31, "topic_ko": "놀람(예측 위반)이 학습의 동력이라는 것과 예측 가능성의 중요성", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "오류 신호가 없으면 학습이 없고, 기대에 어긋나는 놀람이 학습의 근본 동력임"}, {"n": 2, "label": "전개", "from": 4, "to": 8, "summary_ko": "같은 음이 반복되면 뇌 반응이 줄어드는 적응이 일어나고, 음이 갑자기 바뀌면 강한 놀람 반응이 나타남"}, {"n": 3, "label": "보충", "from": 9, "to": 11, "summary_ko": "적응은 반복 자체보다 예측 가능성에 달려 있어 ABABA에는 익숙해지고 ABABB에는 놀람"}], "gloss": [{"w": "error signal", "m": "오류 신호"}, {"w": "organism", "m": "유기체, 생물", "form": "organisms", "note": "명사 organism의 복수형"}, {"w": "violate", "m": "어기다, 위반하다"}, {"w": "fundamental", "m": "근본적인"}, {"w": "auditory", "m": "청각의"}, {"w": "progressively", "m": "점진적으로"}, {"w": "adaptation", "m": "적응"}, {"w": "deceptively", "m": "겉보기에는, 현혹될 정도로"}, {"w": "anticipate", "m": "예상하다"}, {"w": "cortex", "m": "피질"}, {"w": "neuron", "m": "뉴런, 신경 세포", "form": "neurons", "note": "명사 neuron의 복수형"}, {"w": "vigorously", "m": "힘차게, 활발하게"}, {"w": "alternate", "m": "번갈아 나오다, 교차하다", "form": "alternating", "note": "동사 alternate의 현재분사형(뒤의 명사를 꾸미는 형용사 역할)"}, {"w": "predictable", "m": "예측 가능한"}, {"w": "fire", "m": "(뉴런이) 활성화되다, 신호를 내보내다", "form": "fire", "note": "여기서는 \u2018불을 붙이다\u2019가 아니라 뉴런이 신호를 내보낸다는 뜻"}], "qa": [{"chunk": 1, "q": "본문에 따르면 유기체가 학습하는 때는 언제인가?", "opts": ["사건이 그들의 기대에 어긋날 때", "같은 사건이 계속 반복될 때", "오류 신호가 전혀 없을 때"], "ans": 0, "why": ["2번 문장에서 유기체는 사건이 기대에 어긋날 때에만 학습한다고 함.", "1번 문장에서 오류 신호 없이는 학습이 불가능하다고 했으므로 오류 신호가 없을 때는 틀림."], "ev_en": "Organisms only learn when events violate their expectations.", "ev_ko": "유기체는 사건이 그들의 기대에 어긋날 때에만 학습한다."}, {"chunk": 2, "q": "AAAAA를 듣다가 음이 AAAAA#으로 갑자기 바뀌면 일차 청각 피질은 어떻게 반응하는가?", "opts": ["적응이 사라질 뿐 아니라 추가적인 뉴런이 힘차게 활성화되기 시작한다.", "적응이 더 강해져 반응이 더 줄어든다.", "아무런 변화도 보이지 않는다."], "ans": 0, "why": ["8번 문장에서 즉시 강한 놀람 반응을 보인다고 함.", "적응이 점차 사라질 뿐 아니라 예상치 못한 소리에 추가 뉴런이 활성화된다는 내용임.", "반응이 더 줄거나 변화가 없다는 내용은 지문과 반대임."], "ev_en": "Your primary auditory cortex immediately shows a strong surprise reaction: not only does the adaptation fade away, but additional neurons begin to vigorously fire in response to the unexpected sound.", "ev_ko": "당신의 일차 청각 피질은 즉시 강한 놀람의 반응을 보이는데, 즉 적응이 점차 사라질 뿐만 아니라 예상치 못한 소리에 대한 반응으로 추가적인 뉴런이 힘차게 활성화되기 시작한다."}, {"chunk": 3, "q": "9번 문장에 따르면 적응으로 이어지는 데 중요한 것은 무엇인가?", "opts": ["음이 반복되는 횟수", "음의 높낮이", "음들이 예측 가능한지 여부"], "ans": 2, "why": ["9번 문장에서 적응으로 이어지는 것은 단지 반복만이 아니고 중요한 것은 음이 예측 가능한지라고 함.", "횟수나 음의 높낮이는 지문에서 기준으로 제시되지 않음."], "ev_en": "And it is not just repetition that leads to adaptation: what matters is whether the notes are predictable.", "ev_ko": "그리고 적응으로 이어지는 것은 단지 반복만이 아니다. 중요한 것은 그 음들이 예측 가능한지이다."}], "tf": [{"s": "각각의 음이 반복되면서 청각 영역의 반응은 점진적으로 감소한다.", "t": true, "why": ["5번 문장의 내용과 일치함."], "ev_en": "Each note draws out a response in the auditory areas of your brain \u2014 but as the notes repeat, those responses progressively decrease.", "ev_ko": "각각의 음은 당신의 뇌의 청각 영역에서 반응을 끌어내지만 음이 반복되면서 그 반응은 점진적으로 감소한다."}, {"s": "적응은 뇌가 다음 사건을 예상하지 못하고 있음을 보여 주는 현상이다.", "t": false, "why": ["틀린 부분은 \"예상하지 못하고 있음\"임.", "6번 문장에서 적응은 뇌가 다음 사건을 예상하는 것을 배우고 있음을 보여 주는 현상이라고 함."], "ev_en": "This is called \u201cadaptation,\u201d a deceptively simple phenomenon that shows that your brain is learning to anticipate the next event.", "ev_ko": "이것은 \u2018적응\u2019이라 불리며 당신의 뇌가 다음 사건을 예상하는 것을 배우고 있음을 보여 주는 현혹될 정도로 단순해 보이는 현상이다."}, {"s": "ABABA처럼 음이 교차하는 소리를 들으면 뇌는 이 교차에 익숙해져 청각 영역의 활동이 다시 감소한다.", "t": true, "why": ["10번 문장의 내용과 일치함."], "ev_en": "For instance, if you hear an alternating set of notes, such as ABABA, your brain gets used to this alternation, and the activity in your auditory areas again decreases.", "ev_ko": "예를 들어 만약 당신이 ABABA와 같이 한 세트의 교차하는 음을 듣는다면, 당신의 뇌는 이 교차에 익숙해지고, 당신의 청각 영역 내 활동은 다시 감소한다."}, {"s": "ABABB와 같은 예상치 못한 반복은 놀람 반응을 일으키지 않는다.", "t": false, "why": ["틀린 부분은 \"일으키지 않는다\"임.", "11번 문장에서 놀람 반응을 일으키는 것은 바로 ABABB와 같은 예상치 못한 반복이라고 함."], "ev_en": "This time, however, it is an unexpected repetition, such as ABABB, that triggers a surprise response.", "ev_ko": "그러나 이번에는 놀람의 반응을 일으키는 것은 바로 ABABB와 같은 예상치 못한 반복이다."}, {"s": "유기체는 사건이 그들의 기대에 어긋날 때에만 학습한다.", "t": true, "why": ["2번 문장의 내용과 일치함."], "ev_en": "Organisms only learn when events violate their expectations.", "ev_ko": "유기체는 사건이 그들의 기대에 어긋날 때에만 학습한다."}], "flow": {"fixed": "오류 신호가 없으면 학습이 불가능하며, 유기체는 사건이 기대에 어긋날 때에만 학습하므로 놀람은 학습의 근본적인 동력 중 하나이다.", "order": ["예를 들어 똑같은 음이 계속 반복되면 뇌의 청각 영역 반응이 점점 줄어드는데, 이를 적응이라 하며 뇌가 다음 사건을 예상하고 있음을 보여 준다.", "그러다 음이 갑자기 바뀌면 적응이 사라질 뿐 아니라 추가 뉴런까지 활성화되며, 뇌는 강한 놀람 반응을 보인다.", "나아가 적응으로 이어지는 것은 반복만이 아니라 예측 가능성이어서, 교차하는 ABABA에는 익숙해지지만 예상치 못한 ABABB에는 놀람 반응이 나타난다."], "clue": ["\"예를 들어 ... 반복되면\"이 앞의 학습 원리를 같은 음 반복 상황으로 구체화함", "\"그러다 ... 갑자기 바뀌면\"이 앞의 적응 상태가 깨지는 장면을 이어 줌", "\"나아가 ... 반복만이 아니라\"가 앞의 두 장면을 묶어 예측 가능성이라는 핵심을 덧붙임"], "why": ["학습 원리 -> 같은 음 반복(적응) -> 음의 급변(놀람) -> 핵심은 예측 가능성 순서임."], "cards": ["나아가 적응으로 이어지는 것은 반복만이 아니라 예측 가능성이어서, 교차하는 ABABA에는 익숙해지지만 예상치 못한 ABABB에는 놀람 반응이 나타난다.", "그러다 음이 갑자기 바뀌면 적응이 사라질 뿐 아니라 추가 뉴런까지 활성화되며, 뇌는 강한 놀람 반응을 보인다.", "예를 들어 똑같은 음이 계속 반복되면 뇌의 청각 영역 반응이 점점 줄어드는데, 이를 적응이라 하며 뇌가 다음 사건을 예상하고 있음을 보여 준다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "No learning is possible without an error signal.", "ko": "어떤 학습도 오류 신호 없이는 가능하지 않다."}, {"n": 2, "en": "Organisms only learn when events violate their expectations.", "ko": "유기체는 사건이 그들의 기대에 어긋날 때에만 학습한다."}, {"n": 3, "en": "In other words, surprise is one of the fundamental drivers of learning.", "ko": "다시 말해 놀람은 학습의 근본적인 동력 중 하나이다."}, {"n": 4, "en": "Imagine hearing a series of identical notes, AAAAA.", "ko": "일련의 똑같은 음인 AAAAA를 듣는 것을 상상해 보아라."}, {"n": 5, "en": "Each note draws out a response in the auditory areas of your brain \u2014 but as the notes repeat, those responses progressively decrease.", "ko": "각각의 음은 당신의 뇌의 청각 영역에서 반응을 끌어내지만 음이 반복되면서 그 반응은 점진적으로 감소한다."}, {"n": 6, "en": "This is called \u201cadaptation,\u201d a deceptively simple phenomenon that shows that your brain is learning to anticipate the next event.", "ko": "이것은 \u2018적응\u2019이라 불리며 당신의 뇌가 다음 사건을 예상하는 것을 배우고 있음을 보여 주는 현혹될 정도로 단순해 보이는 현상이다."}, {"n": 7, "en": "Suddenly, the note changes: AAAAA#.", "ko": "갑자기 그 음이 AAAAA#으로 바뀐다."}, {"n": 8, "en": "Your primary auditory cortex immediately shows a strong surprise reaction: not only does the adaptation fade away, but additional neurons begin to vigorously fire in response to the unexpected sound.", "ko": "당신의 일차 청각 피질은 즉시 강한 놀람의 반응을 보이는데, 즉 적응이 점차 사라질 뿐만 아니라 예상치 못한 소리에 대한 반응으로 추가적인 뉴런이 힘차게 활성화되기 시작한다."}, {"n": 9, "en": "And it is not just repetition that leads to adaptation: what matters is whether the notes are predictable.", "ko": "그리고 적응으로 이어지는 것은 단지 반복만이 아니다. 중요한 것은 그 음들이 예측 가능한지이다."}, {"n": 10, "en": "For instance, if you hear an alternating set of notes, such as ABABA, your brain gets used to this alternation, and the activity in your auditory areas again decreases.", "ko": "예를 들어 만약 당신이 ABABA와 같이 한 세트의 교차하는 음을 듣는다면, 당신의 뇌는 이 교차에 익숙해지고, 당신의 청각 영역 내 활동은 다시 감소한다."}, {"n": 11, "en": "This time, however, it is an unexpected repetition, such as ABABB, that triggers a surprise response.", "ko": "그러나 이번에는 놀람의 반응을 일으키는 것은 바로 ABABB와 같은 예상치 못한 반복이다."}]}, {"id": "2211-32", "short": "22년 11월 32번", "group": "22년 11월", "num": 32, "topic_ko": "두려움과 불확실성만으로도 번지는 금융 시장의 감염", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "연결된 경제 시장은 감염에 취약해 금융 실패가 독감처럼 퍼질 수 있음"}, {"n": 2, "label": "전개", "from": 3, "to": 5, "summary_ko": "시장의 감염은 접촉이 없어도, 투자 실패가 없어도 일어날 수 있음"}, {"n": 3, "label": "결론", "from": 6, "to": 10, "summary_ko": "두려움과 불확실성이 시장을 해치며, 건전한 은행도 마지막으로 인출하게 될까 두려워해 위기가 자기충족적으로 커짐"}], "gloss": [{"w": "connectedness", "m": "연결성"}, {"w": "vulnerable", "m": "취약한"}, {"w": "infection", "m": "감염"}, {"w": "borrower", "m": "채무자, 돈을 빌린 사람", "form": "borrowers", "note": "명사 borrower의 복수형"}, {"w": "insurer", "m": "보험사", "form": "insurers", "note": "명사 insurer의 복수형"}, {"w": "insolvent", "m": "지급 불능의, 파산한"}, {"w": "cascade", "m": "연쇄적으로 일어나다", "form": "cascading", "note": "동사 cascade의 현재분사형(뒤의 명사 failures를 꾸미는 형용사 역할)"}, {"w": "collective", "m": "집단적인"}, {"w": "pull out", "m": "인출하다, 빼내다"}, {"w": "distress", "m": "고통, 곤경"}, {"w": "self-fulfilling", "m": "자기충족적인(예상이 스스로 현실이 되는)"}, {"w": "troublesome", "m": "골치 아픈, 성가신"}], "qa": [{"chunk": 1, "q": "본문에서 금융상의 실패가 채무자에서 은행, 보험사로 퍼지는 모습을 무엇에 비유했는가?", "opts": ["산불", "홍수", "독감"], "ans": 2, "why": ["2번 문장에서 금융상의 실패가 독감처럼(like a flu) 퍼진다고 함.", "산불과 홍수는 지문에 나오지 않음."], "ev_en": "A financial failure can make its way from borrowers to banks to insurers, spreading like a flu.", "ev_ko": "금융상의 실패는 독감처럼 퍼지면서 채무자에서부터 은행, 보험사까지 나아갈 수 있다."}, {"chunk": 2, "q": "3번 문장 이후에 설명하는 시장 감염의 예상치 못한 특징은 무엇인가?", "opts": ["은행은 투자가 모두 실패한 경우에만 지급 불능이 된다.", "감염은 반드시 직접적인 접촉이 있어야 일어난다.", "은행이 투자 중 어느 하나도 실패하지 않고도 지급 불능이 될 수 있다."], "ans": 2, "why": ["4번 문장에서 감염은 어떤 접촉 없이도 일어날 수 있다고 함.", "5번 문장에서 은행은 투자 중 어느 하나도 실패하지 않고도 지급 불능이 될 수 있다고 함.", "나머지 두 보기는 이 내용과 반대임."], "ev_en": "A bank might become insolvent even without having any of its investments fail.", "ev_ko": "은행은 심지어 투자 중 어느 하나도 실패하지 않고도 지급 불능이 될 수 있다."}, {"chunk": 3, "q": "은행이 건전하게 운영된다는 것을 알아도 사람들이 돈을 인출하려는 이유는 무엇인가?", "opts": ["돈을 인출하는 마지막 사람이 되는 것이 두렵기 때문에", "은행이 이자를 올렸기 때문에", "정부가 인출을 요구했기 때문에"], "ans": 0, "why": ["9번 문장에서 다른 사람들이 돈을 뺄 것으로 예상하면 자신이 마지막으로 인출하는 사람이 되는 것을 무서워한다고 함.", "이자나 정부의 요구는 지문에 나오지 않음."], "ev_en": "We might all even know that Bank X was well-managed with healthy investments, but if we expected others to pull their money out, then we would fear being the last to pull our money out.", "ev_ko": "우리 모두가 심지어 X은행이 건전한 투자로 잘 운영된다는 것을 알지라도, 만약 우리가 다른 사람들이 그들의 돈을 인출해 갈 것이라고 예상한다면, 그러면 우리는 자신의 돈을 인출하는 마지막 사람이 되는 것을 무서워할 것이다."}], "tf": [{"s": "감염은 어떤 접촉 없이도 일어날 수 있다.", "t": true, "why": ["4번 문장의 내용과 일치함."], "ev_en": "Infection can occur even without any contact.", "ev_ko": "감염이 심지어 어떤 접촉 없이도 일어날 수 있다."}, {"s": "은행이 지급 불능이 되려면 투자 중 적어도 하나는 반드시 실패해야 한다.", "t": false, "why": ["틀린 부분은 \"적어도 하나는 반드시 실패\"임.", "5번 문장에서 은행은 투자 중 어느 하나도 실패하지 않고도 지급 불능이 될 수 있다고 함."], "ev_en": "A bank might become insolvent even without having any of its investments fail.", "ev_ko": "은행은 심지어 투자 중 어느 하나도 실패하지 않고도 지급 불능이 될 수 있다."}, {"s": "두려움과 불확실성은 나쁜 투자로 인한 연속된 실패처럼 금융 시장에 손해를 끼칠 수 있다.", "t": true, "why": ["6번 문장의 내용과 일치함."], "ev_en": "Fear and uncertainty can be damaging to financial markets, just as cascading failures due to bad investments.", "ev_ko": "나쁜 투자들 때문에 일어나는 연속된 실패가 그러하듯, 두려움과 불확실성은 금융 시장에 손해를 끼칠 수 있다."}, {"s": "은행이 건전하게 운영된다는 것을 알면, 남들이 돈을 뺄 것으로 예상해도 사람들은 돈을 인출하는 마지막 사람이 되는 것을 두려워하지 않는다.", "t": false, "why": ["틀린 부분은 \"두려워하지 않는다\"임.", "9번 문장에서 은행이 건전하다는 것을 알더라도 다른 사람들이 돈을 뺄 것으로 예상하면 마지막으로 인출하게 될까 두려워한다고 함."], "ev_en": "We might all even know that Bank X was well-managed with healthy investments, but if we expected others to pull their money out, then we would fear being the last to pull our money out.", "ev_ko": "우리 모두가 심지어 X은행이 건전한 투자로 잘 운영된다는 것을 알지라도, 만약 우리가 다른 사람들이 그들의 돈을 인출해 갈 것이라고 예상한다면, 그러면 우리는 자신의 돈을 인출하는 마지막 사람이 되는 것을 무서워할 것이다."}, {"s": "재정적인 고통은 자기충족적일 수 있다.", "t": true, "why": ["10번 문장의 내용과 일치함."], "ev_en": "Financial distress can be self-fulfilling and is a particularly troublesome aspect of financial markets.", "ev_ko": "재정적인 고통은 자기충족적일 수 있고 금융 시장에서의 특별히 골치 아픈 측면이다."}], "flow": {"fixed": "전 세계 경제 시장은 서로 연결되어 있어 감염에 취약하며, 금융상의 실패는 독감처럼 채무자에서 은행, 보험사로 퍼질 수 있다.", "order": ["그러나 시장의 감염에는 예상치 못한 특징이 있어서, 접촉이 없어도 일어나고 투자가 하나도 실패하지 않아도 은행이 지급 불능이 될 수 있다.", "이처럼 두려움과 불확실성만으로도 금융 시장은 손해를 입으며, 우리 모두가 은행이 지급 불능이 되리라 믿거나 남들이 그렇게 믿는다고 두려워하면 실제로 그렇게 된다.", "심지어 은행이 건전하다는 것을 알아도 남들이 돈을 뺄 것 같으면 마지막으로 인출하게 될까 두려워하게 되어, 결국 재정적 고통은 자기충족적일 수 있다."], "clue": ["\"그러나 ... 예상치 못한 특징\"이 앞의 감염 설명을 뒤집어 새로운 면을 소개함", "\"이처럼\"이 앞의 접촉\u00b7투자 실패 없는 감염 사례를 받아 두려움이라는 원인으로 설명함", "\"심지어 ... 알아도\"와 \"결국\"이 앞의 믿음 이야기를 끝까지 밀고 가 결론을 맺음"], "why": ["연결된 시장의 감염 -> 접촉\u00b7투자 실패 없는 감염 -> 두려움이 만드는 지급 불능 -> 건전해도 일어나는 인출 쏠림과 자기충족성 순서임."], "cards": ["그러나 시장의 감염에는 예상치 못한 특징이 있어서, 접촉이 없어도 일어나고 투자가 하나도 실패하지 않아도 은행이 지급 불능이 될 수 있다.", "심지어 은행이 건전하다는 것을 알아도 남들이 돈을 뺄 것 같으면 마지막으로 인출하게 될까 두려워하게 되어, 결국 재정적 고통은 자기충족적일 수 있다.", "이처럼 두려움과 불확실성만으로도 금융 시장은 손해를 입으며, 우리 모두가 은행이 지급 불능이 되리라 믿거나 남들이 그렇게 믿는다고 두려워하면 실제로 그렇게 된다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "The connectedness of the global economic market makes it vulnerable to potential \u201cinfection.\u201d", "ko": "전 세계 경제 시장의 연결성은 그것을 잠재적 \u2018감염\u2019에 취약하게 만든다."}, {"n": 2, "en": "A financial failure can make its way from borrowers to banks to insurers, spreading like a flu.", "ko": "금융상의 실패는 독감처럼 퍼지면서 채무자에서부터 은행, 보험사까지 나아갈 수 있다."}, {"n": 3, "en": "However, there are unexpected characteristics when it comes to such infection in the market.", "ko": "그러나 시장에서의 그러한 감염에 관한 예상치 못한 특징들이 있다."}, {"n": 4, "en": "Infection can occur even without any contact.", "ko": "감염이 심지어 어떤 접촉 없이도 일어날 수 있다."}, {"n": 5, "en": "A bank might become insolvent even without having any of its investments fail.", "ko": "은행은 심지어 투자 중 어느 하나도 실패하지 않고도 지급 불능이 될 수 있다."}, {"n": 6, "en": "Fear and uncertainty can be damaging to financial markets, just as cascading failures due to bad investments.", "ko": "나쁜 투자들 때문에 일어나는 연속된 실패가 그러하듯, 두려움과 불확실성은 금융 시장에 손해를 끼칠 수 있다."}, {"n": 7, "en": "If we all woke up tomorrow and believed that Bank X would be insolvent, then it would become insolvent.", "ko": "만약 우리 모두가 내일 깨어나서 X은행이 지급 불능이 될 것이라고 믿는다면, 그것은 지급 불능이 될 것이다."}, {"n": 8, "en": "In fact, it would be enough for us to fear that others believed that Bank X was going to fail, or just to fear our collective fear!", "ko": "사실 우리가 다른 사람들이 X은행이 실패할 것이라고 믿고 있다는 것을 무서워하거나 단지 우리의 집단적인 두려움을 무서워하는 것으로 충분할 것이다."}, {"n": 9, "en": "We might all even know that Bank X was well-managed with healthy investments, but if we expected others to pull their money out, then we would fear being the last to pull our money out.", "ko": "우리 모두가 심지어 X은행이 건전한 투자로 잘 운영된다는 것을 알지라도, 만약 우리가 다른 사람들이 그들의 돈을 인출해 갈 것이라고 예상한다면, 그러면 우리는 자신의 돈을 인출하는 마지막 사람이 되는 것을 무서워할 것이다."}, {"n": 10, "en": "Financial distress can be self-fulfilling and is a particularly troublesome aspect of financial markets.", "ko": "재정적인 고통은 자기충족적일 수 있고 금융 시장에서의 특별히 골치 아픈 측면이다."}]}, {"id": "2211-33", "short": "22년 11월 33번", "group": "22년 11월", "num": 33, "topic_ko": "음수가 불쾌해서 기호를 피하려는 사람들의 전략", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 1, "summary_ko": "음수는 양수보다 추상적이지만 일상에서 생각해야 함"}, {"n": 2, "label": "중심 내용", "from": 2, "to": 3, "summary_ko": "많은 사람이 음수와 잘 지내지 못해 음수 기호를 피하는 전략을 만들어 냄"}, {"n": 3, "label": "뒷받침", "from": 4, "to": 8, "summary_ko": "펀드 손실, 역사, 지하층, 기온 표현 등에서 음수 기호를 피하며 기호는 불쾌해 보임"}], "gloss": [{"w": "negative number", "m": "음수", "form": "negative numbers", "note": "명사 number의 복수형"}, {"w": "abstract", "m": "추상적인"}, {"w": "debt", "m": "빚, 채무", "form": "debts", "note": "명사 debt의 복수형"}, {"w": "contend with", "m": "~와 씨름하다, 맞서다", "form": "contending with", "note": "동사 contend의 동명사형(전치사 to 뒤)"}, {"w": "freezing", "m": "몹시 차가운"}, {"w": "make peace with", "m": "~와 화해하다, ~을 받아들이다(여기서는 음수와 잘 지내다)", "form": "made peace with", "note": "동사 make의 과거분사형(haven't made = 현재완료 부정)"}, {"w": "invent", "m": "만들어 내다, 고안하다", "form": "invented", "note": "동사 invent의 과거분사형(have invented = 현재완료)"}, {"w": "sidestep", "m": "피하다"}, {"w": "dread", "m": "두려워하다", "form": "dreaded", "note": "동사 dread의 과거분사형이 형용사처럼 쓰여 '두려운'이라는 뜻이 됨"}, {"w": "loss", "m": "손실", "form": "losses", "note": "명사 loss의 복수형"}, {"w": "parenthesis", "m": "괄호", "form": "parentheses", "note": "명사 parenthesis의 복수형(-is가 -es로 바뀜)"}, {"w": "designation", "m": "명칭, 표시", "form": "designations", "note": "명사 designation의 복수형"}, {"w": "exception", "m": "예외", "form": "exceptions", "note": "명사 exception의 복수형"}, {"w": "unpleasant", "m": "불쾌한"}], "qa": [{"chunk": 1, "q": "첫 문장의 핵심 내용으로 알맞은 것은?", "opts": ["음수는 양수보다 구체적이어서 일상에서 쉽게 쓰인다.", "음수는 양수보다 추상적이지만 일상생활 모든 면에서 생각해야 한다.", "음수는 일상에서 거의 쓰이지 않아 몰라도 된다."], "ans": 1, "why": ["1번 문장이 근거이다.", "음수는 양수보다 훨씬 더 추상적이다(a lot more abstract)라고 한다.", "그래도 일상생활의 모든 측면에서(in all aspects of daily life) 음수를 생각해야 한다고 한다.", "\u201c음수가 구체적이어서 쉽게 쓰인다\u201d는 진술은 지문과 반대이다.", "\u201c음수는 거의 쓰이지 않아 몰라도 된다\u201d는 진술도 일상에서 생각해야 한다는 말과 어긋난다."], "ev_en": "Negative numbers are a lot more abstract than positive numbers\u2014you can\u2019t see negative 4 cookies and you certainly can\u2019t eat them\u2014but you can think about them, and you have to, in all aspects of daily life, from debts to contending with freezing temperatures and parking garages.", "ev_ko": "여러분이 음수의 4개의 쿠키를 볼 수 없고 틀림없이 그것들을 먹을 수 없다는 점에서 음수는 양수보다 훨씬 더 추상적이지만 여러분은 그것들을 생각할 수 있으며, 채무에서부터 몹시 차가운 기온, 주차장과 씨름하는 것에 이르기까지 일상생활의 모든 측면에서 생각\u2018해야만 한다\u2019."}, {"chunk": 2, "q": "음수와 잘 지내지 못하는 사람들이 한 일은?", "opts": ["음수를 아예 배우지 않으려 했다.", "음수 기호를 피하기 위한 여러 정신적 전략을 만들어 냈다.", "음수를 양수로 바꾸는 법을 만들어 냈다."], "ans": 1, "why": ["3번 문장이 근거이다.", "사람들은 두려운 음수 기호를 피하려는(to sidestep the dreaded negative sign) 전략을 만들어 냈다.", "funny little mental strategies(우스꽝스럽고 사소한 정신적 전략)라고 표현한다.", "\u201c음수를 아예 배우지 않으려 했다\u201d는 진술은 지문에 없다.", "\u201c음수를 양수로 바꾸는 법을 만들어 냈다\u201d는 진술도 지문에 없다. 피하는 대상은 음수 자체가 아니라 음수 기호이다."], "ev_en": "People have invented all sorts of funny little mental strategies to sidestep the dreaded negative sign.", "ev_ko": "사람들은 그 두려운 음수의 기호를 피하기 위해 모든 종류의 우스꽝스럽고 사소한 정신적 전략들을 만들어 냈다."}, {"chunk": 3, "q": "뒷받침 예시들이 공통으로 보여 주는 것은?", "opts": ["음수는 금융 분야에서만 쓰인다.", "음수 기호를 쓰면 계산이 훨씬 쉬워진다.", "사람들은 음수 기호를 쓰는 것을 피하려고 한다."], "ans": 2, "why": ["펀드 손실은 빨간색이나 괄호로 표시해 음수 기호를 쓰지 않음.", "역사책의 기원전 100년(100 B.C.), 주차장의 B1\u00b7B2(지하 1층\u00b7지하 2층 표시)도 음수 기호를 피한 표현임.", "기온은 -5도라고 말하는 사람도 있지만 5 below zero(영하 5도)를 선호하는 사람이 많음.", "8번 문장은 앞의 예시들을 묶어 음수 기호 자체가 불쾌하다는 공통 이유를 말해 주는 근거임.", "\u201c금융 분야에서만 쓰인다\u201d는 진술은 역사\u00b7주차장\u00b7기온 예시와 맞지 않고 지문에도 없음.", "\u201c계산이 훨씬 쉬워진다\u201d는 진술도 지문에 없음."], "ev_en": "There\u2019s something about that negative sign that just looks so unpleasant.", "ev_ko": "그 음수의 기호에 관해서는 정말 불쾌하게만 보이는 무언가가 있다."}], "tf": [{"s": "\u2018-4개의 쿠키\u2019처럼 음수로 된 양은 눈으로 볼 수 없다.", "t": true, "why": ["1번 문장이 근거이다.", "you can\u2019t see negative 4 cookies(음수 4개의 쿠키를 볼 수 없다)고 한다.", "음수가 양수보다 훨씬 더 추상적인 예로 든 말이다.", "지문 내용과 일치함."], "ev_en": "Negative numbers are a lot more abstract than positive numbers\u2014you can\u2019t see negative 4 cookies and you certainly can\u2019t eat them\u2014but you can think about them, and you have to, in all aspects of daily life, from debts to contending with freezing temperatures and parking garages.", "ev_ko": "여러분이 음수의 4개의 쿠키를 볼 수 없고 틀림없이 그것들을 먹을 수 없다는 점에서 음수는 양수보다 훨씬 더 추상적이지만 여러분은 그것들을 생각할 수 있으며, 채무에서부터 몹시 차가운 기온, 주차장과 씨름하는 것에 이르기까지 일상생활의 모든 측면에서 생각\u2018해야만 한다\u2019."}, {"s": "많은 사람은 이제 음수와 완전히 잘 지내게 되었다.", "t": false, "why": ["2번 문장은 many of us haven\u2019t quite made peace with negative numbers(우리 중 많은 사람은 음수와 아직 완전히 잘 지내지는 못했다)라고 한다.", "올바른 내용은 음수를 아직 받아들이지 못한 사람이 많다는 것임."], "ev_en": "Still, many of us haven\u2019t quite made peace with negative numbers.", "ev_ko": "여전히 우리들 중 많은 사람들은 음수와 잘 지내지 못해 왔다."}, {"s": "뮤추얼 펀드 진술에서 손실은 음수 기호를 붙여 표시한다.", "t": false, "why": ["4번 문장은 손실이 빨간색으로 인쇄되거나 괄호 안에 들어간다고 한다.", "with no negative sign to be found(음수 기호가 발견되지 않음)가 핵심이므로 틀림.", "올바른 내용은 음수 기호 없이 빨간색이나 괄호로 표시한다는 것임."], "ev_en": "On mutual fund statements, losses (negative numbers) are printed in red or stuck in parentheses with no negative sign to be found.", "ev_ko": "뮤추얼 펀드(계약형 투자 신탁) 진술에서 손실(음수)은 빨간색으로 인쇄되거나 음수의 기호가 발견되지 않은 채 괄호 안에 갇혀 있다."}, {"s": "역사책은 Julius Caesar가 \u2013100년에 태어났다고 말한다.", "t": false, "why": ["5번 문장은 born in 100 B.C., not \u2013100(\u2013100이 아닌 기원전 100년에 태어났다)이라고 한다.", "올바른 내용은 음수 표기 대신 기원전 100년이라고 쓴다는 것임."], "ev_en": "The history books tell us that Julius Caesar was born in 100 B.C., not \u2011100.", "ev_ko": "역사책은 우리에게 Julius Caesar가 \u2013100이 아닌 기원전 100년에 태어났다고 말한다."}, {"s": "음수 기호에는 정말 불쾌하게 보이는 무언가가 있다고 한다.", "t": true, "why": ["8번 문장이 근거이다.", "that negative sign that just looks so unpleasant(정말 불쾌하게만 보이는 그 음수 기호)라고 한다.", "사람들이 음수 기호를 피하려는 이유를 정리한 문장임.", "지문 내용과 일치함."], "ev_en": "There\u2019s something about that negative sign that just looks so unpleasant.", "ev_ko": "그 음수의 기호에 관해서는 정말 불쾌하게만 보이는 무언가가 있다."}], "flow": {"fixed": "음수는 양수보다 훨씬 추상적이지만, 우리는 일상생활의 모든 면에서 음수를 생각해야 한다.", "order": ["그런데도 우리 중 많은 사람은 여전히 음수와 잘 지내지 못한다.", "그래서 사람들은 그 두려운 음수 기호를 피하려고 온갖 우스꽝스럽고 사소한 정신적 전략을 만들어 냈다.", "예를 들어 펀드 손실은 빨간색이나 괄호로, 역사는 기원전 100년으로 표현하고, 기온도 -5도라고 말하는 사람이 있기는 하지만 많은 사람이 영하 5도라고 말하길 선호하는데, 음수 기호가 그만큼 불쾌해 보이기 때문이다."], "clue": ["'그런데도'는 필요하다는 앞 내용과 대비되는 현실을 이끎", "'그래서'는 잘 지내지 못하는 상황의 결과를 이끎", "'예를 들어'는 앞의 전략들을 구체적으로 보여 줌"], "why": ["필요하지만 불편하다, 그래서 피하는 전략이 생겼다, 예시 순으로 흐름."], "cards": ["예를 들어 펀드 손실은 빨간색이나 괄호로, 역사는 기원전 100년으로 표현하고, 기온도 -5도라고 말하는 사람이 있기는 하지만 많은 사람이 영하 5도라고 말하길 선호하는데, 음수 기호가 그만큼 불쾌해 보이기 때문이다.", "그래서 사람들은 그 두려운 음수 기호를 피하려고 온갖 우스꽝스럽고 사소한 정신적 전략을 만들어 냈다.", "그런데도 우리 중 많은 사람은 여전히 음수와 잘 지내지 못한다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Negative numbers are a lot more abstract than positive numbers\u2014you can\u2019t see negative 4 cookies and you certainly can\u2019t eat them\u2014but you can think about them, and you have to, in all aspects of daily life, from debts to contending with freezing temperatures and parking garages.", "ko": "여러분이 음수의 4개의 쿠키를 볼 수 없고 틀림없이 그것들을 먹을 수 없다는 점에서 음수는 양수보다 훨씬 더 추상적이지만 여러분은 그것들을 생각할 수 있으며, 채무에서부터 몹시 차가운 기온, 주차장과 씨름하는 것에 이르기까지 일상생활의 모든 측면에서 생각\u2018해야만 한다\u2019."}, {"n": 2, "en": "Still, many of us haven\u2019t quite made peace with negative numbers.", "ko": "여전히 우리들 중 많은 사람들은 음수와 잘 지내지 못해 왔다."}, {"n": 3, "en": "People have invented all sorts of funny little mental strategies to sidestep the dreaded negative sign.", "ko": "사람들은 그 두려운 음수의 기호를 피하기 위해 모든 종류의 우스꽝스럽고 사소한 정신적 전략들을 만들어 냈다."}, {"n": 4, "en": "On mutual fund statements, losses (negative numbers) are printed in red or stuck in parentheses with no negative sign to be found.", "ko": "뮤추얼 펀드(계약형 투자 신탁) 진술에서 손실(음수)은 빨간색으로 인쇄되거나 음수의 기호가 발견되지 않은 채 괄호 안에 갇혀 있다."}, {"n": 5, "en": "The history books tell us that Julius Caesar was born in 100 B.C., not \u2011100.", "ko": "역사책은 우리에게 Julius Caesar가 \u2013100이 아닌 기원전 100년에 태어났다고 말한다."}, {"n": 6, "en": "The underground levels in a parking garage often have designations like B1 and B2.", "ko": "주차장의 지하층은 종종 B1과 B2와 같은 명칭을 가지고 있다."}, {"n": 7, "en": "Temperatures are one of the few exceptions: folks do say, especially here in Ithaca, New York, that it\u2019s \u20115 degrees outside, though even then, many prefer to say 5 below zero.", "ko": "기온은 몇 안 되는 예외 중 하나인데 특히 여기 New York의 Ithaca에서 사람들은 바깥의 기온이 \u20135도라고 말하지만 심지어 그때에도 많은 사람들은 영하 5도라고 말하길 선호한다."}, {"n": 8, "en": "There\u2019s something about that negative sign that just looks so unpleasant.", "ko": "그 음수의 기호에 관해서는 정말 불쾌하게만 보이는 무언가가 있다."}]}, {"id": "2211-34", "short": "22년 11월 34번", "group": "22년 11월", "num": 34, "topic_ko": "교란 변수가 인간 관찰 연구의 인과적 결론을 해침", "chunks": [{"n": 1, "label": "중심 내용", "from": 1, "to": 4, "summary_ko": "인간은 동질적이지 않아 교란 변수가 인과적 결론 도출 능력을 손상시킴"}, {"n": 2, "label": "뒷받침\u2460", "from": 5, "to": 8, "summary_ko": "교란 변수는 특정 변수의 영향을 분리하기 어렵게 하며 흡연이 예시"}, {"n": 3, "label": "뒷받침\u2461", "from": 9, "to": 10, "summary_ko": "알려진 교란 변수는 수정 가능하나 알려지지 않으면 신뢰성을 손상시킴"}], "gloss": [{"w": "observational", "m": "관찰의"}, {"w": "properly", "m": "적절하게"}, {"w": "insufficiently", "m": "불충분하게"}, {"w": "homogeneous", "m": "동질적인"}, {"w": "subject", "m": "(실험) 대상", "form": "subjects", "note": "명사 subject의 복수형"}, {"w": "confounding factor", "m": "교란 변수", "form": "confounding factors", "note": "명사 factor의 복수형"}, {"w": "undermine", "m": "손상시키다, 약화시키다"}, {"w": "causal", "m": "인과적인"}, {"w": "epidemiological", "m": "역학(\u75ab\u5b78)의"}, {"w": "isolate", "m": "분리하다"}, {"w": "correlation", "m": "상관관계"}, {"w": "coronary heart disease", "m": "관상 동맥성 심장 질환"}, {"w": "correct for", "m": "~을 보정하다, 수정하다", "form": "corrected for", "note": "8번 문장에서는 동사 correct의 과거형(corrected for), 9번 문장에서는 원형 그대로 쓰임"}, {"w": "reliability", "m": "신뢰성"}], "qa": [{"chunk": 1, "q": "인간에 대한 관찰 연구가 적절히 통제될 수 없는 이유는?", "opts": ["사람들이 서로 다른 생활 방식과 환경에서 살아 충분히 동질적이지 않아서", "연구에 참여하는 사람의 수가 너무 적어서", "연구자들이 인과적 결론을 내리지 않아서"], "ans": 0, "why": ["인간은 다양한 생활 방식으로, 다양한 환경에서 삶.", "그래서 insufficiently homogeneous(충분히 동질적이지 않음)하여 실험 대상으로 적합하지 않음.", "\u201c연구에 참여하는 사람의 수가 너무 적다\u201d는 말은 지문에 없음.", "\u201c연구자들이 인과적 결론을 내리지 않는다\u201d는 말도 지문에 없음."], "ev_en": "Thus, they are insufficiently homogeneous to be suitable experimental subjects.", "ev_ko": "따라서 그들은 적절한 실험 대상이 되기에 충분히 동질적이지 않다."}, {"chunk": 2, "q": "Framingham 연구에서 커피와 심장 질환의 상관관계 대부분이 사라진 이유는?", "opts": ["커피 마시는 사람의 수가 크게 줄었기 때문", "커피가 심장 질환을 예방한다는 것이 밝혀졌기 때문", "커피를 마시는 많은 사람이 흡연도 한다는 점을 보정했기 때문"], "ans": 2, "why": ["처음에는 커피와 심장 질환 사이에 상당한 상관관계가 확인됨.", "커피 마시는 사람 중 흡연자가 많다는 사실을 보정하자 대부분 사라짐.", "여기서 흡연이 교란 변수임.", "커피 마시는 사람의 수가 줄었다는 말도, 커피가 심장 질환을 예방한다는 말도 지문에 없음."], "ev_en": "However, most of this correlation disappeared once researchers corrected for the fact that many coffee drinkers also smoke.", "ev_ko": "그러나 연구자들이 커피를 마시는 많은 사람들이 흡연도 한다는 사실에 대해 수정을 하자 이러한 상관관계의 대부분은 사라졌다."}, {"chunk": 3, "q": "교란 변수가 알려져 있지 않을 때 어떻게 되는가?", "opts": ["인과적 결론의 신뢰성이 손상된다.", "쉽게 수정할 수 있다.", "연구 대상이 더 동질적이 된다."], "ans": 0, "why": ["10번 문장이 근거이다.", "교란 변수가 알려져 있지 않으면 if they are unknown, they will undermine the reliability(신뢰성을 손상시킬 것이다)라고 한다.", "\u201c쉽게 수정할 수 있다\u201d는 보기는 9번 문장의 알려진 경우의 이야기이다.", "\u201c연구 대상이 더 동질적이 된다\u201d는 보기는 지문에 없는 내용이다."], "ev_en": "However, if they are unknown, they will undermine the reliability of the causal conclusions we draw from epidemiological surveys.", "ev_ko": "그러나 그것들이 알려져 있지 않다면, 그것들은 우리가 역학 조사로부터 도출하는 인과적 결론의 신뢰성을 손상시킬 것이다."}], "tf": [{"s": "교란 변수는 인간 역학 조사에서 타당한 인과적 결론을 이끌어 내는 능력을 손상시킨다.", "t": true, "why": ["4번 문장이 근거이다.", "These confounding factors undermine our ability to draw sound causal conclusions(이러한 교란 변수는 타당한 인과적 결론을 도출하는 우리의 능력을 손상시킨다)라고 한다.", "지문 내용과 일치함."], "ev_en": "These confounding factors undermine our ability to draw sound causal conclusions from human epidemiological surveys.", "ev_ko": "이러한 \u2018교란 변수\u2019는 인간 역학 조사로부터 타당한 인과적 결론을 도출하는 우리의 능력을 손상시킨다."}, {"s": "교란 변수는 모두 연구자에게 알려져 있다.", "t": false, "why": ["5번 문장은 교란 변수를 variables (known or unknown)(알려지거나 알려지지 않은 변수)라고 정의한다.", "올바른 내용은 알려지지 않은 교란 변수도 있다는 것이다."], "ev_en": "Confounding factors are variables (known or unknown) that make it difficult for epidemiologists to isolate the effects of the specific variable being studied.", "ev_ko": "교란 변수는 역학자가 연구되고 있는 특정한 변수의 영향을 분리하기 어렵게 만드는 (알려지거나 알려지지 않은) 변수이다."}, {"s": "Taubes는 술을 마시는 사람 중에 흡연자가 많아 알코올과 암의 연관성을 판단하기 어렵다고 주장했다.", "t": true, "why": ["6번 문장이 근거이다.", "many people who drink also smoke(술을 마시는 많은 사람이 흡연도 한다)는 점이 교란 변수이다.", "그래서 알코올 섭취와 암의 연관성을 판단하기 어렵다고 Taubes는 주장했다.", "지문 내용과 일치함."], "ev_en": "For example, Taubes argued that since many people who drink also smoke, researchers have difficulty determining the link between alcohol consumption and cancer.", "ev_ko": "예를 들어, Taubes는 술을 마시는 많은 사람들이 흡연도 하기 때문에 연구자들이 알코올 섭취와 암 사이의 연관성을 결정짓는 데 어려움을 겪는다고 주장했다."}, {"s": "Framingham 연구에서는 커피와 관상 동맥성 심장 질환 사이에 상관관계가 전혀 확인되지 않았다.", "t": false, "why": ["7번 문장은 identified a significant correlation(상당한 상관관계를 확인했다)이라고 한다.", "그래서 전혀 확인되지 않았다는 말은 틀림.", "올바른 내용은 상당한 상관관계가 확인되었다가 흡연을 보정하자 대부분 사라졌다는 것임."], "ev_en": "Similarly, researchers in the famous Framingham study identified a significant correlation between coffee drinking and coronary heart disease.", "ev_ko": "마찬가지로 유명한 Framingham 연구의 연구자들은 커피를 마시는 것과 관상 동맥성 심장 질환 사이에 상당한 상관관계를 확인했다."}, {"s": "교란 변수가 알려져 있다면 그것을 수정하는 것이 종종 가능하다.", "t": true, "why": ["9번 문장이 근거이다.", "it is often possible to correct for them(그것들을 수정하는 것이 종종 가능하다)이라고 한다.", "단, 알려져 있지 않은 경우에는 신뢰성을 해친다는 10번 문장과 대비해 기억할 것."], "ev_en": "If the confounding factors are known, it is often possible to correct for them.", "ev_ko": "교란 변수들이 알려져 있다면 그것들을 수정하는 것이 종종 가능하다."}], "flow": {"fixed": "인간에 대한 관찰 연구는 적절하게 통제될 수 없는데, 사람마다 생활 방식과 환경이 달라 실험 대상으로 삼기에 충분히 동질적이지 않기 때문이다.", "order": ["사람마다 생활 방식과 환경이 다르다는 점에서 생기는 요인을 \u2018교란 변수\u2019라 하며, 이는 연구되는 변수의 영향을 분리하기 어렵게 만들어 타당한 인과적 결론을 이끌어 내는 능력을 손상시킨다.", "이런 교란 변수의 예로, 술 마시는 사람 중에는 흡연자가 많아 알코올과 암의 연관성을 판단하기 어렵고, 커피와 심장 질환의 상관관계도 흡연을 보정하자 대부분 사라졌다.", "앞의 사례처럼 교란 변수가 알려져 있으면 종종 보정할 수 있지만, 알려져 있지 않으면 우리가 내리는 인과적 결론의 신뢰성이 손상된다."], "clue": ["\u2018교란 변수\u2019라는 용어를 처음 정의하며 소개함", "\u2018이런 교란 변수의 예로\u2019는 정의 뒤에만 올 수 있음", "\u2018앞의 사례처럼\u2019은 예시가 나온 뒤에만 올 수 있고, 알려진 경우와 알려지지 않은 경우를 대비해 마무리함"], "why": ["통제 불가 이유, 교란 변수 정의, 예시, 알려짐 여부에 따른 결과 순으로 흐름."], "cards": ["사람마다 생활 방식과 환경이 다르다는 점에서 생기는 요인을 \u2018교란 변수\u2019라 하며, 이는 연구되는 변수의 영향을 분리하기 어렵게 만들어 타당한 인과적 결론을 이끌어 내는 능력을 손상시킨다.", "앞의 사례처럼 교란 변수가 알려져 있으면 종종 보정할 수 있지만, 알려져 있지 않으면 우리가 내리는 인과적 결론의 신뢰성이 손상된다.", "이런 교란 변수의 예로, 술 마시는 사람 중에는 흡연자가 많아 알코올과 암의 연관성을 판단하기 어렵고, 커피와 심장 질환의 상관관계도 흡연을 보정하자 대부분 사라졌다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "Observational studies of humans cannot be properly controlled.", "ko": "인간에 대한 관찰 연구는 적절하게 통제될 수 없다."}, {"n": 2, "en": "Humans live different lifestyles and in different environments.", "ko": "인간은 다양한 생활 방식으로 그리고 다양한 환경에서 살고 있다."}, {"n": 3, "en": "Thus, they are insufficiently homogeneous to be suitable experimental subjects.", "ko": "따라서 그들은 적절한 실험 대상이 되기에 충분히 동질적이지 않다."}, {"n": 4, "en": "These confounding factors undermine our ability to draw sound causal conclusions from human epidemiological surveys.", "ko": "이러한 \u2018교란 변수\u2019는 인간 역학 조사로부터 타당한 인과적 결론을 도출하는 우리의 능력을 손상시킨다."}, {"n": 5, "en": "Confounding factors are variables (known or unknown) that make it difficult for epidemiologists to isolate the effects of the specific variable being studied.", "ko": "교란 변수는 역학자가 연구되고 있는 특정한 변수의 영향을 분리하기 어렵게 만드는 (알려지거나 알려지지 않은) 변수이다."}, {"n": 6, "en": "For example, Taubes argued that since many people who drink also smoke, researchers have difficulty determining the link between alcohol consumption and cancer.", "ko": "예를 들어, Taubes는 술을 마시는 많은 사람들이 흡연도 하기 때문에 연구자들이 알코올 섭취와 암 사이의 연관성을 결정짓는 데 어려움을 겪는다고 주장했다."}, {"n": 7, "en": "Similarly, researchers in the famous Framingham study identified a significant correlation between coffee drinking and coronary heart disease.", "ko": "마찬가지로 유명한 Framingham 연구의 연구자들은 커피를 마시는 것과 관상 동맥성 심장 질환 사이에 상당한 상관관계를 확인했다."}, {"n": 8, "en": "However, most of this correlation disappeared once researchers corrected for the fact that many coffee drinkers also smoke.", "ko": "그러나 연구자들이 커피를 마시는 많은 사람들이 흡연도 한다는 사실에 대해 수정을 하자 이러한 상관관계의 대부분은 사라졌다."}, {"n": 9, "en": "If the confounding factors are known, it is often possible to correct for them.", "ko": "교란 변수들이 알려져 있다면 그것들을 수정하는 것이 종종 가능하다."}, {"n": 10, "en": "However, if they are unknown, they will undermine the reliability of the causal conclusions we draw from epidemiological surveys.", "ko": "그러나 그것들이 알려져 있지 않다면, 그것들은 우리가 역학 조사로부터 도출하는 인과적 결론의 신뢰성을 손상시킬 것이다."}]}, {"id": "2211-35", "short": "22년 11월 35번", "group": "22년 11월", "num": 35, "topic_ko": "질투를 직접 표현하지 않고 스스로에게도 감추려 하는 이유", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "질투는 알아차리기 어려운데, 우리가 질투를 직접 표현하는 경우가 거의 없기 때문임"}, {"n": 2, "label": "전개", "from": 4, "to": 5, "summary_ko": "질투는 열등하다는 인정을 수반해 고통스럽고, 남이 알게 되는 것은 더 나쁨"}, {"n": 3, "label": "결론", "from": 6, "to": 7, "summary_ko": "질투심이 생기면 거의 즉시 불공평함이나 분노로 스스로에게 감추려 함(6번 문장은 질병 이야기로 흐름과 무관한 문장)"}], "gloss": [{"w": "envy", "m": "질투, 부러워하다"}, {"w": "tricky", "m": "까다로운", "form": "trickier", "note": "형용사 tricky의 비교급"}, {"w": "elusive", "m": "이해하기 어려운, 모호한"}, {"w": "discern", "m": "알아차리다, 식별하다"}, {"w": "motivate", "m": "자극하다, 동기를 부여하다", "form": "motivates", "note": "동사 motivate의 3인칭 단수 현재형(주어 the envy가 단수)"}, {"w": "entail", "m": "수반하다", "form": "entails", "note": "동사 entail의 3인칭 단수 현재형(주어 Envy가 단수)"}, {"w": "admission", "m": "인정"}, {"w": "inferior", "m": "열등한"}, {"w": "disguise", "m": "감추다, 위장하다"}, {"w": "unfairness", "m": "불공평함"}, {"w": "distribution", "m": "분배"}, {"w": "resentment", "m": "분개, 억울한 감정"}], "qa": [{"chunk": 1, "q": "본문에서 질투를 실제로 알아차리기 어려운 이유로 든 것은 무엇인가?", "opts": ["질투는 아주 드물게만 생기는 감정이기 때문에", "우리가 느끼는 질투를 직접적으로 표현하는 경우가 거의 없기 때문에", "사람들이 질투를 숨길 필요를 느끼지 못하기 때문에"], "ans": 1, "why": ["3번 문장에서 모호함의 이유는 우리가 느끼는 질투를 직접 표현하는 경우가 거의 없기 때문이라고 함.", "질투가 드물다거나 숨길 필요가 없다는 내용은 지문과 맞지 않음."], "ev_en": "The reason for this elusiveness is simple: we almost never directly express the envy we are feeling.", "ev_ko": "이러한 모호함의 이유는 간단한데, 우리는 우리가 느끼고 있는 질투를 직접적으로 표현하는 경우가 거의 없다."}, {"chunk": 2, "q": "본문에서 질투가 수반한다고 한 스스로에 대한 인정은 무엇인가?", "opts": ["남이 나보다 더 가치 없는 일을 한다는 인정", "내가 다른 사람보다 모든 면에서 우월하다는 인정", "가치 있게 여기는 무언가에서 내가 다른 사람보다 열등하다는 인정"], "ans": 2, "why": ["4번 문장에서 질투는 우리가 가치 있게 여기는 무언가에서 다른 사람보다 열등하다는 인정을 수반한다고 함.", "우월하다는 인정은 정반대이고, 남의 일이 가치 없다는 내용은 지문에 없음."], "ev_en": "Envy entails the admission to ourselves that we are inferior to another person in something we value.", "ev_ko": "질투는 우리가 가치 있게 여기는 무언가에서 우리가 다른 사람보다 열등하다는 스스로에 대한 인정을 수반한다."}, {"chunk": 3, "q": "최초의 질투심을 경험한 직후 우리가 하려는 행동은 무엇인가?", "opts": ["질투를 그 사람에게 곧바로 직접 표현한다.", "질투를 스스로에게 감추려 하며 불공평함이나 분노라고 느낀다.", "질투의 대상이 된 사람에게 사과한다."], "ans": 1, "why": ["7번 문장에서 최초의 질투심을 경험하는 거의 즉시 그것을 자신에게 감추려 한다고 함.", "우리가 느끼는 것은 질투가 아니라 불공평함, 분개, 분노라고 여기게 된다는 내용임.", "6번 문장은 질병 이야기로 흐름에서 벗어난 문장이라 근거로 쓰지 않음."], "ev_en": "And so almost as soon as we experience the initial feelings of envy, we are motivated to disguise it to ourselves \u2014 it is not envy we feel but unfairness at the distribution of goods or attention, resentment at this unfairness, even anger.", "ev_ko": "그래서 우리가 최초의 질투심을 경험하는 거의 즉시, 우리는 그것을 우리 자신에게 감추고자 하게 되는데, 즉 우리가 느끼는 것은 질투가 아니라 재산이나 관심의 분배에 대한 불공평함, 이 불공평함에 대한 분개, 심지어 분노이다."}], "tf": [{"s": "우리는 우리가 느끼고 있는 질투를 직접적으로 표현하는 경우가 거의 없다.", "t": true, "why": ["3번 문장의 내용과 일치함."], "ev_en": "The reason for this elusiveness is simple: we almost never directly express the envy we are feeling.", "ev_ko": "이러한 모호함의 이유는 간단한데, 우리는 우리가 느끼고 있는 질투를 직접적으로 표현하는 경우가 거의 없다."}, {"s": "사람들의 행동을 자극하는 질투를 실제로 알아차리는 것은 쉬운 일이다.", "t": false, "why": ["틀린 부분은 \"쉬운 일\"임.", "2번 문장에서 사람들의 행동을 자극하는 질투를 실제로 알아차리는 것은 매우 어렵다고 함."], "ev_en": "It is very difficult to actually discern the envy that motivates people\u2019s actions.", "ev_ko": "사람들의 행동을 자극하는 질투를 실제로 알아차리는 것은 매우 어렵다."}, {"s": "열등감을 인정하는 것은 고통스러울 뿐 아니라, 다른 사람들이 우리의 그런 감정을 알게 되는 것은 훨씬 더 나쁘다.", "t": true, "why": ["5번 문장의 내용과 일치함."], "ev_en": "Not only is it painful to admit this inferiority, but it is even worse for others to see that we are feeling this.", "ev_ko": "이 열등감을 인정하는 것은 고통스러울 뿐만 아니라, 우리가 이것을 느끼고 있다는 것을 다른 사람들이 알게 되는 것은 훨씬 더 나쁘다."}, {"s": "질투는 우리가 다른 사람보다 우월하다는 스스로에 대한 인정을 수반한다.", "t": false, "why": ["틀린 부분은 \"우월하다\"임.", "4번 문장에서 질투는 우리가 다른 사람보다 열등하다는 인정을 수반한다고 함."], "ev_en": "Envy entails the admission to ourselves that we are inferior to another person in something we value.", "ev_ko": "질투는 우리가 가치 있게 여기는 무언가에서 우리가 다른 사람보다 열등하다는 스스로에 대한 인정을 수반한다."}, {"s": "최초의 질투심을 경험하는 거의 즉시, 우리는 그것을 스스로에게 감추고자 하게 된다.", "t": true, "why": ["7번 문장의 내용과 일치함."], "ev_en": "And so almost as soon as we experience the initial feelings of envy, we are motivated to disguise it to ourselves \u2014 it is not envy we feel but unfairness at the distribution of goods or attention, resentment at this unfairness, even anger.", "ev_ko": "그래서 우리가 최초의 질투심을 경험하는 거의 즉시, 우리는 그것을 우리 자신에게 감추고자 하게 되는데, 즉 우리가 느끼는 것은 질투가 아니라 재산이나 관심의 분배에 대한 불공평함, 이 불공평함에 대한 분개, 심지어 분노이다."}], "flow": {"fixed": "질투는 인간의 감정 중 가장 알아차리기 어려운데, 우리가 느끼는 질투를 직접 표현하는 경우가 거의 없기 때문이다.", "order": ["질투는 우리가 가치 있게 여기는 무언가에서 다른 사람보다 열등하다고 스스로 인정하는 것을 수반한다.", "이 열등함을 인정하는 것은 고통스러울 뿐만 아니라, 남들이 우리의 이런 감정을 알게 되는 것은 훨씬 더 나쁘다.", "그래서 질투심이 처음 생기는 거의 즉시, 우리는 이를 스스로에게 감추려고 질투가 아니라 불공평함, 분개, 분노를 느낀다고 여긴다."], "clue": ["앞에서 말한 질투를 표현하지 않는 이유를 \"열등하다는 인정\"으로 설명하기 시작함", "\"이 열등함을 인정하는 것\"이 앞의 열등하다는 인정을 받아 그 고통을 말함", "\"그래서\"가 앞의 고통과 들키는 것의 문제에서 나온 결과(감추려는 행동)를 이끎"], "why": ["질투는 표현되지 않아 알기 어려움 -> 열등함의 인정 -> 인정도 노출도 고통 -> 그래서 스스로에게도 감춤 순서임."], "cards": ["그래서 질투심이 처음 생기는 거의 즉시, 우리는 이를 스스로에게 감추려고 질투가 아니라 불공평함, 분개, 분노를 느낀다고 여긴다.", "이 열등함을 인정하는 것은 고통스러울 뿐만 아니라, 남들이 우리의 이런 감정을 알게 되는 것은 훨씬 더 나쁘다.", "질투는 우리가 가치 있게 여기는 무언가에서 다른 사람보다 열등하다고 스스로 인정하는 것을 수반한다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Of all the human emotions, none is trickier or more elusive than envy.", "ko": "인간의 모든 감정 중에서 질투보다 더 까다롭거나 더 이해하기 어려운 것은 없다."}, {"n": 2, "en": "It is very difficult to actually discern the envy that motivates people\u2019s actions.", "ko": "사람들의 행동을 자극하는 질투를 실제로 알아차리는 것은 매우 어렵다."}, {"n": 3, "en": "The reason for this elusiveness is simple: we almost never directly express the envy we are feeling.", "ko": "이러한 모호함의 이유는 간단한데, 우리는 우리가 느끼고 있는 질투를 직접적으로 표현하는 경우가 거의 없다."}, {"n": 4, "en": "Envy entails the admission to ourselves that we are inferior to another person in something we value.", "ko": "질투는 우리가 가치 있게 여기는 무언가에서 우리가 다른 사람보다 열등하다는 스스로에 대한 인정을 수반한다."}, {"n": 5, "en": "Not only is it painful to admit this inferiority, but it is even worse for others to see that we are feeling this.", "ko": "이 열등감을 인정하는 것은 고통스러울 뿐만 아니라, 우리가 이것을 느끼고 있다는 것을 다른 사람들이 알게 되는 것은 훨씬 더 나쁘다."}, {"n": 6, "en": "Envy can cause illness because people with envy can cast the \u201cevil eye\u201d on someone they envy, even unwittingly, or the envious person can become ill from the emotion.", "ko": "질투는 질병을 유발할 수도 있는데, 왜냐하면 질투하는 사람이 무의식적으로라도 그들이 시기하는 사람에게 \u2018증오에 찬 눈초리\u2019를 보낼 수 있거나, 질투심이 강한 사람이 그 감정 때문에 건강이 나빠질 수 있기 때문이다."}, {"n": 7, "en": "And so almost as soon as we experience the initial feelings of envy, we are motivated to disguise it to ourselves \u2014 it is not envy we feel but unfairness at the distribution of goods or attention, resentment at this unfairness, even anger.", "ko": "그래서 우리가 최초의 질투심을 경험하는 거의 즉시, 우리는 그것을 우리 자신에게 감추고자 하게 되는데, 즉 우리가 느끼는 것은 질투가 아니라 재산이나 관심의 분배에 대한 불공평함, 이 불공평함에 대한 분개, 심지어 분노이다."}]}, {"id": "2211-36", "short": "22년 11월 36번", "group": "22년 11월", "num": 36, "topic_ko": "사생활 권리와 구별되는 잊힐 권리와 그 이유, 예외", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "잊힐 권리는 사생활 권리와 구별되지만 관련된 권리이며, 사생활 권리는 보호되는 정보가 공개되지 않을 권리임"}, {"n": 2, "label": "전개", "from": 3, "to": 6, "summary_ko": "잊힐 권리는 이미 공개된 정보에도 적용되며, 개인이 과거에 매이지 않고 삶을 이어 가게 하려는 것임"}, {"n": 3, "label": "한계", "from": 7, "to": 8, "summary_ko": "잊힐 권리도 다른 권리와 충돌할 수 있어 안보나 공공 보건 이유로 예외가 만들어짐"}], "gloss": [{"w": "distinct", "m": "구별되는, 별개의"}, {"w": "reveal", "m": "드러내다, 공개하다", "form": "revealed", "note": "동사 reveal의 과거분사형(to be revealed, 수동)"}, {"w": "regard", "m": "(~로) 여기다", "form": "regarded", "note": "동사 regard의 과거분사형(수동, regarded as ~: ~로 여겨지는)"}, {"w": "public domain", "m": "공공의 영역"}, {"w": "define", "m": "정의하다, 규정하다", "form": "defined", "note": "동사 define의 과거분사형(수동, be defined by ~)"}, {"w": "motivation", "m": "동기, 이유"}, {"w": "move on", "m": "(지난 일을 털고) 앞으로 나아가다"}, {"w": "conviction", "m": "유죄 판결", "form": "convictions", "note": "명사 conviction의 복수형"}, {"w": "spend", "m": "쓰다, 소비하다 (여기서는 spent: 효력이 소멸된)", "form": "spent", "note": "동사 spend의 과거분사형이지만 본문에서는 \u2018효력이 소멸된\u2019이라는 뜻의 형용사처럼 쓰임"}, {"w": "recognize", "m": "인식하다, 인정하다", "form": "recognized", "note": "동사 recognize의 과거분사형(has been recognized, 현재완료 수동)"}, {"w": "conflict", "m": "충돌, 갈등"}, {"w": "exception", "m": "예외", "form": "exceptions", "note": "명사 exception의 복수형"}], "qa": [{"chunk": 1, "q": "사생활 권리는 어떤 권리인가?", "opts": ["전통적으로 보호되거나 개인적인 것으로 여겨지는 정보가 공개되지 않을 권리이다.", "이미 공개된 정보를 없애 달라고 요구할 권리이다.", "공공의 영역에 있는 정보를 모두 알 권리이다."], "ans": 0, "why": ["2번 문장이 근거이다.", "사생활 권리는 보호되거나 개인적인 정보가 공개되지 않을 권리이다.", "이미 공개된 정보에 적용되는 것은 3번 문장에서 잊힐 권리라고 하므로 두 번째 보기는 틀리다.", "공공 정보를 모두 알 권리라는 내용은 지문에 없다."], "ev_en": "The right to privacy is, among other things, the right for information traditionally regarded as protected or personal not to be revealed.", "ev_ko": "사생활 권리는, 무엇보다도, 전통적으로 보호되거나 개인적인 것으로 여겨지는 정보가 공개되지 않을 권리이다."}, {"chunk": 2, "q": "잊힐 권리를 지지하는 이유(동기)로 글에서 든 것은?", "opts": ["개인이 삶을 이어 나가고 특정 사건이나 기간에 의해 정의되지 않게 하기 위해서이다.", "범죄자에게 더 무거운 벌을 주기 위해서이다.", "개인 정보를 더 널리 공개하기 위해서이다."], "ans": 0, "why": ["5번 문장이 근거이다.", "one motivation(한 가지 이유)은 개인이 삶을 이어 가고 과거의 한 사건에 매이지 않게 하는 것이다.", "범죄자에게 더 무거운 벌을 준다는 내용은 없고, 6번 문장은 오히려 과거의 유죄 판결도 결국 효력이 소멸되어야 한다고 한다.", "정보를 더 널리 공개한다는 내용은 지문에 없다."], "ev_en": "One motivation for such a right is to allow individuals to move on with their lives and not be defined by a specific event or period in their lives.", "ev_ko": "그러한 권리의 한 가지 이유는 개인들이 (지난 일을 털고) 자신의 삶을 이어 나가고 자신의 삶의 특정한 사건이나 기간에 의해 정의되지 않게 해 주는 것이다."}, {"chunk": 3, "q": "잊힐 권리가 다른 권리와 충돌할 때 지문에서 예로 든 것은?", "opts": ["안보나 공공 보건 이유로 공식적인 예외가 만들어지기도 한다.", "잊힐 권리는 언제나 다른 권리보다 우선한다.", "충돌이 생기면 잊힐 권리는 폐지된다."], "ans": 0, "why": ["8번 문장이 근거이다.", "formal exceptions(공식적인 예외)가 안보 또는 공공 보건 이유로 때때로 만들어진다고 한다.", "언제나 우선한다는 내용은 7번 문장의 \u2018다른 권리와 충돌할 수 있다\u2019와 맞지 않는다.", "권리가 폐지된다는 내용은 지문에 없다."], "ev_en": "For example, formal exceptions are sometimes made for security or public health reasons.", "ev_ko": "예를 들어, 공식적인 예외가 안보 또는 공공 보건의 이유로 인해 때때로 만들어진다."}], "tf": [{"s": "잊힐 권리는 공공의 영역에 있었던 정보에도 적용될 수 있다.", "t": true, "why": ["3번 문장의 내용이다.", "in contrast(반면에)가 있으므로 사생활 권리와의 차이점을 말하는 문장이다."], "ev_en": "The right to be forgotten, in contrast, can be applied to information that has been in the public domain.", "ev_ko": "반면에 잊힐 권리는 공공의 영역에 있었던 정보에 적용될 수 있다."}, {"s": "사생활 권리는 이미 공공의 영역에 있었던 정보에 적용되는 권리이다.", "t": false, "why": ["잊힐 권리와 사생활 권리를 바꿔치기한 진술이다.", "2번 문장에서 사생활 권리는 보호되거나 개인적인 정보가 공개되지 않을 권리이다.", "공공의 영역에 있었던 정보에 적용될 수 있는 것은 잊힐 권리이다(3번 문장)."], "ev_en": "The right to privacy is, among other things, the right for information traditionally regarded as protected or personal not to be revealed. The right to be forgotten, in contrast, can be applied to information that has been in the public domain.", "ev_ko": "사생활 권리는, 무엇보다도, 전통적으로 보호되거나 개인적인 것으로 여겨지는 정보가 공개되지 않을 권리이다. 반면에 잊힐 권리는 공공의 영역에 있었던 정보에 적용될 수 있다."}, {"s": "영국과 프랑스 같은 일부 국가에서는 과거의 범죄 유죄 판결도 결국 효력이 소멸되어야 한다고 오랫동안 인식되어 왔다.", "t": true, "why": ["6번 문장의 내용이다.", "spent는 여기서 \u2018효력이 소멸된\u2019이라는 뜻이다."], "ev_en": "For example, it has long been recognized in some countries, such as the UK and France, that even past criminal convictions should eventually be \u201cspent\u201d and not continue to affect a person\u2019s life.", "ev_ko": "예를 들어, 영국과 프랑스와 같은 일부 국가에서는 과거의 범죄 유죄 판결조차도 결국 \u2018효력이 소멸되어야\u2019 하고 한 사람의 삶에 계속 영향을 미치지 않아야 한다고 오랫동안 인식되어 왔다."}, {"s": "잊힐 권리는 다른 권리와 충돌하는 일이 없다.", "t": false, "why": ["지문과 반대이다.", "7번 문장은 잊힐 권리가 다른 권리와 때때로 충돌할 수 있다(can sometimes come into conflict with other rights)고 한다.", "그래서 안보나 공공 보건 이유로 예외가 만들어지기도 한다(8번 문장)."], "ev_en": "Despite the reason for supporting the right to be forgotten, the right to be forgotten can sometimes come into conflict with other rights. For example, formal exceptions are sometimes made for security or public health reasons.", "ev_ko": "잊힐 권리를 지지하는 그러한 이유에도 불구하고 잊힐 권리는 다른 권리와 때때로 충돌할 수 있다. 예를 들어, 공식적인 예외가 안보 또는 공공 보건의 이유로 인해 때때로 만들어진다."}, {"s": "잊힐 권리는 개인이 특정 시점의 정보에 의해 영원히 정의되지 않을 권리를 포함한다.", "t": true, "why": ["4번 문장의 내용이다.", "not to be forever defined(영원히 정의되지 않는)가 핵심 표현이다."], "ev_en": "The right to be forgotten broadly includes the right of an individual not to be forever defined by information from a specific point in time.", "ev_ko": "잊힐 권리는 특정 시점의 정보에 의해 영원히 정의되지 않아야 할 개인의 권리를 광범위하게 포함한다."}], "flow": {"fixed": "잊힐 권리는 사생활 권리와 구별되지만 관련이 있는 권리이며, 사생활 권리는 보호되거나 개인적인 정보가 공개되지 않을 권리이다.", "order": ["이와 달리 잊힐 권리는 이미 공공의 영역에 있었던 정보에도 적용될 수 있다.", "잊힐 권리는 특정 시점의 정보로 영원히 정의되지 않을 개인의 권리를 포함하며, 그 이유는 사람들이 과거에 매이지 않고 삶을 이어 가게 하려는 것이다. 예를 들어 일부 국가에서는 과거의 범죄 유죄 판결도 결국 효력이 소멸되어야 한다고 본다.", "그런 이유에도 불구하고 이 권리는 다른 권리와 충돌할 수 있어서, 예를 들어 안보나 공공 보건 이유로 예외가 만들어지기도 한다."], "clue": ["\u2018이와 달리\u2019가 앞의 사생활 권리와 대비되는 잊힐 권리의 특징을 이끎", "\u2018그 이유\u2019와 \u2018예를 들어\u2019로 앞의 권리의 이유와 예를 설명함", "\u2018그런 이유에도 불구하고\u2019가 앞의 이유를 받아 충돌과 예외를 말함"], "why": ["두 권리를 소개", "잊힐 권리는 공개된 정보에도 적용", "권리의 이유와 예", "그래도 충돌하면 예외가 있음"], "cards": ["그런 이유에도 불구하고 이 권리는 다른 권리와 충돌할 수 있어서, 예를 들어 안보나 공공 보건 이유로 예외가 만들어지기도 한다.", "잊힐 권리는 특정 시점의 정보로 영원히 정의되지 않을 개인의 권리를 포함하며, 그 이유는 사람들이 과거에 매이지 않고 삶을 이어 가게 하려는 것이다. 예를 들어 일부 국가에서는 과거의 범죄 유죄 판결도 결국 효력이 소멸되어야 한다고 본다.", "이와 달리 잊힐 권리는 이미 공공의 영역에 있었던 정보에도 적용될 수 있다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "The right to be forgotten is a right distinct from but related to a right to privacy.", "ko": "잊힐 권리는 사생활 권리와 구별되지만 관련이 있는 권리이다."}, {"n": 2, "en": "The right to privacy is, among other things, the right for information traditionally regarded as protected or personal not to be revealed.", "ko": "사생활 권리는, 무엇보다도, 전통적으로 보호되거나 개인적인 것으로 여겨지는 정보가 공개되지 않을 권리이다."}, {"n": 3, "en": "The right to be forgotten, in contrast, can be applied to information that has been in the public domain.", "ko": "반면에 잊힐 권리는 공공의 영역에 있었던 정보에 적용될 수 있다."}, {"n": 4, "en": "The right to be forgotten broadly includes the right of an individual not to be forever defined by information from a specific point in time.", "ko": "잊힐 권리는 특정 시점의 정보에 의해 영원히 정의되지 않아야 할 개인의 권리를 광범위하게 포함한다."}, {"n": 5, "en": "One motivation for such a right is to allow individuals to move on with their lives and not be defined by a specific event or period in their lives.", "ko": "그러한 권리의 한 가지 이유는 개인들이 (지난 일을 털고) 자신의 삶을 이어 나가고 자신의 삶의 특정한 사건이나 기간에 의해 정의되지 않게 해 주는 것이다."}, {"n": 6, "en": "For example, it has long been recognized in some countries, such as the UK and France, that even past criminal convictions should eventually be \u201cspent\u201d and not continue to affect a person\u2019s life.", "ko": "예를 들어, 영국과 프랑스와 같은 일부 국가에서는 과거의 범죄 유죄 판결조차도 결국 \u2018효력이 소멸되어야\u2019 하고 한 사람의 삶에 계속 영향을 미치지 않아야 한다고 오랫동안 인식되어 왔다."}, {"n": 7, "en": "Despite the reason for supporting the right to be forgotten, the right to be forgotten can sometimes come into conflict with other rights.", "ko": "잊힐 권리를 지지하는 그러한 이유에도 불구하고 잊힐 권리는 다른 권리와 때때로 충돌할 수 있다."}, {"n": 8, "en": "For example, formal exceptions are sometimes made for security or public health reasons.", "ko": "예를 들어, 공식적인 예외가 안보 또는 공공 보건의 이유로 인해 때때로 만들어진다."}]}, {"id": "2211-37", "short": "22년 11월 37번", "group": "22년 11월", "num": 37, "topic_ko": "행동을 호불호 변화로 설명하는 것의 문제와 소득\u00b7물가의 영향", "chunks": [{"n": 1, "label": "주장", "from": 1, "to": 1, "summary_ko": "경제학자에게 행동을 호불호의 변화로 설명하는 것은 일반적으로 매우 문제가 많음"}, {"n": 2, "label": "예시", "from": 2, "to": 3, "summary_ko": "출산율 변화를 아이에 대한 기호의 증감으로 설명하는 것은 사회 과학자를 불안정한 입지에 놓음"}, {"n": 3, "label": "원인", "from": 4, "to": 5, "summary_ko": "경제학자에게 출산율에 영향을 주는 것은 기호가 아니라 소득과 물가의 변화임"}], "gloss": [{"w": "preference", "m": "선호, 선호도"}, {"w": "consume", "m": "소비하다", "form": "consuming", "note": "동사 consume의 동명사형(전치사 from 뒤)"}, {"w": "figure out", "m": "알아내다, 이해하다", "form": "figuring out", "note": "figure out의 동명사형(전치사 in 뒤)"}, {"w": "underlying", "m": "기저에 있는, 근본적인"}, {"w": "problematic", "m": "문제가 많은"}, {"w": "baby bust", "m": "출산율의 급락"}, {"w": "inherent", "m": "내재적인, 타고난"}, {"w": "taste", "m": "기호, 취향", "form": "tastes", "note": "명사 taste의 복수형"}, {"w": "unsound", "m": "불안정한, 근거가 약한"}, {"w": "equivalent", "m": "동등한, 같은"}, {"w": "mortality", "m": "사망률"}, {"w": "attribute", "m": "~의 탓으로 돌리다", "form": "attributed", "note": "동사 attribute의 과거분사형(could be attributed to ~, 수동)"}, {"w": "derive", "m": "(~에서) 얻다", "form": "derived", "note": "동사 derive의 과거분사형(satisfaction derived from children: 아이로부터 얻은 만족감)"}, {"w": "good", "m": "상품, 재화", "form": "good", "note": "여기서는 형용사 \u2018좋은\u2019이 아니라 명사 \u2018상품\u2019"}], "qa": [{"chunk": 1, "q": "한 사람의 선호도 구조를 알아낸 경제학자는 행동을 호불호의 변화로 설명하는 것을 어떻게 보는가?", "opts": ["가장 정확한 설명 방법이라고 본다.", "일반적으로 매우 문제가 많다고 본다.", "선호도 구조와는 관계가 없다고 본다."], "ans": 1, "why": ["1번 문장이 근거이다.", "explaining behavior in terms of changes in underlying likes and dislikes는 \u2018기저에 있는 호불호의 변화로 행동을 설명하는 것\u2019이라는 뜻이다.", "그것이 usually highly problematic(일반적으로 매우 문제가 많다)이라고 한다.", "가장 정확하다는 내용은 지문과 반대이다.", "선호도 구조는 오히려 글의 출발점이므로 관계가 없다는 말도 틀리다."], "ev_en": "To an economist who succeeds in figuring out a person\u2019s preference structure \u2014 understanding whether the satisfaction gained from consuming one good is greater than that of another \u2014 explaining behavior in terms of changes in underlying likes and dislikes is usually highly problematic.", "ev_ko": "한 사람의 선호도 구조를 알아내는 것, 즉 한 상품을 소비함으로써 얻는 만족도가 또 다른 상품을 소비함으로써 얻는 만족도보다 더 큰지를 이해하는 것에 성공한 경제학자에게는 행동을 기저에 있는 호불호의 변화의 관점에서 설명하는 것은 일반적으로 매우 문제가 많다."}, {"chunk": 2, "q": "출산율의 증감을 아이에 대한 대중의 기호 증감으로 설명하는 주장은 어떻게 평가되는가?", "opts": ["사회 과학자를 불안정한 입지에 놓는다.", "상대적 가격의 변화로 설명하는 것보다 더 설득력 있다.", "사망률을 설명할 때에만 쓸 수 있다."], "ans": 0, "why": ["2번 문장이 근거이다.", "그런 주장은 places a social scientist in an unsound position(사회 과학자를 불안정한 입지에 놓는다)이라고 한다.", "상대적 가격의 변화는 오히려 그 주장과 대비되는 올바른 설명으로 제시된다.", "3번 문장은 사망률 이야기를 비유로 든 것일 뿐이다."], "ev_en": "To argue, for instance, that the baby boom and then the baby bust resulted from an increase and then a decrease in the public\u2019s inherent taste for children, rather than a change in relative prices against a background of stable preferences, places a social scientist in an unsound position.", "ev_ko": "예를 들어, 베이비 붐과 그 후의 출산율의 급락이 안정된 선호도를 배경으로 한 상대적 가격의 변화보다는 아이에 대한 대중의 내재적인 기호의 증가와 그 후의 감소에서 비롯되었다고 주장하는 것은 사회 과학자를 불안정한 입지에 놓는다."}, {"chunk": 3, "q": "경제학자가 보기에 출산율에 영향을 미치는 것은?", "opts": ["소득이나 물가가 아니라 기호의 변화이다.", "사망률의 변화이다.", "기호의 변화가 아니라 소득과 물가의 변화이다."], "ans": 2, "why": ["4번 문장이 근거이다.", "changes in income and prices, rather than changes in tastes(기호의 변화가 아니라 소득과 물가의 변화)가 출산율에 영향을 미친다.", "두 번째 보기는 순서를 바꿔 반대로 말한 것이다.", "사망률은 비유로만 나왔고 출산율의 원인으로 제시되지 않는다."], "ev_en": "For an economist, changes in income and prices, rather than changes in tastes, affect birth rates.", "ev_ko": "경제학자에게는 기호의 변화보다는 소득과 물가의 변화가 출산율에 영향을 미친다."}], "tf": [{"s": "경제학자에게는 안정된 선호도를 배경으로 한 상대적 가격의 변화가 출산율 변화의 설명이 될 수 있다.", "t": true, "why": ["2번 문장의 내용이다.", "a change in relative prices against a background of stable preferences(안정된 선호도를 배경으로 한 상대적 가격의 변화)가 올바른 설명으로 대비되어 나온다."], "ev_en": "To argue, for instance, that the baby boom and then the baby bust resulted from an increase and then a decrease in the public\u2019s inherent taste for children, rather than a change in relative prices against a background of stable preferences, places a social scientist in an unsound position.", "ev_ko": "예를 들어, 베이비 붐과 그 후의 출산율의 급락이 안정된 선호도를 배경으로 한 상대적 가격의 변화보다는 아이에 대한 대중의 내재적인 기호의 증가와 그 후의 감소에서 비롯되었다고 주장하는 것은 사회 과학자를 불안정한 입지에 놓는다."}, {"s": "소득이 증가할 때 사람들이 자녀를 더 원하려면 자녀에 대한 내재적 욕구가 먼저 커져야 한다.", "t": false, "why": ["지문과 반대이다.", "5번 문장은 even if their inherent desire for children stays the same(자녀에 대한 내재적 욕구가 그대로 유지되더라도) 소득이 오르면 더 많은 자녀를 원한다고 한다.", "즉 내재적 욕구가 변하지 않아도 된다."], "ev_en": "When income rises, for example, people want more children (or, as you will see later, more satisfaction derived from children), even if their inherent desire for children stays the same.", "ev_ko": "예를 들어, 소득이 증가할 때 사람들은 자녀에 대한 자신의 내재적 욕구가 그대로 유지되더라도 더 많은 자녀(또는 여러분이 나중에 알게 되겠지만, 아이로부터 오는 더 큰 만족감)를 원한다."}, {"s": "출산율을 기호의 변화로 설명하는 것은 사망률의 상승과 하락을 죽음에 대한 욕구 변화로 설명하는 것과 같다.", "t": true, "why": ["3번 문장의 내용이다.", "would be equivalent to(~와 같을 것이다)로 비유하고 있다."], "ev_en": "In economics, such an argument about birth rates would be equivalent to saying that a rise and fall in mortality could be attributed to an increase in the inherent desire change for death.", "ev_ko": "경제학에서 출산율에 대한 그러한 주장은 사망률의 상승과 하락이 죽음에 대한 내재적 욕구 변화의 증가에 기인한다고 말하는 것과 같다."}, {"s": "경제학자에게는 소득과 물가의 변화보다 기호의 변화가 출산율에 영향을 미친다.", "t": false, "why": ["순서가 뒤바뀐 진술이다.", "4번 문장은 기호의 변화보다 소득과 물가의 변화가 출산율에 영향을 미친다고 한다."], "ev_en": "For an economist, changes in income and prices, rather than changes in tastes, affect birth rates.", "ev_ko": "경제학자에게는 기호의 변화보다는 소득과 물가의 변화가 출산율에 영향을 미친다."}, {"s": "선호도 구조를 안다는 것은 한 상품을 소비해 얻는 만족도가 다른 상품보다 큰지를 이해하는 것이다.", "t": true, "why": ["1번 문장의 대시(\u2014) 뒤 설명이다.", "preference structure(선호도 구조)를 풀어서 설명한 부분이다."], "ev_en": "To an economist who succeeds in figuring out a person\u2019s preference structure \u2014 understanding whether the satisfaction gained from consuming one good is greater than that of another \u2014 explaining behavior in terms of changes in underlying likes and dislikes is usually highly problematic.", "ev_ko": "한 사람의 선호도 구조를 알아내는 것, 즉 한 상품을 소비함으로써 얻는 만족도가 또 다른 상품을 소비함으로써 얻는 만족도보다 더 큰지를 이해하는 것에 성공한 경제학자에게는 행동을 기저에 있는 호불호의 변화의 관점에서 설명하는 것은 일반적으로 매우 문제가 많다."}], "flow": {"fixed": "경제학자에게는 행동을 기저에 있는 호불호의 변화로 설명하는 것이 일반적으로 매우 문제가 많다.", "order": ["예를 들어 베이비 붐과 출산율 급락이 안정된 선호도 속 가격 변화가 아니라 아이에 대한 기호의 증감 때문이라고 주장하면 사회 과학자는 불안정한 입지에 놓인다.", "기호의 증감으로 설명하는 그러한 주장은 사망률의 오르내림을 죽음에 대한 욕구 변화 탓으로 돌리는 것과 같다.", "경제학자에게 출산율에 영향을 주는 것은 기호가 아니라 소득과 물가의 변화이며, 예를 들어 소득이 오르면 내재적 욕구가 그대로여도 사람들은 자녀를 더 원한다."], "clue": ["\u2018예를 들어\u2019가 앞의 일반적 주장을 구체적인 사례로 풀어 줌", "\u2018기호의 증감으로 설명하는 그러한 주장\u2019이 앞 카드의 주장을 가리키며 그것의 문제를 비유로 드러냄", "앞의 잘못된 주장을 뒤집어 진짜 원인과 \u2018예를 들어\u2019 소득의 영향을 말함"], "why": ["호불호로 설명하는 것은 문제가 많음", "출산율 사례", "그 주장은 사망률 비유처럼 설득력이 없음", "진짜 원인은 소득과 물가"], "cards": ["기호의 증감으로 설명하는 그러한 주장은 사망률의 오르내림을 죽음에 대한 욕구 변화 탓으로 돌리는 것과 같다.", "경제학자에게 출산율에 영향을 주는 것은 기호가 아니라 소득과 물가의 변화이며, 예를 들어 소득이 오르면 내재적 욕구가 그대로여도 사람들은 자녀를 더 원한다.", "예를 들어 베이비 붐과 출산율 급락이 안정된 선호도 속 가격 변화가 아니라 아이에 대한 기호의 증감 때문이라고 주장하면 사회 과학자는 불안정한 입지에 놓인다."], "answer": [2, 0, 1]}, "sents": [{"n": 1, "en": "To an economist who succeeds in figuring out a person\u2019s preference structure \u2014 understanding whether the satisfaction gained from consuming one good is greater than that of another \u2014 explaining behavior in terms of changes in underlying likes and dislikes is usually highly problematic.", "ko": "한 사람의 선호도 구조를 알아내는 것, 즉 한 상품을 소비함으로써 얻는 만족도가 또 다른 상품을 소비함으로써 얻는 만족도보다 더 큰지를 이해하는 것에 성공한 경제학자에게는 행동을 기저에 있는 호불호의 변화의 관점에서 설명하는 것은 일반적으로 매우 문제가 많다."}, {"n": 2, "en": "To argue, for instance, that the baby boom and then the baby bust resulted from an increase and then a decrease in the public\u2019s inherent taste for children, rather than a change in relative prices against a background of stable preferences, places a social scientist in an unsound position.", "ko": "예를 들어, 베이비 붐과 그 후의 출산율의 급락이 안정된 선호도를 배경으로 한 상대적 가격의 변화보다는 아이에 대한 대중의 내재적인 기호의 증가와 그 후의 감소에서 비롯되었다고 주장하는 것은 사회 과학자를 불안정한 입지에 놓는다."}, {"n": 3, "en": "In economics, such an argument about birth rates would be equivalent to saying that a rise and fall in mortality could be attributed to an increase in the inherent desire change for death.", "ko": "경제학에서 출산율에 대한 그러한 주장은 사망률의 상승과 하락이 죽음에 대한 내재적 욕구 변화의 증가에 기인한다고 말하는 것과 같다."}, {"n": 4, "en": "For an economist, changes in income and prices, rather than changes in tastes, affect birth rates.", "ko": "경제학자에게는 기호의 변화보다는 소득과 물가의 변화가 출산율에 영향을 미친다."}, {"n": 5, "en": "When income rises, for example, people want more children (or, as you will see later, more satisfaction derived from children), even if their inherent desire for children stays the same.", "ko": "예를 들어, 소득이 증가할 때 사람들은 자녀에 대한 자신의 내재적 욕구가 그대로 유지되더라도 더 많은 자녀(또는 여러분이 나중에 알게 되겠지만, 아이로부터 오는 더 큰 만족감)를 원한다."}]}, {"id": "2211-38", "short": "22년 11월 38번", "group": "22년 11월", "num": 38, "topic_ko": "동물과 사람이 타고난 직관으로 항영양소 식물을 피하는 방식", "chunks": [{"n": 1, "label": "동물의 직관", "from": 1, "to": 3, "summary_ko": "동물은 항영양소가 있는 식물을 다시 먹지 않고 멀리하며, 이는 타고난 지능임"}, {"n": 2, "label": "사람의 직관", "from": 4, "to": 6, "summary_ko": "직관은 동물만의 것이 아니며, 아이들이 야채를 싫어하는 것도 내적 지능의 일부임"}, {"n": 3, "label": "맛과 성장", "from": 7, "to": 9, "summary_ko": "몸은 야채 맛을 나쁘게 느끼게 해 아이를 지키고, 자라서 강해지면 맛이 덜 나쁘게 느껴짐"}], "gloss": [{"w": "consume", "m": "섭취하다, 먹다", "form": "consumes", "note": "동사 consume의 3인칭 단수 현재형(주어 an animal이 단수)"}, {"w": "antinutrient", "m": "항영양소(영양 흡수를 방해하는 성분)", "form": "antinutrients", "note": "명사 antinutrient의 복수형"}, {"w": "unwell", "m": "몸이 안 좋은"}, {"w": "intuitively", "m": "직관적으로"}, {"w": "evolution", "m": "진화"}, {"w": "innate", "m": "타고난, 선천적인"}, {"w": "pass down", "m": "(후대로) 전해 내려오다", "form": "passed down", "note": "동사 pass down의 과거분사형(being passed down: 전해지는)"}, {"w": "justify", "m": "정당화하다, 설명하다", "form": "justifies", "note": "동사 justify의 3인칭 단수 현재형(주어 Dr. Steven Gundry가 단수)"}, {"w": "genetic", "m": "유전의, 유전적인"}, {"w": "fragile", "m": "연약한"}, {"w": "taste bud", "m": "미뢰(혀의 맛 감각 기관)", "form": "taste buds", "note": "명사 taste bud의 복수형"}, {"w": "perceive", "m": "인식하다, 느끼다"}, {"w": "disgusting", "m": "역겨운"}, {"w": "tolerate", "m": "견디다, 참아 내다"}], "qa": [{"chunk": 1, "q": "동물이 항영양소가 많아 몸 상태를 나쁘게 하는 식물을 먹으면 어떻게 하는가?", "opts": ["그 식물을 다시는 먹지 않는다.", "그 식물을 더 많이 먹어 적응한다.", "다른 동물에게 그 식물을 먹이로 나눠 준다."], "ans": 0, "why": ["1번 문장이 근거이다.", "it won\u2019t eat that plant again(그 식물을 다시는 먹지 않을 것이다)이라고 한다.", "더 많이 먹는다거나 나눠 준다는 내용은 지문에 없다."], "ev_en": "In the natural world, if an animal consumes a plant with enough antinutrients to make it feel unwell, it won\u2019t eat that plant again.", "ev_ko": "자연계에서 만약 동물이 자신의 상태를 안 좋게 하기에 충분한 항영양소가 있는 식물을 섭취하면 그 동물은 그 식물을 다시는 먹지 않을 것이다."}, {"chunk": 2, "q": "Dr. Steven Gundry는 대부분의 아이들이 야채를 싫어하는 것을 어떻게 설명하는가?", "opts": ["우리의 유전적 프로그래밍, 즉 내적 지능의 일부라고 설명한다.", "부모가 야채를 억지로 먹여서 생긴 습관이라고 설명한다.", "야채를 먹어 본 경험이 부족해서라고 설명한다."], "ans": 0, "why": ["6번 문장이 근거이다.", "part of our genetic programming, our inner intelligence(우리의 유전적 프로그래밍, 즉 내적 지능의 일부)라고 한다.", "부모의 강요나 경험 부족은 지문에 나오지 않는다."], "ev_en": "Dr. Steven Gundry justifies this as part of our genetic programming, our inner intelligence.", "ev_ko": "Dr. Steven Gundry는 이것을 우리의 유전적 프로그래밍, 즉 우리의 내적 지능의 일부로 정당화한다."}, {"chunk": 3, "q": "몸이 아이를 야채로부터 멀리하게 하는 방법은?", "opts": ["미뢰가 이런 맛을 나쁘고 역겹게 인식하게 만든다.", "야채를 소화하지 못하게 만든다.", "야채의 냄새를 맡지 못하게 만든다."], "ans": 0, "why": ["8번 문장이 근거이다.", "making your taste buds perceive these flavors as bad and even disgusting(미뢰가 이런 맛을 나쁘고 심지어 역겨운 것으로 인식하게 만듦)으로써 그렇게 한다.", "소화나 냄새에 대한 내용은 지문에 없다."], "ev_en": "It does this by making your taste buds perceive these flavors as bad and even disgusting.", "ev_ko": "그것은 여러분의 미뢰(\u5473\u857e)로 하여금 이러한 맛을 나쁘고 심지어 역겨운 것으로 인식하게 만듦으로써 이를 수행한다."}], "tf": [{"s": "동물이 지닌 타고난 지능은 오랜 진화와 전해 내려오는 정보가 만들어 냈다.", "t": true, "why": ["3번 문장의 내용이다.", "Years of evolution and information being passed down(오랜 시간의 진화와 전해 내려오는 정보)이 원인이다."], "ev_en": "Years of evolution and information being passed down created this innate intelligence.", "ev_ko": "오랜 시간의 진화와 전해 내려오는 정보는 이 타고난 지능을 만들어 냈다."}, {"s": "직관은 동물에게서만 보이는 현상이다.", "t": false, "why": ["지문과 반대이다.", "4번 문장은 이 직관이 not just seen in animals(동물에게서만 보이는 것은 아니다)라고 한다.", "사람, 특히 아이들에게도 나타난다는 내용이 이어진다."], "ev_en": "This \u201cintuition,\u201d though, is not just seen in animals.", "ev_ko": "그러나 이 \u2018직관\u2019은 동물에게서만 보이는 것은 아니다."}, {"s": "많은 야채에 항영양소가 가득해서, 몸은 연약하고 성장 중인 사람을 야채로부터 멀리하게 하려 한다.", "t": true, "why": ["7번 문장의 내용이다.", "fragile(연약한)과 in development(성장 중인)가 아이 시기를 가리킨다."], "ev_en": "Since many vegetables are full of antinutrients, your body tries to keep you away from them while you are still fragile and in development.", "ev_ko": "많은 야채들이 항영양소로 가득 차 있기 때문에 여러분이 아직 연약하고 성장 중에 있을 때 여러분의 몸은 여러분을 그것들로부터 멀리하게 하려고 노력한다."}, {"s": "몸이 강해져 항영양소를 견딜 수 있게 되면 야채 맛이 이전보다 더 나쁘게 느껴진다.", "t": false, "why": ["방향이 뒤바뀐 진술이다.", "9번 문장에 따르면 몸이 강해지면 항영양소가 더 이상 이전만큼 맛이 나쁘지 않게 느껴진다.", "그래서 몸이 강해질수록 야채의 맛이 덜 나쁘게 느껴진다."], "ev_en": "As you grow and your body becomes stronger enough to tolerate these antinutrients, suddenly they no longer taste as bad as before.", "ev_ko": "여러분이 성장하고 여러분의 신체가 이러한 항영양소를 견딜 만큼 충분히 더 강해지면 갑자기 그것들은 더 이상 이전만큼 맛이 나쁘게 느껴지지 않는다."}, {"s": "동물은 직관적으로 항영양소가 든 식물을 멀리할 줄 안다.", "t": true, "why": ["2번 문장의 내용이다.", "stay away from(~을 멀리하다)이 핵심 표현이다."], "ev_en": "Intuitively, animals also know to stay away from these plants.", "ev_ko": "직관적으로 동물은 또한 이러한 식물을 멀리할 줄 안다."}], "flow": {"fixed": "동물은 항영양소가 든 식물을 먹고 몸이 안 좋아지면 다시 먹지 않으며, 직관적으로 그런 식물을 멀리하는데 이는 오랜 진화가 만든 타고난 지능이다.", "order": ["그러나 이런 직관은 동물에게서만 보이는 것이 아니며, 아이들이 야채를 싫어하는 것도 유전적 프로그래밍, 즉 내적 지능의 일부로 설명된다.", "많은 야채에 항영양소가 가득해서 몸은 연약한 시기의 아이를 야채에서 멀리하려 하며, 이를 위해 미뢰가 그 맛을 나쁘고 역겹게 느끼게 만든다.", "그러다 성장해서 몸이 항영양소를 견딜 만큼 강해지면 갑자기 야채는 이전만큼 맛이 나쁘게 느껴지지 않는다."], "clue": ["\u2018그러나\u2019와 \u2018동물에게서만이 아니다\u2019가 앞의 동물 이야기를 사람으로 넓힘", "아이들이 야채를 싫어하는 이유를 앞의 설명을 받아 구체적으로 풀어 줌", "\u2018그러다 성장해서\u2019가 아이 시기 다음의 변화를 말함"], "why": ["동물의 타고난 직관", "사람, 특히 아이에게도 있는 직관", "맛으로 야채를 막음", "크면 맛이 덜 나빠짐"], "cards": ["많은 야채에 항영양소가 가득해서 몸은 연약한 시기의 아이를 야채에서 멀리하려 하며, 이를 위해 미뢰가 그 맛을 나쁘고 역겹게 느끼게 만든다.", "그러나 이런 직관은 동물에게서만 보이는 것이 아니며, 아이들이 야채를 싫어하는 것도 유전적 프로그래밍, 즉 내적 지능의 일부로 설명된다.", "그러다 성장해서 몸이 항영양소를 견딜 만큼 강해지면 갑자기 야채는 이전만큼 맛이 나쁘게 느껴지지 않는다."], "answer": [1, 0, 2]}, "sents": [{"n": 1, "en": "In the natural world, if an animal consumes a plant with enough antinutrients to make it feel unwell, it won\u2019t eat that plant again.", "ko": "자연계에서 만약 동물이 자신의 상태를 안 좋게 하기에 충분한 항영양소가 있는 식물을 섭취하면 그 동물은 그 식물을 다시는 먹지 않을 것이다."}, {"n": 2, "en": "Intuitively, animals also know to stay away from these plants.", "ko": "직관적으로 동물은 또한 이러한 식물을 멀리할 줄 안다."}, {"n": 3, "en": "Years of evolution and information being passed down created this innate intelligence.", "ko": "오랜 시간의 진화와 전해 내려오는 정보는 이 타고난 지능을 만들어 냈다."}, {"n": 4, "en": "This \u201cintuition,\u201d though, is not just seen in animals.", "ko": "그러나 이 \u2018직관\u2019은 동물에게서만 보이는 것은 아니다."}, {"n": 5, "en": "Have you ever wondered why most children hate vegetables?", "ko": "여러분은 대부분의 아이들이 왜 야채를 싫어하는지 궁금해 한 적이 있는가?"}, {"n": 6, "en": "Dr. Steven Gundry justifies this as part of our genetic programming, our inner intelligence.", "ko": "Dr. Steven Gundry는 이것을 우리의 유전적 프로그래밍, 즉 우리의 내적 지능의 일부로 정당화한다."}, {"n": 7, "en": "Since many vegetables are full of antinutrients, your body tries to keep you away from them while you are still fragile and in development.", "ko": "많은 야채들이 항영양소로 가득 차 있기 때문에 여러분이 아직 연약하고 성장 중에 있을 때 여러분의 몸은 여러분을 그것들로부터 멀리하게 하려고 노력한다."}, {"n": 8, "en": "It does this by making your taste buds perceive these flavors as bad and even disgusting.", "ko": "그것은 여러분의 미뢰(\u5473\u857e)로 하여금 이러한 맛을 나쁘고 심지어 역겨운 것으로 인식하게 만듦으로써 이를 수행한다."}, {"n": 9, "en": "As you grow and your body becomes stronger enough to tolerate these antinutrients, suddenly they no longer taste as bad as before.", "ko": "여러분이 성장하고 여러분의 신체가 이러한 항영양소를 견딜 만큼 충분히 더 강해지면 갑자기 그것들은 더 이상 이전만큼 맛이 나쁘게 느껴지지 않는다."}]}, {"id": "2311-21", "short": "23년 11월 21번", "group": "23년 11월", "num": 21, "topic_ko": "예술은 불편함을 마주하게 해 변화의 가능성을 주는 매개체", "chunks": [{"n": 1, "label": "주장", "from": 1, "to": 2, "summary_ko": "예술은 단순히 달콤한 것 이상으로 인간 경험의 전 범위와 정서적 연결을 제공함"}, {"n": 2, "label": "설명", "from": 3, "to": 5, "summary_ko": "예술에서 불편함을 기꺼이 마주하면 변화의 가능성이 생기며, 예술은 어려운 개념과 씨름하는 매개체가 됨"}, {"n": 3, "label": "예시", "from": 6, "to": 7, "summary_ko": "Guernica는 전쟁의 고통을, A Raisin in the Sun은 차별과 가족의 모습을 다룬 사례임"}], "gloss": [{"w": "aesthetics", "m": "미학, 미적인 것"}, {"w": "range", "m": "범위"}, {"w": "challenging", "m": "도전적인, 어려운"}, {"w": "uncomfortable", "m": "불편한"}, {"w": "engage with", "m": "~에 참여하다, ~와 관계를 맺다"}, {"w": "transformation", "m": "변형, 큰 변화"}, {"w": "vehicle", "m": "매개체, 수단", "form": "vehicles", "note": "명사 vehicle의 복수형"}, {"w": "contend with", "m": "~와 씨름하다, ~에 맞서다"}, {"w": "masterpiece", "m": "걸작"}, {"w": "heartbreaking", "m": "가슴 아픈"}, {"w": "cruel", "m": "잔인한"}, {"w": "universal", "m": "보편적인"}, {"w": "struggle", "m": "고군분투하다, 애쓰다", "form": "struggling", "note": "동사 struggle의 현재분사형(people struggling with ~: ~로 고군분투하는 사람들)"}, {"w": "discrimination", "m": "차별"}, {"w": "pursuit", "m": "추구"}, {"w": "portrait", "m": "초상(화), 묘사"}], "qa": [{"chunk": 1, "q": "Chatterjee가 말한 \u2018more than just sugar on the tongue(혀 위의 설탕 이상의 것)\u2019이 뜻하는 바로 알맞은 것은?", "opts": ["예술은 달콤하고 기분 좋게 하는 것에 그치지 않고 그 이상의 역할을 할 수 있다.", "예술은 사람의 입맛을 좋게 만들어 준다.", "예술은 설탕처럼 쉽게 사라진다."], "ans": 0, "why": ["2번 문장이 근거이다.", "혀 위의 설탕은 달콤하고 기분 좋은 것을 비유한다.", "그 이상이라는 것은 불편하고 도전적인 면까지 포함해 변화를 줄 수 있다는 뜻이다(3번 문장).", "입맛이나 쉽게 사라진다는 내용은 지문에 없다."], "ev_en": "\u201cThe arts can be more than just sugar on the tongue,\u201d Anjan Chatterjee, a professor at the University of Pennsylvania, says.", "ev_ko": "\u201c예술은 단순히 혀 위의 설탕 이상의 것이 될 수 있다,\u201d라고 Pennsylvania 대학교의 교수인 Anjan Chatterjee는 말한다."}, {"chunk": 2, "q": "Chatterjee에 따르면 예술에서 불편함을 기꺼이 마주하면 어떻게 되는가?", "opts": ["예술을 감상하는 것이 더 쉬워진다.", "예술의 아름다움이 줄어든다.", "어떤 변화나 변형의 가능성이 생긴다."], "ans": 2, "why": ["3번 문장이 근거이다.", "discomfort offers the possibility of some change(불편은 어떤 변화의 가능성을 제공한다)고 한다.", "4번 문장은 그것이 강력한 미적 경험이 될 수 있다고도 하므로 아름다움이 줄어든다는 말은 틀리다.", "감상이 쉬워진다는 내용은 지문에 없다."], "ev_en": "\u201cIn art, when there\u2019s something challenging, which can also be uncomfortable, this discomfort, if we\u2019re willing to engage with it, offers the possibility of some change, some transformation.", "ev_ko": "\u201c예술에서, 무언가 도전적인 것이 있고 그것이 또한 불편할 수 있을 때, 이 불편은, 만약 우리가 기꺼이 그것에 참여하려 한다면, 어떤 변화, 어떤 변형의 가능성을 제공한다."}, {"chunk": 3, "q": "Picasso의 Guernica에 대한 설명으로 알맞은 것은?", "opts": ["인종 차별과 아메리칸드림을 위한 노력을 다룬 이야기이다.", "전쟁의 가슴 아프고 잔인한 본질을 포착하고 스페인 내전의 보편적 고통을 숙고할 방법을 주었다.", "가족생활의 감동적인 초상을 보여 주었다."], "ans": 1, "why": ["6번 문장이 근거이다.", "Guernica는 전쟁의 가슴 아프고 잔인한 본질을 포착했다.", "인종 차별과 아메리칸드림, 가족생활은 Hansberry의 희곡 A Raisin in the Sun의 내용이다(7번 문장)."], "ev_en": "When Picasso painted his masterpiece Guernica in 1937, he captured the heartbreaking and cruel nature of war, and offered the world a way to consider the universal suffering caused by the Spanish Civil War.", "ev_ko": "Picasso가 그의 걸작 Guernica를 1937년에 그렸을 때, 그는 가슴 아프고 잔인한 전쟁의 본질을 포착했고, 스페인 내전으로 인한 보편적인 고통을 숙고할 방법을 세상에 제공했다."}], "tf": [{"s": "Chatterjee는 예술에서 불편함을 기꺼이 마주하면 변화의 가능성이 생긴다고 말한다.", "t": true, "why": ["3번 문장의 내용이다.", "if we\u2019re willing to engage with it(우리가 기꺼이 그것에 참여하려 한다면)이라는 조건이 붙는다."], "ev_en": "\u201cIn art, when there\u2019s something challenging, which can also be uncomfortable, this discomfort, if we\u2019re willing to engage with it, offers the possibility of some change, some transformation.", "ev_ko": "\u201c예술에서, 무언가 도전적인 것이 있고 그것이 또한 불편할 수 있을 때, 이 불편은, 만약 우리가 기꺼이 그것에 참여하려 한다면, 어떤 변화, 어떤 변형의 가능성을 제공한다."}, {"s": "Chatterjee는 예술에서 불편한 요소는 피하는 것이 좋다고 말한다.", "t": false, "why": ["지문과 맞지 않다.", "불편함을 피하라는 말은 없고, 기꺼이 마주하면 변화의 가능성이 생긴다고 한다.", "3번 문장은 불편함을 기꺼이 마주하면 변화의 가능성을 준다고 한다.", "4번 문장은 그것이 강력한 미적 경험이 될 수 있다고도 한다."], "ev_en": "\u201cIn art, when there\u2019s something challenging, which can also be uncomfortable, this discomfort, if we\u2019re willing to engage with it, offers the possibility of some change, some transformation. That can also be a powerful aesthetic experience.\u201d", "ev_ko": "\u201c예술에서, 무언가 도전적인 것이 있고 그것이 또한 불편할 수 있을 때, 이 불편은, 만약 우리가 기꺼이 그것에 참여하려 한다면, 어떤 변화, 어떤 변형의 가능성을 제공한다. 그것은 또한 강력한 미적 경험이 될 수 있다.\u201d"}, {"s": "예술은 그렇지 않으면 어렵고 불편한 아이디어와 개념에 맞서는 매개체가 된다.", "t": true, "why": ["5번 문장의 내용이다.", "vehicles to contend with(~와 씨름하는 매개체)가 핵심 표현이다."], "ev_en": "The arts, in this way, become vehicles to contend with ideas and concepts that are difficult and uncomfortable otherwise.", "ev_ko": "예술은, 이런 방식으로, 그렇지 않았더라면 어렵고 불편한 아이디어 및 개념들과 싸우는 매개체가 된다."}, {"s": "Picasso의 Guernica는 인종 차별과 아메리칸드림의 추구를 그린 희곡이다.", "t": false, "why": ["다른 작품의 내용을 섞은 진술이다.", "Guernica는 1937년에 Picasso가 그린 그림으로, 스페인 내전이 낳은 보편적인 고통을 다룬다(6번 문장).", "7번 문장의 struggling with racism, discrimination(인종 차별, 차별과 씨름하는)도 Hansberry의 이야기에 나온다.", "인종 차별과 아메리칸드림은 Hansberry의 희곡 A Raisin in the Sun이 다루는 내용이다(7번 문장)."], "ev_en": "When Picasso painted his masterpiece Guernica in 1937, he captured the heartbreaking and cruel nature of war, and offered the world a way to consider the universal suffering caused by the Spanish Civil War. When Lorraine Hansberry wrote her play A Raisin in the Sun, she gave us a powerful story of people struggling with racism, discrimination, and the pursuit of the American dream while also offering a touching portrait of family life.", "ev_ko": "Picasso가 그의 걸작 Guernica를 1937년에 그렸을 때, 그는 가슴 아프고 잔인한 전쟁의 본질을 포착했고, 스페인 내전으로 인한 보편적인 고통을 숙고할 방법을 세상에 제공했다. Lorraine Hansberry가 그녀의 희곡 A Raisin in the Sun을 썼을 때, 그녀는 또한 가족생활에 대한 감동적인 초상화를 제공하면서 인종 차별, 차별, 아메리칸드림의 추구를 위해 고군분투하는 사람들의 강력한 이야기를 우리에게 주었다."}, {"s": "Hansberry의 희곡은 차별에 맞서 고군분투하는 사람들의 이야기를 주면서 가족생활의 감동적인 초상도 보여 준다.", "t": true, "why": ["7번 문장의 내용이다.", "touching portrait of family life(가족생활에 대한 감동적인 초상)가 근거 표현이다."], "ev_en": "When Lorraine Hansberry wrote her play A Raisin in the Sun, she gave us a powerful story of people struggling with racism, discrimination, and the pursuit of the American dream while also offering a touching portrait of family life.", "ev_ko": "Lorraine Hansberry가 그녀의 희곡 A Raisin in the Sun을 썼을 때, 그녀는 또한 가족생활에 대한 감동적인 초상화를 제공하면서 인종 차별, 차별, 아메리칸드림의 추구를 위해 고군분투하는 사람들의 강력한 이야기를 우리에게 주었다."}], "flow": {"fixed": "예술은 단순히 달콤한 것 이상으로 인간 경험의 전 범위에 대한 정서적 연결을 제공한다.", "order": ["예술에서 도전적이고 불편한 것이 있을 때 우리가 기꺼이 그것에 참여하면 불편함이 변화의 가능성을 주고 강력한 미적 경험이 될 수 있다.", "이런 방식으로 예술은 그렇지 않으면 어렵고 불편한 아이디어와 개념과 씨름하게 해 주는 매개체가 된다.", "예를 들어 Picasso는 Guernica로 전쟁의 잔인한 본질을 포착했고, Hansberry는 희곡으로 인종 차별과 아메리칸드림의 추구 속에서 고군분투하는 사람들과 가족의 모습을 보여 주었다."], "clue": ["앞에서 말한 \u2018달콤함 이상\u2019이 불편함의 가치로 구체화됨", "\u2018이런 방식으로\u2019가 앞의 불편함을 마주하는 과정을 받아 정리함", "\u2018예를 들어\u2019가 앞의 일반적 설명을 구체적인 작품 사례로 보여 줌"], "why": ["예술은 달콤함 그 이상", "불편함을 마주하면 변화의 가능성", "예술은 어려운 개념과 씨름하는 매개체", "Picasso와 Hansberry의 예"], "cards": ["이런 방식으로 예술은 그렇지 않으면 어렵고 불편한 아이디어와 개념과 씨름하게 해 주는 매개체가 된다.", "예술에서 도전적이고 불편한 것이 있을 때 우리가 기꺼이 그것에 참여하면 불편함이 변화의 가능성을 주고 강력한 미적 경험이 될 수 있다.", "예를 들어 Picasso는 Guernica로 전쟁의 잔인한 본질을 포착했고, Hansberry는 희곡으로 인종 차별과 아메리칸드림의 추구 속에서 고군분투하는 사람들과 가족의 모습을 보여 주었다."], "answer": [1, 0, 2]}, "sents": [{"n": 1, "en": "The arts and aesthetics offer emotional connection to the full range of human experience.", "ko": "예술과 미학은 인간 경험의 전 범위에 대한 정서적인 연결을 제공한다."}, {"n": 2, "en": "\u201cThe arts can be more than just sugar on the tongue,\u201d Anjan Chatterjee, a professor at the University of Pennsylvania, says.", "ko": "\u201c예술은 단순히 혀 위의 설탕 이상의 것이 될 수 있다,\u201d라고 Pennsylvania 대학교의 교수인 Anjan Chatterjee는 말한다."}, {"n": 3, "en": "\u201cIn art, when there\u2019s something challenging, which can also be uncomfortable, this discomfort, if we\u2019re willing to engage with it, offers the possibility of some change, some transformation.", "ko": "\u201c예술에서, 무언가 도전적인 것이 있고 그것이 또한 불편할 수 있을 때, 이 불편은, 만약 우리가 기꺼이 그것에 참여하려 한다면, 어떤 변화, 어떤 변형의 가능성을 제공한다."}, {"n": 4, "en": "That can also be a powerful aesthetic experience.\u201d", "ko": "그것은 또한 강력한 미적 경험이 될 수 있다.\u201d"}, {"n": 5, "en": "The arts, in this way, become vehicles to contend with ideas and concepts that are difficult and uncomfortable otherwise.", "ko": "예술은, 이런 방식으로, 그렇지 않았더라면 어렵고 불편한 아이디어 및 개념들과 싸우는 매개체가 된다."}, {"n": 6, "en": "When Picasso painted his masterpiece Guernica in 1937, he captured the heartbreaking and cruel nature of war, and offered the world a way to consider the universal suffering caused by the Spanish Civil War.", "ko": "Picasso가 그의 걸작 Guernica를 1937년에 그렸을 때, 그는 가슴 아프고 잔인한 전쟁의 본질을 포착했고, 스페인 내전으로 인한 보편적인 고통을 숙고할 방법을 세상에 제공했다."}, {"n": 7, "en": "When Lorraine Hansberry wrote her play A Raisin in the Sun, she gave us a powerful story of people struggling with racism, discrimination, and the pursuit of the American dream while also offering a touching portrait of family life.", "ko": "Lorraine Hansberry가 그녀의 희곡 A Raisin in the Sun을 썼을 때, 그녀는 또한 가족생활에 대한 감동적인 초상화를 제공하면서 인종 차별, 차별, 아메리칸드림의 추구를 위해 고군분투하는 사람들의 강력한 이야기를 우리에게 주었다."}]}, {"id": "2311-23", "short": "23년 11월 23번", "group": "23년 11월", "num": 23, "topic_ko": "설득과 논리가 아닌 바람잡이로 쇼핑 카트를 받아들이게 한 Goldman의 아이디어", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "Goldman이 쇼핑 카트를 발명해 도입했고, 쇼핑객에게 편리한 훌륭한 장치였음"}, {"n": 2, "label": "문제", "from": 3, "to": 7, "summary_ko": "광고와 설명에도 남성은 나약해 보일까 봐, 여성은 유모차가 떠올라 카트를 꺼렸고 노인 몇 명만 사용함"}, {"n": 3, "label": "해결과 결과", "from": 8, "to": 13, "summary_ko": "모델과 직원을 이용한 아이디어가 전환점이 되어 몇 주 만에 쇼핑객들이 카트를 받아들임"}], "gloss": [{"w": "device", "m": "장치, 기구"}, {"w": "seek", "m": "구하다, 찾다", "form": "seeking", "note": "동사 seek의 동명사형(전치사 without 뒤)"}, {"w": "persuade", "m": "설득하다"}, {"w": "reluctant", "m": "꺼리는, 내키지 않는"}, {"w": "elderly", "m": "나이가 지긋한, 노인의"}, {"w": "majority", "m": "대다수"}, {"w": "hit upon", "m": "(생각 등을) 떠올리다", "form": "hit", "note": "동사 hit upon의 과거형(현재형\u00b7과거형 모양이 같음)"}, {"w": "hire", "m": "고용하다", "form": "hired", "note": "동사 hire의 과거형(-ed)"}, {"w": "shill", "m": "바람잡이(손님인 척 위장해 분위기를 띄우는 사람)", "form": "shills", "note": "명사 shill의 복수형"}, {"w": "disguise", "m": "위장하다", "form": "disguised", "note": "동사 disguise의 과거분사형(앞의 shills를 꾸며 줌)"}, {"w": "accomplish", "m": "달성하다, 해내다", "form": "accomplished", "note": "동사 accomplish의 과거형(-ed)"}, {"w": "readily", "m": "기꺼이, 쉽게"}, {"w": "wheel", "m": "(바퀴 달린 것을) 밀다, 몰다"}], "qa": [{"chunk": 1, "q": "Goldman이 발명한 쇼핑 카트의 장점으로 알맞은 것은?", "opts": ["쇼핑객이 지치거나 남의 도움을 구하지 않고도 원하는 만큼 구매하기 쉬워진다.", "상품 가격이 크게 내려간다.", "가게 규모를 줄여도 된다."], "ans": 0, "why": ["2번 문장이 근거이다.", "카트는 지치거나 다른 사람의 도움을 구하지 않고 원하는 만큼 사게 해 주는 훌륭한 장치였다.", "가격이 내려간다거나 가게 규모를 줄인다는 내용은 지문에 없다."], "ev_en": "It was an excellent device that would make it easy for shoppers to buy as much as they wanted without getting tired or seeking others\u2019 help.", "ev_ko": "그것은 쇼핑객들이 지치거나 다른 사람들의 도움을 구하지 않고 그들이 원했던 만큼 구매하는 것을 쉽게 만들어 준 훌륭한 장치였다."}, {"chunk": 2, "q": "쇼핑객들이 카트를 사용하지 않으려 한 이유로 알맞은 것은?", "opts": ["남성은 나약해 보일까 봐, 여성은 유모차가 떠올라서 꺼렸다.", "남성은 가격이 비싸서, 여성은 너무 무거워서 꺼렸다.", "남성은 사용법을 몰라서, 여성은 나이가 많아서 꺼렸다."], "ans": 0, "why": ["4번과 5번 문장이 근거이다.", "남성은 카트를 밀면 나약해 보일 것이라 생각했고, 여성은 카트가 유모차를 떠올리게 해서 손대려 하지 않았다.", "가격, 무게, 사용법, 나이를 이유로 든 내용은 지문에 없다."], "ev_en": "Men were reluctant because they thought they would appear weak if they pushed such carts instead of carrying their shopping. Women wouldn\u2019t touch them because the carts reminded them of baby carriages.", "ev_ko": "남성들은 그들의 쇼핑한 물건을 들고 다니는 대신 만약 그들이 그런 카트들을 민다면 그들이 나약해 보일 것으로 생각했기 때문에 꺼렸다. 여성들은 카트들이 그들에게 유모차를 연상시키기 때문에 그것들에 손대려 하지 않았다."}, {"chunk": 3, "q": "Goldman이 떠올린 아이디어로 알맞은 것은?", "opts": ["여러 연령의 모델을 고용해 카트를 밀며 쇼핑하게 했다.", "광고를 더 많이 하고 설명을 더 자세히 했다.", "카트 값을 내려 주었다."], "ans": 0, "why": ["9번 문장이 근거이다.", "남녀 여러 연령의 모델을 고용해 상점에서 카트를 밀며 쇼핑하도록 요청했다.", "광고와 설명은 이미 반복했는데도 실패한 방법이다(3번 문장).", "카트 값을 내렸다는 내용은 지문에 없다."], "ev_en": "He hired several models, men and women, of different ages and asked them to wheel the carts in the store and shop.", "ev_ko": "그는 다른 연령대의 남자와 여자 모델들을 고용했고, 그들에게 상점에서 카트들을 밀고 쇼핑하도록 요청했다."}], "tf": [{"s": "카트를 사용하는 사람은 처음에 오직 몇 명의 노인 쇼핑객뿐이었다.", "t": true, "why": ["6번 문장의 내용이다.", "카트를 쓰는 사람은 몇몇 노인뿐이었고, 이것이 카트를 대다수에게 더 매력 없게 만들었다."], "ev_en": "It was only a few elderly shoppers who used them.", "ev_ko": "그것들을 사용하는 사람들은 오직 몇 명의 노인 쇼핑객들뿐이었다."}, {"s": "여성들은 카트가 나약해 보이게 한다는 이유로 카트를 꺼렸다.", "t": false, "why": ["이유가 바뀐 진술이다.", "나약해 보일까 봐 꺼린 쪽은 남성이다(4번 문장).", "여성은 카트가 유모차를 떠올리게 해서 손대려 하지 않았다."], "ev_en": "Women wouldn\u2019t touch them because the carts reminded them of baby carriages.", "ev_ko": "여성들은 카트들이 그들에게 유모차를 연상시키기 때문에 그것들에 손대려 하지 않았다."}, {"s": "Goldman은 반복한 광고와 설명으로 쇼핑객들을 설득하는 데 성공했다.", "t": false, "why": ["지문과 반대이다.", "반복된 광고와 설명에도 불구하고 쇼핑객들을 설득할 수 없었다는 것이 3번 문장의 내용이다.", "설득에 성공한 것은 모델과 직원을 이용한 아이디어 덕분이다."], "ev_en": "But Goldman discovered that in spite of his repeated advertisements and explanations, he could not persuade his shoppers to use the wheeled carts.", "ev_ko": "하지만 Goldman은 그의 반복적인 광고와 설명에도 불구하고, 그의 쇼핑객들에게 바퀴 달린 카트들을 사용하도록 설득할 수 없다는 것을 알게 됐다."}, {"s": "입구 근처의 젊은 여성 직원은 일반 쇼핑객들에게 모두가 카트를 사용하고 있다고 말했다.", "t": true, "why": ["10번 문장의 내용이다.", "직원은 Look, everyone is using the carts.(보라, 모든 사람이 카트를 사용하고 있다.)라고 말했다."], "ev_en": "A young woman employee standing near the entrance told the regular shoppers, \u2018Look, everyone is using the carts. Why don\u2019t you?\u2019", "ev_ko": "입구 근처에 서 있던 한 젊은 여성 직원이 일반 쇼핑객들에게 \u2018보세요, 모든 사람이 카트를 사용하고 있습니다. 해 보는 게 어떠세요?\u2019라고 말했다."}, {"s": "쇼핑객들이 카트를 기꺼이 받아들이기까지는 몇 달이 걸렸다.", "t": false, "why": ["기간이 바뀐 진술이다.", "13번 문장에서 Within a few weeks(몇 주 만에) 쇼핑객들이 카트를 기꺼이 받아들였다고 한다.", "몇 달이 아니라 몇 주이다."], "ev_en": "Within a few weeks shoppers readily accepted those carts.", "ev_ko": "몇 주 만에 쇼핑객들은 그 카트들을 기꺼이 받아들였다."}], "flow": {"fixed": "Sylvan Goldman은 쇼핑 카트를 발명해 1937년에 가게들에 도입했는데, 쇼핑객이 지치거나 도움을 구하지 않고도 원하는 만큼 사게 해 주는 훌륭한 장치였다.", "order": ["그러나 광고와 설명에도 남성은 나약해 보일까 봐, 여성은 유모차가 떠올라서 카트를 꺼렸고, 사용하는 사람은 몇몇 노인뿐이었다.", "이에 Goldman은 여러 연령의 모델을 고용해 카트를 밀며 쇼핑하게 했고, 입구 근처의 젊은 여직원은 일반 쇼핑객들에게 모두가 쓰고 있다고 말했다.", "그 결과 일반 쇼핑객으로 위장한 몇몇 바람잡이가 논리와 광고가 못 한 일을 해내서, 몇 주 만에 쇼핑객들이 카트를 기꺼이 받아들였다."], "clue": ["'그러나'로 앞의 훌륭한 장치라는 내용을 뒤집어 사용을 꺼린 문제 상황을 말함", "'이에'가 앞의 문제를 해결하려는 Goldman의 대응을 이끎", "'그 결과'로 앞의 아이디어가 가져온 변화를 마무리함"], "why": ["카트는 훌륭한 장치", "그러나 쇼핑객은 사용을 꺼림", "모델과 직원을 이용한 아이디어", "몇 주 만에 카트가 받아들여짐"], "cards": ["그 결과 일반 쇼핑객으로 위장한 몇몇 바람잡이가 논리와 광고가 못 한 일을 해내서, 몇 주 만에 쇼핑객들이 카트를 기꺼이 받아들였다.", "그러나 광고와 설명에도 남성은 나약해 보일까 봐, 여성은 유모차가 떠올라서 카트를 꺼렸고, 사용하는 사람은 몇몇 노인뿐이었다.", "이에 Goldman은 여러 연령의 모델을 고용해 카트를 밀며 쇼핑하게 했고, 입구 근처의 젊은 여직원은 일반 쇼핑객들에게 모두가 쓰고 있다고 말했다."], "answer": [1, 2, 0]}, "sents": [{"n": 1, "en": "Sylvan Goldman invented the shopping cart and introduced it in his stores in 1937.", "ko": "Sylvan Goldman은 쇼핑 카트를 발명하고 1937년에 그의 가게들에 그것을 도입했다."}, {"n": 2, "en": "It was an excellent device that would make it easy for shoppers to buy as much as they wanted without getting tired or seeking others\u2019 help.", "ko": "그것은 쇼핑객들이 지치거나 다른 사람들의 도움을 구하지 않고 그들이 원했던 만큼 구매하는 것을 쉽게 만들어 준 훌륭한 장치였다."}, {"n": 3, "en": "But Goldman discovered that in spite of his repeated advertisements and explanations, he could not persuade his shoppers to use the wheeled carts.", "ko": "하지만 Goldman은 그의 반복적인 광고와 설명에도 불구하고, 그의 쇼핑객들에게 바퀴 달린 카트들을 사용하도록 설득할 수 없다는 것을 알게 됐다."}, {"n": 4, "en": "Men were reluctant because they thought they would appear weak if they pushed such carts instead of carrying their shopping.", "ko": "남성들은 그들의 쇼핑한 물건을 들고 다니는 대신 만약 그들이 그런 카트들을 민다면 그들이 나약해 보일 것으로 생각했기 때문에 꺼렸다."}, {"n": 5, "en": "Women wouldn\u2019t touch them because the carts reminded them of baby carriages.", "ko": "여성들은 카트들이 그들에게 유모차를 연상시키기 때문에 그것들에 손대려 하지 않았다."}, {"n": 6, "en": "It was only a few elderly shoppers who used them.", "ko": "그것들을 사용하는 사람들은 오직 몇 명의 노인 쇼핑객들뿐이었다."}, {"n": 7, "en": "That made the carts even less attractive to the majority of the shoppers.", "ko": "그것은 카트들을 대다수 쇼핑객들에게 훨씬 덜 매력적이도록 만들었다."}, {"n": 8, "en": "Then Goldman hit upon an idea.", "ko": "그때 Goldman이 한 아이디어를 떠올렸다."}, {"n": 9, "en": "He hired several models, men and women, of different ages and asked them to wheel the carts in the store and shop.", "ko": "그는 다른 연령대의 남자와 여자 모델들을 고용했고, 그들에게 상점에서 카트들을 밀고 쇼핑하도록 요청했다."}, {"n": 10, "en": "A young woman employee standing near the entrance told the regular shoppers, \u2018Look, everyone is using the carts. Why don\u2019t you?\u2019", "ko": "입구 근처에 서 있던 한 젊은 여성 직원이 일반 쇼핑객들에게 \u2018보세요, 모든 사람이 카트를 사용하고 있습니다. 해 보는 게 어떠세요?\u2019라고 말했다."}, {"n": 11, "en": "That was the turning point.", "ko": "그것이 전환점이었다."}, {"n": 12, "en": "A few shills disguised as regular shoppers easily accomplished what logic, explanations, and advertisements failed to do.", "ko": "일반 쇼핑객들로 위장한 몇몇의 바람잡이들이 논리, 설명, 그리고 광고가 하지 못한 것을 쉽게 달성했다."}, {"n": 13, "en": "Within a few weeks shoppers readily accepted those carts.", "ko": "몇 주 만에 쇼핑객들은 그 카트들을 기꺼이 받아들였다."}]}, {"id": "2311-30", "short": "23년 11월 30번", "group": "23년 11월", "num": 30, "topic_ko": "기술 변화에 따라 사생활 보호를 어떻게 확장할지 고민할 필요", "chunks": [{"n": 1, "label": "주장", "from": 1, "to": 3, "summary_ko": "기술은 사생활 개념을 바꾸며, 새 능력이 남의 정보를 보는 것을 정당화하지는 않고 보호 확장을 고민하게 함"}, {"n": 2, "label": "예시", "from": 4, "to": 6, "summary_ko": "카메라가 등장했을 때 새 법을 두고 다투다 사적\u00b7공적 공간의 구별이 재확인되고, 공공장소에서는 동의한 것으로 봄"}, {"n": 3, "label": "현재의 태도", "from": 7, "to": 7, "summary_ko": "일부는 감시 카메라가 불편해도 대부분은 관찰되지 않을 권리를 포기하는 편이 해가 적다고 받아들임"}], "gloss": [{"w": "privacy", "m": "사생활, 프라이버시"}, {"w": "justify", "m": "정당화하다"}, {"w": "advance", "m": "발전, 진보", "form": "advances", "note": "명사 advance의 복수형"}, {"w": "citizen", "m": "시민", "form": "citizens", "note": "명사 citizen의 복수형"}, {"w": "enact", "m": "(법을) 제정하다", "form": "enacted", "note": "동사 enact의 과거분사형(수동태 should be enacted)"}, {"w": "permission", "m": "허가, 허락"}, {"w": "reconsideration", "m": "재고, 다시 생각함"}, {"w": "consent", "m": "동의, 허락"}, {"w": "voluntarily", "m": "자발적으로"}, {"w": "surveillance", "m": "감시"}, {"w": "adjust", "m": "적응하다, 조정하다", "form": "adjusted", "note": "동사 adjust의 과거분사형(have adjusted, 현재완료)"}, {"w": "harm", "m": "해, 피해"}], "qa": [{"chunk": 1, "q": "기술의 발전이 시민들과 정책 입안자들에게 요구하는 것은?", "opts": ["새 기술을 최대한 자유롭게 활용하는 것", "사생활 보호를 어떻게 확장해야 할지 고려하는 것", "사생활이라는 개념을 포기하는 것"], "ans": 1, "why": ["3번 문장이 근거이다.", "Rather(오히려)로 이어지며, 기술의 발전은 사생활 보호를 어떻게 확장해야 하는지 고려할 것을 요구한다고 한다.", "새 능력이 있다고 해서 남을 관찰하는 것이 정당화되지는 않는다(2번 문장)."], "ev_en": "Rather, advances in technology require citizens and policy makers to consider how privacy protections should be expanded.", "ev_ko": "오히려, 기술의 발전은 시민들과 정책 입안자들이 어떻게 사생활 보호가 확장되어야 하는지 고려할 것을 요구한다."}, {"chunk": 2, "q": "대부분의 문화에서 공공장소에 자발적으로 들어간 사람에 대해 내린 결정으로 알맞은 것은?", "opts": ["보여지고 녹화되는 것에 자동적으로 동의한 것으로 본다.", "어떤 경우에도 녹화 전에 따로 허락을 받아야 한다.", "공공장소에서도 사적 공간과 똑같이 보호받는다."], "ans": 0, "why": ["6번 문장이 근거이다.", "자발적으로 공공장소에 발을 들여놓으면 보여지고, 따라서 녹화되는 것에 자동적으로 동의한 것으로 결정되었다.", "5번 문장에서 사적 공간과 공적 공간의 구별이 재확인되었으므로 두 공간을 똑같이 보호한다는 진술은 틀리다."], "ev_en": "It was determined by most cultures that people automatically gave consent to being seen \u2015 and thus recorded \u2015 once they voluntarily stepped into a public space.", "ev_ko": "일단 사람들이 자발적으로 공공장소에 발을 들여놓으면, 보여지고, 따라서 녹화되는 것에 자동적으로 동의하는 것으로 대부분의 문화에서 결정되었다."}, {"chunk": 3, "q": "감시 카메라 확산에 대한 대부분의 문화권 시민들의 태도로 알맞은 것은?", "opts": ["관찰되지 않을 권리를 포기하는 것이 감시가 없는 것보다 해가 적다는 사실에 적응해 왔다.", "모든 시민이 감시 카메라에 강하게 반대한다.", "감시 카메라를 금지하는 새 법을 만들었다."], "ans": 0, "why": ["7번 문장이 근거이다.", "일부는 불편해하지만 대부분의 시민은 관찰되지 않을 권리를 포기하는 것이 감시받지 못하는 것보다 해가 적다는 사실에 순응해 왔다.", "모든 시민이 반대한다거나 금지법을 만들었다는 내용은 지문에 없다."], "ev_en": "Although some people might be uncomfortable with the spread of surveillance cameras, citizens in most cultures have adjusted to the fact that giving up the right not to be observed in these circumstances causes less harm to the community than failing to have surveillance.", "ev_ko": "일부 사람들은 감시 카메라들의 확산을 불편하게 여길지도 모르지만, 대부분의 문화권에 있는 시민들은 이러한 상황에서 관찰되지 않을 권리를 포기하는 것이 감시받지 못하는 것보다 지역 사회에 더 적은 해를 끼친다는 사실에 순응해 왔다."}], "tf": [{"s": "누군가에게 정보에 접근하거나 다른 사람의 행동을 볼 새로운 능력이 있다는 사실이 그렇게 하는 것을 정당화하지는 않는다.", "t": true, "why": ["2번 문장의 내용이다.", "능력이 생긴 것과 그것을 써도 되는 것은 별개라는 뜻이다."], "ev_en": "The fact that someone has a new ability to access information or watch the actions of another does not justify doing so.", "ev_ko": "누군가가 정보에 접근하거나 다른 사람의 행동을 관찰하는 새로운 능력을 갖추고 있다는 사실은 그렇게 하는 것을 정당화하지 않는다."}, {"s": "카메라가 처음 쓰이게 되었을 때 국가와 시민들은 허가 없이 찍히지 않도록 보호하는 새 법이 필요한지에 대해 이견 없이 합의했다.", "t": false, "why": ["지문과 반대이다.", "4번 문장은 새 법이 제정되어야 하는지를 두고 국가와 시민들이 struggled(다투었다, 고심했다)고 한다.", "합의가 아니라 논란이 있었다."], "ev_en": "For example, when cameras first became available for commercial and private use, nations and citizens struggled over whether new laws should be enacted to protect individuals from being photographed without their permission.", "ev_ko": "예를 들어, 카메라들이 상업적이고 사적인 용도로 처음 사용될 수 있게 되었을 때, 국가들과 시민들은 그들의 허가 없이 개인들이 사진에 찍히는 것으로부터 보호하기 위해 새로운 법들이 제정되어야 하는지에 대해 투쟁했다."}, {"s": "카메라라는 새 기술이 가져온 사생활에 대한 재고는 사적 공간과 공적 공간의 구별을 재확인했다.", "t": true, "why": ["5번 문장의 내용이다."], "ev_en": "The reconsideration of privacy brought about by this new technology re-affirmed a distinction between private and public spaces.", "ev_ko": "이 새로운 기술이 가져온 사생활에 대한 재고는 사적 및 공적 공간의 구별을 재확인했다."}, {"s": "일부 사람들은 감시 카메라의 확산을 불편하게 여길 수 있다.", "t": true, "why": ["7번 문장의 내용이다.", "Although some people might be uncomfortable with the spread of surveillance cameras(일부 사람들은 감시 카메라의 확산을 불편하게 여길지도 모르지만)라고 한다."], "ev_en": "Although some people might be uncomfortable with the spread of surveillance cameras, citizens in most cultures have adjusted to the fact that giving up the right not to be observed in these circumstances causes less harm to the community than failing to have surveillance.", "ev_ko": "일부 사람들은 감시 카메라들의 확산을 불편하게 여길지도 모르지만, 대부분의 문화권에 있는 시민들은 이러한 상황에서 관찰되지 않을 권리를 포기하는 것이 감시받지 못하는 것보다 지역 사회에 더 적은 해를 끼친다는 사실에 순응해 왔다."}, {"s": "대부분의 문화권 시민들은 감시를 하지 않는 것이 감시를 하는 것보다 지역 사회에 더 적은 해를 끼친다고 받아들였다.", "t": false, "why": ["비교 방향이 뒤바뀐 진술이다.", "관찰되지 않을 권리를 포기하는 것이 감시받지 못하는 것보다 해가 더 적다고 받아들였다.", "즉 감시가 없는 쪽이 해가 더 크다는 뜻이다."], "ev_en": "Although some people might be uncomfortable with the spread of surveillance cameras, citizens in most cultures have adjusted to the fact that giving up the right not to be observed in these circumstances causes less harm to the community than failing to have surveillance.", "ev_ko": "일부 사람들은 감시 카메라들의 확산을 불편하게 여길지도 모르지만, 대부분의 문화권에 있는 시민들은 이러한 상황에서 관찰되지 않을 권리를 포기하는 것이 감시받지 못하는 것보다 지역 사회에 더 적은 해를 끼친다는 사실에 순응해 왔다."}], "flow": {"fixed": "기술은 사람들이 사생활을 이해하는 방식을 바꾸는데, 새로운 능력이 생겼다고 해서 남의 정보를 보는 것이 정당해지지는 않고 오히려 사생활 보호를 어떻게 넓힐지 고민해야 한다.", "order": ["예를 들어 카메라가 처음 쓰이게 되었을 때, 국가와 시민들은 허락 없이 찍히지 않도록 보호하는 새 법이 필요한지를 두고 다투었다.", "이 카메라 논쟁을 거치며 사적 공간과 공적 공간의 구별이 다시 확인되었고, 대부분의 문화는 자발적으로 공공장소에 들어간 사람이 보이고 녹화되는 것에 동의한 것으로 보기로 했다.", "오늘날 일부가 감시 카메라의 확산을 불편해하더라도, 대부분의 시민은 관찰되지 않을 권리를 포기하는 편이 감시가 없는 것보다 해가 적다고 받아들여 왔다."], "clue": ["'예를 들어'로 앞의 주장을 카메라 사례로 뒷받침함", "'이 카메라 논쟁'이 앞의 새 법을 둘러싼 다툼을 받아 그 결론을 말함", "'오늘날'로 앞의 결정에서 현재의 감시 카메라에 대한 태도로 이어짐"], "why": ["기술은 사생활 개념을 바꿈", "카메라가 등장하며 새 법 논란이 생김", "사적\u00b7공적 공간 구별 재확인", "감시 카메라를 받아들여 옴"], "cards": ["이 카메라 논쟁을 거치며 사적 공간과 공적 공간의 구별이 다시 확인되었고, 대부분의 문화는 자발적으로 공공장소에 들어간 사람이 보이고 녹화되는 것에 동의한 것으로 보기로 했다.", "예를 들어 카메라가 처음 쓰이게 되었을 때, 국가와 시민들은 허락 없이 찍히지 않도록 보호하는 새 법이 필요한지를 두고 다투었다.", "오늘날 일부가 감시 카메라의 확산을 불편해하더라도, 대부분의 시민은 관찰되지 않을 권리를 포기하는 편이 감시가 없는 것보다 해가 적다고 받아들여 왔다."], "answer": [1, 0, 2]}, "sents": [{"n": 1, "en": "Technology changes how individuals and societies understand the concept of privacy.", "ko": "기술은 개인들과 사회가 사생활의 개념을 이해하는 방식을 변화시킨다."}, {"n": 2, "en": "The fact that someone has a new ability to access information or watch the actions of another does not justify doing so.", "ko": "누군가가 정보에 접근하거나 다른 사람의 행동을 관찰하는 새로운 능력을 갖추고 있다는 사실은 그렇게 하는 것을 정당화하지 않는다."}, {"n": 3, "en": "Rather, advances in technology require citizens and policy makers to consider how privacy protections should be expanded.", "ko": "오히려, 기술의 발전은 시민들과 정책 입안자들이 어떻게 사생활 보호가 확장되어야 하는지 고려할 것을 요구한다."}, {"n": 4, "en": "For example, when cameras first became available for commercial and private use, nations and citizens struggled over whether new laws should be enacted to protect individuals from being photographed without their permission.", "ko": "예를 들어, 카메라들이 상업적이고 사적인 용도로 처음 사용될 수 있게 되었을 때, 국가들과 시민들은 그들의 허가 없이 개인들이 사진에 찍히는 것으로부터 보호하기 위해 새로운 법들이 제정되어야 하는지에 대해 투쟁했다."}, {"n": 5, "en": "The reconsideration of privacy brought about by this new technology re-affirmed a distinction between private and public spaces.", "ko": "이 새로운 기술이 가져온 사생활에 대한 재고는 사적 및 공적 공간의 구별을 재확인했다."}, {"n": 6, "en": "It was determined by most cultures that people automatically gave consent to being seen \u2015 and thus recorded \u2015 once they voluntarily stepped into a public space.", "ko": "일단 사람들이 자발적으로 공공장소에 발을 들여놓으면, 보여지고, 따라서 녹화되는 것에 자동적으로 동의하는 것으로 대부분의 문화에서 결정되었다."}, {"n": 7, "en": "Although some people might be uncomfortable with the spread of surveillance cameras, citizens in most cultures have adjusted to the fact that giving up the right not to be observed in these circumstances causes less harm to the community than failing to have surveillance.", "ko": "일부 사람들은 감시 카메라들의 확산을 불편하게 여길지도 모르지만, 대부분의 문화권에 있는 시민들은 이러한 상황에서 관찰되지 않을 권리를 포기하는 것이 감시받지 못하는 것보다 지역 사회에 더 적은 해를 끼친다는 사실에 순응해 왔다."}]}, {"id": "2311-31", "short": "23년 11월 31번", "group": "23년 11월", "num": 31, "topic_ko": "기적의 기원은 자연이 아니라 우리의 무지에 있음", "chunks": [{"n": 1, "label": "우연과 기적", "from": 1, "to": 2, "summary_ko": "통계적으로 불가능한 우연을 기적이라 하지만, Montaigne는 기적의 기원이 우리의 무지에 있다고 함"}, {"n": 2, "label": "기적의 정체", "from": 3, "to": 4, "summary_ko": "기적이라 불렸던 일은 나중에 자연 법칙이나 기술 발전으로 밝혀졌으며 신비한 것이 아직 기적은 아님"}, {"n": 3, "label": "기적은 핑계", "from": 5, "to": 8, "summary_ko": "기적은 더 높은 힘을 가정하지만 조사하는 대신 기적이라 정의하는 것은 생각하기 게으른 사람들의 핑계임"}], "gloss": [{"w": "coincidence", "m": "우연의 일치, 우연"}, {"w": "statistically", "m": "통계적으로"}, {"w": "irrational", "m": "비이성적인"}, {"w": "miracle", "m": "기적"}, {"w": "ignorance", "m": "무지, 모름"}, {"w": "obedience", "m": "순응, 복종"}, {"w": "phrase", "m": "(말로) 표현하다", "form": "phrased", "note": "동사 phrase의 과거형(-ed)"}, {"w": "assume", "m": "가정하다, 전제하다", "form": "assumes", "note": "동사 assume의 3인칭 단수 현재형(주어 The miracle이 단수)"}, {"w": "intervention", "m": "개입"}, {"w": "divine", "m": "신의, 신적인"}, {"w": "revelation", "m": "계시, 드러남"}, {"w": "investigate", "m": "조사하다", "form": "investigating", "note": "동사 investigate의 동명사형(Instead of 뒤)"}, {"w": "excuse", "m": "핑계, 변명"}, {"w": "methodical", "m": "체계적인"}], "qa": [{"chunk": 1, "q": "Montaigne에 따르면 기적의 기원은 어디에 있는가?", "opts": ["자연 그 자체", "신적인 계시와 영감", "자연에 대한 우리의 지식수준, 곧 우리의 무지"], "ans": 2, "why": ["2번 문장이 근거이다.", "기적의 기원은 자연 그 자체가 아니라 자연에 대한 우리의 지식수준, 곧 우리의 무지에 있다고 한다.", "자연 그 자체는 not in nature itself(자연 그 자체에 있지 않다)로 부정되었다."], "ev_en": "But, as Montaigne has said, \u201cthe origin of a miracle is in our ignorance, at the level of our knowledge of nature, and not in nature itself.\u201d", "ev_ko": "그러나, Montaigne가 말했듯이, \u201c기적의 기원은 자연 그 자체가 아니라 자연에 대한 우리의 지식수준에서, 우리의 무지에 있다.\u201d"}, {"chunk": 2, "q": "영광스러운 기적들이 나중에 어떤 것으로 발견되어 왔다고 하는가?", "opts": ["통계적으로 불가능한 우연", "인간이 이해할 수 없는 더 높은 힘의 개입", "자연의 법칙에 대한 순응이거나 당시 널리 알려지지 않았던 기술적 발전"], "ans": 2, "why": ["3번 문장이 근거이다.", "기적이라 불리던 일들은 자연 법칙에 따른 것이거나 당시 널리 알려지지 않았던 기술적 발전이었음이 나중에 밝혀졌다.", "더 높은 힘의 개입은 기적이 가정하는 내용일 뿐(5번 문장) 나중에 발견된 정체가 아니다."], "ev_en": "Glorious miracles have been later on discovered to be obedience to the laws of nature or a technological development that was not widely known at the time.", "ev_ko": "영광스러운 기적들은 자연의 법칙에 대한 순응으로서, 혹은 당시에는 널리 알려지지 않았던 기술적 발전으로서 나중에 발견되어 왔다."}, {"chunk": 3, "q": "글쓴이가 기적을 바라보는 관점으로 알맞은 것은?", "opts": ["더 높은 힘의 개입이 증명된 사건이다.", "자연이 만들어 낸 통계적 필연이다.", "사건의 근원을 조사하는 대신 붙이는 이름이며, 생각하기 게으른 사람들의 핑계이다."], "ans": 2, "why": ["7번과 8번 문장이 근거이다.", "우리는 사건의 근원을 조사하는 대신 기적이라고 정의하며, 기적은 생각하는 데 너무 게으른 사람들의 핑계라고 한다.", "더 높은 힘의 개입은 기적이 가정하는 것일 뿐 글쓴이가 증명되었다고 말하는 것이 아니다."], "ev_en": "Instead of checking it out, investigating and finding the source of the event, we define it as a miracle. The miracle, then, is the excuse of those who are too lazy to think.", "ev_ko": "그것을 확인하는 것, 즉, 그 사건의 근원을 조사하고 찾는 것 대신에, 우리는 그것을 기적으로 정의한다. 그렇다면, 기적은 생각하는 데 너무 게으른 사람들의 핑계이다."}], "tf": [{"s": "Goethe는 신비한 것들이 아직 기적은 아니라고 표현했다.", "t": true, "why": ["4번 문장의 내용이다.", "Things that are mysterious are not yet miracles.(신비한 것들은 아직 기적이 아니다.)라고 했다."], "ev_en": "As the German poet, Goethe, phrased it: \u201cThings that are mysterious are not yet miracles.\u201d", "ev_ko": "독일 시인 Goethe가 그것을 표현했듯이, \u201c\u2018신비한\u2019 것들은 아직 \u2018기적\u2019이 \u2018아니다\u2019.\u201d"}, {"s": "Montaigne는 기적의 기원이 자연 그 자체에 있다고 말했다.", "t": false, "why": ["지문과 반대이다.", "2번 문장에서 기적의 기원은 자연 그 자체가 아니라 우리의 무지에 있다고 한다."], "ev_en": "But, as Montaigne has said, \u201cthe origin of a miracle is in our ignorance, at the level of our knowledge of nature, and not in nature itself.\u201d", "ev_ko": "그러나, Montaigne가 말했듯이, \u201c기적의 기원은 자연 그 자체가 아니라 자연에 대한 우리의 지식수준에서, 우리의 무지에 있다.\u201d"}, {"s": "기적은 그것이 일어나는 데 인간이 이해할 수 있는 능력 너머의 더 높은 힘이 개입한다고 가정한다.", "t": true, "why": ["5번 문장의 내용이다.", "The miracle assumes the intervention of a higher power(기적은 더 높은 힘의 개입을 가정한다)라고 한다."], "ev_en": "The miracle assumes the intervention of a \u201chigher power\u201d in its occurrence that is beyond human capability to grasp.", "ev_ko": "기적은 그것의 발생에 있어서 인간이 이해할 수 있는 능력 너머의 \u2018더 높은 힘\u2019의 개입을 가정한다."}, {"s": "기적을 일으키는 체계적이고 간단한 방법은 신적인 계시와 영감 없이는 존재하지 않는다.", "t": false, "why": ["지문과 반대이다.", "6번 문장은 without divine revelation and inspiration(신적인 계시와 영감 없이)도 기적을 일으키는 방법들이 있다고 한다."], "ev_en": "Yet there are methodical and simple ways to \u201ccause a miracle\u201d without divine revelation and inspiration.", "ev_ko": "하지만, 신적인 계시와 영감 없이 \u2018기적을 일으키는\u2019 체계적이고 간단한 방법들이 있다."}, {"s": "우리는 사건의 근원을 조사하고 찾는 대신 그것을 기적으로 정의한다.", "t": true, "why": ["7번 문장의 내용이다."], "ev_en": "Instead of checking it out, investigating and finding the source of the event, we define it as a miracle.", "ev_ko": "그것을 확인하는 것, 즉, 그 사건의 근원을 조사하고 찾는 것 대신에, 우리는 그것을 기적으로 정의한다."}], "flow": {"fixed": "통계적으로 불가능한 우연을 어떤 이들은 기적이라 정의하지만, Montaigne에 따르면 기적의 기원은 자연이 아니라 자연에 대한 우리의 무지에 있다.", "order": ["나중에 보면 영광스러운 기적이라 불리던 일들은 자연 법칙에 따른 것이거나 당시 널리 알려지지 않은 기술 발전으로 밝혀졌고, Goethe의 말처럼 신비한 것이 아직 기적은 아니다.", "이와 달리 기적이라는 말은 인간이 이해할 수 없는 더 높은 힘의 개입을 전제하지만, 사실 신적인 계시 없이도 기적을 일으키는 체계적이고 간단한 방법이 있다.", "그럼에도 우리는 사건의 근원을 조사하는 대신 기적이라 정의해 버리니, 결국 기적은 생각하기에 너무 게으른 사람들의 핑계인 셈이다."], "clue": ["앞의 무지 때문이라는 말을 실제로 기적이라 불렸던 일들의 정체로 뒷받침함", "'이와 달리'가 앞에서 밝혀진 기적의 정체(자연 법칙\u00b7기술)와 대비해 기적이 가정하는 높은 힘으로 화제를 돌림", "'그럼에도'로 앞의 내용을 받아 조사하지 않는 태도를 비판하며 결론 지음"], "why": ["우연을 기적이라 부르지만 기원은 무지", "기적의 정체는 자연 법칙이나 기술", "기적은 높은 힘을 가정하나 방법도 있음", "기적은 게으른 사람들의 핑계"], "cards": ["이와 달리 기적이라는 말은 인간이 이해할 수 없는 더 높은 힘의 개입을 전제하지만, 사실 신적인 계시 없이도 기적을 일으키는 체계적이고 간단한 방법이 있다.", "그럼에도 우리는 사건의 근원을 조사하는 대신 기적이라 정의해 버리니, 결국 기적은 생각하기에 너무 게으른 사람들의 핑계인 셈이다.", "나중에 보면 영광스러운 기적이라 불리던 일들은 자연 법칙에 따른 것이거나 당시 널리 알려지지 않은 기술 발전으로 밝혀졌고, Goethe의 말처럼 신비한 것이 아직 기적은 아니다."], "answer": [2, 0, 1]}, "sents": [{"n": 1, "en": "Coincidence that is statistically impossible seems to us like an irrational event, and some define it as a miracle.", "ko": "통계적으로 불가능한 우연은 우리에게 비이성적인 사건처럼 보이고, 어떤 이들은 그것을 기적으로 정의한다."}, {"n": 2, "en": "But, as Montaigne has said, \u201cthe origin of a miracle is in our ignorance, at the level of our knowledge of nature, and not in nature itself.\u201d", "ko": "그러나, Montaigne가 말했듯이, \u201c기적의 기원은 자연 그 자체가 아니라 자연에 대한 우리의 지식수준에서, 우리의 무지에 있다.\u201d"}, {"n": 3, "en": "Glorious miracles have been later on discovered to be obedience to the laws of nature or a technological development that was not widely known at the time.", "ko": "영광스러운 기적들은 자연의 법칙에 대한 순응으로서, 혹은 당시에는 널리 알려지지 않았던 기술적 발전으로서 나중에 발견되어 왔다."}, {"n": 4, "en": "As the German poet, Goethe, phrased it: \u201cThings that are mysterious are not yet miracles.\u201d", "ko": "독일 시인 Goethe가 그것을 표현했듯이, \u201c\u2018신비한\u2019 것들은 아직 \u2018기적\u2019이 \u2018아니다\u2019.\u201d"}, {"n": 5, "en": "The miracle assumes the intervention of a \u201chigher power\u201d in its occurrence that is beyond human capability to grasp.", "ko": "기적은 그것의 발생에 있어서 인간이 이해할 수 있는 능력 너머의 \u2018더 높은 힘\u2019의 개입을 가정한다."}, {"n": 6, "en": "Yet there are methodical and simple ways to \u201ccause a miracle\u201d without divine revelation and inspiration.", "ko": "하지만, 신적인 계시와 영감 없이 \u2018기적을 일으키는\u2019 체계적이고 간단한 방법들이 있다."}, {"n": 7, "en": "Instead of checking it out, investigating and finding the source of the event, we define it as a miracle.", "ko": "그것을 확인하는 것, 즉, 그 사건의 근원을 조사하고 찾는 것 대신에, 우리는 그것을 기적으로 정의한다."}, {"n": 8, "en": "The miracle, then, is the excuse of those who are too lazy to think.", "ko": "그렇다면, 기적은 생각하는 데 너무 게으른 사람들의 핑계이다."}]}, {"id": "2311-32", "short": "23년 11월 32번", "group": "23년 11월", "num": 32, "topic_ko": "사건 후 접한 정보가 목격자의 기억에 통합되는 과정", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "사건 후 정보는 기억에 영향을 주며, 기억이 약할수록 쉽게 통합됨"}, {"n": 2, "label": "전개", "from": 3, "to": 4, "summary_ko": "확인할 기억 정보가 줄면 새 정보가 거부되지 않고 원래 경험의 일부가 됨"}, {"n": 3, "label": "결말", "from": 5, "to": 8, "summary_ko": "이 과정은 흔히 무의식적이며, 출처를 잊게 되고 잘못된 정보는 어디서나 접할 수 있음"}], "gloss": [{"w": "encounter", "m": "~와 마주치다", "form": "encountered", "note": "동사 encounter의 과거분사형(앞의 information을 꾸며 줌)"}, {"w": "influence", "m": "~에 영향을 미치다"}, {"w": "subsequent", "m": "이후의, 다음의"}, {"w": "integrate", "m": "통합되다, 합쳐지다", "form": "integrated", "note": "동사 integrate의 과거분사형(4번 문장 it may be integrated, 수동의 의미)"}, {"w": "witness", "m": "목격자"}, {"w": "encode", "m": "부호화하다(기억으로 저장하다)", "form": "encoded", "note": "동사 encode의 과거분사형(수동의 의미)"}, {"w": "degrade", "m": "저하시키다, 떨어뜨리다", "form": "degraded", "note": "동사 degrade의 과거분사형(현재완료 have degraded의 일부)"}, {"w": "validity", "m": "타당성, 유효성"}, {"w": "misinformation", "m": "잘못된 정보"}, {"w": "reject", "m": "거부하다", "form": "rejected", "note": "동사 reject의 과거분사형(수동의 의미)"}, {"w": "unconscious", "m": "무의식적인"}, {"w": "explicit", "m": "명시적인, 분명한"}, {"w": "source", "m": "출처"}, {"w": "investigator", "m": "수사관", "form": "investigators", "note": "명사 investigator의 복수형"}], "qa": [{"chunk": 1, "q": "사건 후에 접한 외부 정보가 목격자의 기억에 쉽게 통합되는 경우는?", "opts": ["사건이 불충분하게 부호화되었거나 먼 과거의 일인 경우", "목격자가 사건 직후 내용을 꼼꼼히 기록해 둔 경우", "사건을 여러 번 반복해서 떠올린 경우"], "ans": 0, "why": ["2번 문장이 근거이다.", "사건이 poorly encoded(불충분하게 부호화됨)였거나 먼 과거의 일이면, 시간과 망각이 원래 기억을 약하게 만든다.", "직후에 기록해 두거나 반복해 떠올린다는 내용은 지문에 없다."], "ev_en": "External information can easily integrate into a witness\u2019s memory, especially if the event was poorly encoded or the memory is from a distant event, in which case time and forgetting have degraded the original memory.", "ev_ko": "특히 사건이 불충분하게 부호화되었거나, 그 기억이 시간과 망각이 원래의 기억을 저하시켜 온 먼 사건으로부터 온 것이라면, 외부 정보는 목격자의 기억에 쉽게 통합될 수 있다."}, {"chunk": 2, "q": "사건 후의 잘못된 정보가 덜 거부되는 이유로 알맞은 것은?", "opts": ["목격자가 새 정보를 일부러 믿으려고 하기 때문", "그 정보가 항상 법정에서만 주어지기 때문", "기억 속에 그 정보의 유효성을 확인할 정보가 줄어들었기 때문"], "ans": 2, "why": ["3번 문장이 근거이다.", "확인에 쓸 수 있는 기억 정보가 줄면 새 정보가 거부될 가능성이 낮아진다.", "목격자가 일부러 믿는다는 내용은 없고, 5번 문장에서는 오히려 흔히 무의식적이라고 한다.", "법정은 8번 문장에서 잘못된 정보를 접하는 여러 곳 중 하나로 나올 뿐이다."], "ev_en": "With reduced information available in memory with which to confirm the validity of post\u2011event misinformation, it is less likely that this new information will be rejected.", "ev_ko": "사건 후의 잘못된 정보의 유효성을 확인하기 위해 기억에서 사용할 수 있는 줄어든 정보를 가지면, 이 새로운 정보가 덜 거부될 듯하다."}, {"chunk": 3, "q": "정보가 기억에 통합되는 과정의 특징으로 알맞은 것은?", "opts": ["대개 목격자가 알고 있는 가운데 진행되며 출처도 정확히 남는다.", "흔히 무의식적이며, 시간이 지나면 출처조차 모를 수 있다.", "법정에서만 일어나며 다른 곳에서는 일어나지 않는다."], "ans": 1, "why": ["5번 문장은 이 과정이 explicit(명시적인)일 수 있지만 often unconscious(흔히 무의식적인)라고 한다.", "7번 문장에서 시간이 지나면 새 기억의 출처조차 모를 수 있다고 한다.", "8번 문장에서 출처는 토론, 소셜 미디어, 면담, 법정 등 어디서나 접할 수 있다고 하므로 법정에만 한정되지 않는다."], "ev_en": "This process can be explicit (i.e., the witness knows it is happening), but it is often unconscious.", "ev_ko": "이 과정은 명시적일 수 있지만(즉, 목격자는 그것이 일어나고 있다는 것을 알고 있다), 그것은 흔히 무의식적이다."}], "tf": [{"s": "사건 후 접한 정보는 이후의 기억에 영향을 줄 수 있다.", "t": true, "why": ["1번 문장 그대로의 내용이다.", "information encountered after an event(사건 후에 마주친 정보)가 subsequent remembering(이후의 기억하기)에 영향을 줄 수 있다는 뜻이다.", "글 전체의 중심 내용이기도 하다."], "ev_en": "Information encountered after an event can influence subsequent remembering.", "ev_ko": "사건 후에 마주친 정보는 이후의 기억하는 것에 영향을 미칠 수 있다."}, {"s": "잘못된 정보의 출처는 오직 법정에서만 마주칠 수 있다.", "t": false, "why": ["범위가 좁혀진 진술이다.", "8번 문장은 잘못된 정보의 출처를 다른 목격자들과의 토론, 소셜 미디어 조사, 수사관과의 면담, 심지어 법정에서까지(even in court) 어디에서나 마주칠 수 있다고 한다.", "즉 법정은 여러 곳 중 하나일 뿐이다."], "ev_en": "Sources of misinformation in forensic contexts can be encountered anywhere, from discussions with other witnesses to social media searches to multiple interviews with investigators or other legal professionals, and even in court.", "ev_ko": "법정의 상황에서의 잘못된 정보의 출처는 다른 목격자들과의 토론에서부터 소셜 미디어 조사들, 수사관 또는 기타 법률 전문가들과의 다중 인터뷰들, 심지어 법정에서까지 어디에서나 마주쳐질 수 있다."}, {"s": "외부 정보가 목격자의 현재 생각과 맞으면 원래 경험의 일부로 통합될 수 있다.", "t": true, "why": ["4번 문장의 내용이다.", "현재 생각과 맞고 이해되는 이야기를 만드는 데 쓰일 수 있을 때 통합된다."], "ev_en": "Instead, especially when it fits the witness\u2019s current thinking and can be used to create a story that makes sense to him or her, it may be integrated as part of the original experience.", "ev_ko": "대신에, 특히 그것이 목격자의 현재 생각과 맞고 그 또는 그녀에게 이해되는 하나의 이야기를 만드는 데 사용될 수 있을 때, 그것은 원래 경험의 일부로서 통합될 수 있다."}, {"s": "목격자는 사건을 다르게 생각하게 될 때 대개 그 변화를 분명히 의식하고 있다.", "t": false, "why": ["지문과 반대이다.", "6번 문장은 목격자가 의식하지 못한 채(without awareness) 그 사건에 대해 다르게 생각하게 될 수 있다고 한다."], "ev_en": "That is, the witness might find himself or herself thinking about the event differently without awareness.", "ev_ko": "즉, 목격자는 의식하지 못한 채 그 사건에 대해 다르게 생각하는 그 자신 또는 그녀 자신을 발견할지도 모른다."}, {"s": "시간이 지나면 목격자는 새 기억을 만든 정보의 출처조차 모를 수 있다.", "t": true, "why": ["7번 문장의 내용이다.", "may not even know the source(출처조차 모를지도 모른다)는 시간이 지나면 새 기억이 어디서 왔는지 잊을 수 있다는 뜻이다."], "ev_en": "Over time, the witness may not even know the source of information that led to the (new) memory.", "ev_ko": "시간이 지남에 따라, 목격자는 (새로운) 기억으로 이끄는 정보의 출처조차 모를지도 모른다."}], "flow": {"fixed": "사건이 끝난 뒤에 접하게 된 정보는 이후 그 사건을 기억해 내는 데 영향을 줄 수 있다.", "order": ["특히 원래 기억이 불충분했거나 오래전 일이라면 사건 후 외부 정보가 쉽게 섞여 들어가고, 새 정보가 틀렸는지 확인할 기억 속 재료도 줄어 잘 걸러지지 않는다.", "게다가 이런 섞임은 대개 본인이 알아채지 못하는 사이에 일어나서, 목격자는 자기도 모르게 그 사건을 다르게 생각하게 되기도 한다.", "그렇게 알아채지 못한 채 시간이 지나면 목격자는 새 기억의 출처조차 모르게 되고, 이런 잘못된 정보는 토론, 소셜 미디어, 면담, 법정 등 어디서든 접할 수 있다."], "clue": ["'특히'와 '사건 후 외부 정보'가 첫 덩어리의 사건 후 정보를 이어받아, 기억이 약할 때 더 쉽게 섞임을 설명함", "'이런 섞임'이 앞에서 말한 통합 과정을 가리키고 '게다가'로 무의식이라는 특징을 덧붙임", "'그렇게 알아채지 못한 채'가 앞 덩어리의 무의식적 과정을 그대로 받아, 시간이 지난 뒤의 결과와 마무리를 말함"], "why": ["사건 후 정보가 기억에 영향을 줌", "기억이 약하면 쉽게 섞여 들어가 걸러지지 않음", "이 과정은 무의식적임", "결국 출처를 잊고 잘못된 정보는 어디서나 접함"], "cards": ["게다가 이런 섞임은 대개 본인이 알아채지 못하는 사이에 일어나서, 목격자는 자기도 모르게 그 사건을 다르게 생각하게 되기도 한다.", "그렇게 알아채지 못한 채 시간이 지나면 목격자는 새 기억의 출처조차 모르게 되고, 이런 잘못된 정보는 토론, 소셜 미디어, 면담, 법정 등 어디서든 접할 수 있다.", "특히 원래 기억이 불충분했거나 오래전 일이라면 사건 후 외부 정보가 쉽게 섞여 들어가고, 새 정보가 틀렸는지 확인할 기억 속 재료도 줄어 잘 걸러지지 않는다."], "answer": [2, 0, 1]}, "sents": [{"n": 1, "en": "Information encountered after an event can influence subsequent remembering.", "ko": "사건 후에 마주친 정보는 이후의 기억하는 것에 영향을 미칠 수 있다."}, {"n": 2, "en": "External information can easily integrate into a witness\u2019s memory, especially if the event was poorly encoded or the memory is from a distant event, in which case time and forgetting have degraded the original memory.", "ko": "특히 사건이 불충분하게 부호화되었거나, 그 기억이 시간과 망각이 원래의 기억을 저하시켜 온 먼 사건으로부터 온 것이라면, 외부 정보는 목격자의 기억에 쉽게 통합될 수 있다."}, {"n": 3, "en": "With reduced information available in memory with which to confirm the validity of post\u2011event misinformation, it is less likely that this new information will be rejected.", "ko": "사건 후의 잘못된 정보의 유효성을 확인하기 위해 기억에서 사용할 수 있는 줄어든 정보를 가지면, 이 새로운 정보가 덜 거부될 듯하다."}, {"n": 4, "en": "Instead, especially when it fits the witness\u2019s current thinking and can be used to create a story that makes sense to him or her, it may be integrated as part of the original experience.", "ko": "대신에, 특히 그것이 목격자의 현재 생각과 맞고 그 또는 그녀에게 이해되는 하나의 이야기를 만드는 데 사용될 수 있을 때, 그것은 원래 경험의 일부로서 통합될 수 있다."}, {"n": 5, "en": "This process can be explicit (i.e., the witness knows it is happening), but it is often unconscious.", "ko": "이 과정은 명시적일 수 있지만(즉, 목격자는 그것이 일어나고 있다는 것을 알고 있다), 그것은 흔히 무의식적이다."}, {"n": 6, "en": "That is, the witness might find himself or herself thinking about the event differently without awareness.", "ko": "즉, 목격자는 의식하지 못한 채 그 사건에 대해 다르게 생각하는 그 자신 또는 그녀 자신을 발견할지도 모른다."}, {"n": 7, "en": "Over time, the witness may not even know the source of information that led to the (new) memory.", "ko": "시간이 지남에 따라, 목격자는 (새로운) 기억으로 이끄는 정보의 출처조차 모를지도 모른다."}, {"n": 8, "en": "Sources of misinformation in forensic contexts can be encountered anywhere, from discussions with other witnesses to social media searches to multiple interviews with investigators or other legal professionals, and even in court.", "ko": "법정의 상황에서의 잘못된 정보의 출처는 다른 목격자들과의 토론에서부터 소셜 미디어 조사들, 수사관 또는 기타 법률 전문가들과의 다중 인터뷰들, 심지어 법정에서까지 어디에서나 마주쳐질 수 있다."}]}, {"id": "2311-33", "short": "23년 11월 33번", "group": "23년 11월", "num": 33, "topic_ko": "상관관계의 힘과 인과 설명 시도의 한계", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "상관관계는 통찰이 명확해 강력하지만, 인과를 끌어들이면 가려짐"}, {"n": 2, "label": "전개", "from": 3, "to": 7, "summary_ko": "주황색 차 사례에서 우리는 이유를 추측하다 경쟁적 인과 가설에 빠짐"}, {"n": 3, "label": "결말", "from": 8, "to": 11, "summary_ko": "설명 시도는 상황을 흐리고 인과는 보이기 어려우므로 이유 설명을 삼가는 것이 좋음"}], "gloss": [{"w": "correlation", "m": "상관관계", "form": "Correlations", "note": "명사 correlation의 복수형"}, {"w": "insight", "m": "통찰력", "form": "insights", "note": "명사 insight의 복수형"}, {"w": "causality", "m": "인과 관계"}, {"w": "statistician", "m": "통계학자", "form": "statisticians", "note": "명사 statistician의 복수형"}, {"w": "defect", "m": "결함", "form": "defects", "note": "명사 defect의 복수형"}, {"w": "enthusiast", "m": "애호가", "form": "enthusiasts", "note": "명사 enthusiast의 복수형"}, {"w": "noticeable", "m": "눈에 띄는"}, {"w": "hypothesis", "m": "가설", "form": "hypotheses", "note": "명사 hypothesis의 복수형(-is가 -es로 바뀜)"}, {"w": "illuminate", "m": "설명하다, 밝히다"}, {"w": "cloudy", "m": "흐린", "form": "cloudier", "note": "형용사 cloudy의 비교급"}, {"w": "mathematically", "m": "수학적으로"}, {"w": "causal", "m": "인과의"}, {"w": "hold off from", "m": "~을 삼가다, 미루다"}, {"w": "resell", "m": "재판매하다", "form": "resold", "note": "동사 resell의 과거분사형(수동의 의미)"}], "qa": [{"chunk": 1, "q": "지문에서 상관관계가 강력하다고 한 이유는?", "opts": ["제공하는 통찰이 비교적 명확하기 때문", "원인과 결과를 정확히 밝혀 주기 때문", "수학 없이도 누구나 계산할 수 있기 때문"], "ans": 0, "why": ["1번 문장이 근거이다.", "the insights they offer are relatively clear, 즉 상관관계가 주는 통찰이 비교적 명확하기 때문이다.", "원인과 결과를 밝혀 준다는 내용은 없고, 오히려 인과를 끌어들이면 통찰이 가려진다고 한다.", "수학 없이도 누구나 계산할 수 있다는 내용도 없다. 9번 문장은 상관관계를 수학적으로 보여 줄 수 있다고만 한다."], "ev_en": "Correlations are powerful because the insights they offer are relatively clear.", "ev_ko": "상관관계는 그것들이 제공하는 통찰력이 비교적 명확하기 때문에 강력하다."}, {"chunk": 2, "q": "주황색 차 사례에서 이 결과를 읽은 우리가 곧바로 하게 되는 일은?", "opts": ["통계학자에게 더 많은 데이터를 요청한다.", "이유를 추측하다가 서로 경쟁하는 인과 가설에 빠진다.", "상관관계 분석 결과를 믿지 않고 무시한다."], "ans": 1, "why": ["7번 문장이 근거이다.", "5~6번 문장에서 차 주인이 관리를 잘해서인지, 눈에 띄어 사고가 적어서인지 이유를 따지게 된다.", "데이터를 더 요청하거나 결과를 무시한다는 내용은 없다."], "ev_en": "Quickly we are caught in a web of competing causal hypotheses.", "ev_ko": "곧 우리는 경쟁적인 인과 가설의 함정에 빠진다."}, {"chunk": 3, "q": "글쓴이의 결론으로 알맞은 것은?", "opts": ["인과 관계를 먼저 밝힌 뒤에 상관관계를 활용해야 한다.", "상관관계의 배후 이유를 설명하려 하지 않는 것이 좋다.", "상관관계는 수학적으로 보일 수 없으므로 믿기 어렵다."], "ans": 1, "why": ["11번 문장이 근거이다.", "hold off from trying to explain the reason은 이유를 설명하려는 것을 삼가라는 뜻이다.", "9번 문장에서 상관관계는 수학적으로 보여 줄 수 있다고 하므로 \u2018상관관계는 수학적으로 보일 수 없다\u2019는 진술은 틀리다.", "\u2018인과 관계를 먼저 밝힌 뒤 활용해야 한다\u2019는 내용도 지문에 없고, 오히려 인과를 끌어들이면 통찰이 가려진다(2번 문장)고 한다."], "ev_en": "So we would do well to hold off from trying to explain the reason behind the correlations.", "ev_ko": "따라서 우리는 상관관계의 배후에 있는 이유를 설명하려 하지 않는 것이 좋다."}], "tf": [{"s": "한 중고차 딜러가 경매 차량 중 문제가 생길 만한 차를 예측하려고 통계학자에게 데이터를 제공했다.", "t": true, "why": ["3번 문장의 내용이다."], "ev_en": "For instance, a used\u2011car dealer supplied data to statisticians to predict which of the vehicles available for purchase at an auction were likely to have problems.", "ev_ko": "예를 들어, 한 중고차 딜러가 경매에서 구입할 수 있는 차량들 중 어떤 차량에 문제가 발생할 가능성이 있는지를 예측하기 위한 데이터를 통계학자들에게 제공했다."}, {"s": "상관관계 분석에서 주황색 차는 결함이 있을 가능성이 훨씬 높게 나타났다.", "t": false, "why": ["결과가 반대로 바뀐 진술이다.", "분석은 주황색 차가 결함이 있을 가능성이 훨씬 적다는 것을 보여 줬다."], "ev_en": "A correlation analysis showed that orange\u2011colored cars were far less likely to have defects.", "ev_ko": "한 상관관계 분석은 주황색 차들이 결함이 있을 가능성이 훨씬 적다는 것을 보여 줬다."}, {"s": "주황색 차가 도로에서 더 눈에 띄어 사고가 적다는 것은 지문이 제시한 가능한 설명 중 하나이다.", "t": true, "why": ["6번 문장에서 가능한 이유로 제시된 내용이다.", "이 설명으로 재판매 때 상태가 더 좋다는 결과를 풀이해 볼 수 있다."], "ev_en": "Or, is it because orange\u2011colored cars are more noticeable on the road and therefore less likely to be in accidents, so they\u2019re in better condition when resold?", "ev_ko": "아니면, 주황색 차들이 도로에서 더 눈에 띄고, 그래서 사고가 날 가능성이 적어 재판매될 때 그것들이 상태가 더 좋은 것이기 때문인가?"}, {"s": "글쓴이는 인과 관계도 상관관계만큼 쉽게 수학적으로 보여 줄 수 있다고 말한다.", "t": false, "why": ["지문과 반대이다.", "9번 문장은 Correlations exist; we can show them mathematically(상관관계는 존재하며, 우리는 그것을 수학적으로 보여 줄 수 있다)고 한다.", "반면 10번 문장은 인과 관계에 대해서는 쉽게 똑같이 할 수 없다고 한다."], "ev_en": "We can\u2019t easily do the same for causal links.", "ev_ko": "우리는 인과 관계에 대해서는 쉽게 똑같이 할 수 없다."}, {"s": "인과 관계로 설명하려는 시도는 오히려 상황을 더 흐리게 만들 뿐이다.", "t": true, "why": ["8번 문장의 내용이다.", "this way는 앞에서 말한 인과적 이유를 설명하려는 방식을 가리킨다.", "그런 시도는 상황을 cloudier(더 흐린, 형용사 cloudy의 비교급)하게, 즉 더 흐리게 만들 뿐이라고 한다."], "ev_en": "But our attempts to illuminate things this way only make them cloudier.", "ev_ko": "하지만 이런 식으로 무언가를 설명하려는 우리의 시도는 그것들을 더 흐리게 만들 뿐이다."}], "flow": {"fixed": "상관관계는 그것이 주는 통찰이 비교적 분명해서 강력하지만, 인과 관계를 끌어들이면 그 통찰이 종종 가려진다.", "order": ["예를 들어 한 중고차 딜러의 데이터를 분석했더니, 주황색 차가 결함이 있을 가능성이 훨씬 적다는 상관관계가 나타났다.", "그런데 이 결과를 보면 우리는 곧바로 이유를 궁리하게 되어, 차주가 차를 잘 관리해서인지 눈에 띄어 사고가 적어서인지 하는 경쟁하는 가설에 빠져든다.", "하지만 그렇게 설명하려 할수록 오히려 더 흐려지고, 상관관계와 달리 인과는 쉽게 보여 줄 수 없으므로 이유를 설명하려 하지 않는 편이 낫다."], "clue": ["'예를 들어'로 첫 덩어리의 주장을 구체적인 사례로 보여 줌", "'이 결과'가 앞 사례의 분석 결과를 가리키고 '그런데'로 우리의 반응이 이어짐", "'그렇게 설명하려 할수록'이 앞의 가설 세우기를 받아 결론으로 마무리함"], "why": ["상관관계는 명확하지만 인과를 끌어들이면 가려짐", "주황색 차 사례", "결과를 보면 곧 경쟁하는 가설에 빠짐", "설명하려 하지 말고 이유 설명을 삼가는 것이 좋음"], "cards": ["하지만 그렇게 설명하려 할수록 오히려 더 흐려지고, 상관관계와 달리 인과는 쉽게 보여 줄 수 없으므로 이유를 설명하려 하지 않는 편이 낫다.", "그런데 이 결과를 보면 우리는 곧바로 이유를 궁리하게 되어, 차주가 차를 잘 관리해서인지 눈에 띄어 사고가 적어서인지 하는 경쟁하는 가설에 빠져든다.", "예를 들어 한 중고차 딜러의 데이터를 분석했더니, 주황색 차가 결함이 있을 가능성이 훨씬 적다는 상관관계가 나타났다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Correlations are powerful because the insights they offer are relatively clear.", "ko": "상관관계는 그것들이 제공하는 통찰력이 비교적 명확하기 때문에 강력하다."}, {"n": 2, "en": "These insights are often covered up when we bring causality back into the picture.", "ko": "이러한 통찰력은 종종 우리가 인과 관계를 그 상황으로 다시 가져올 때 가려진다."}, {"n": 3, "en": "For instance, a used\u2011car dealer supplied data to statisticians to predict which of the vehicles available for purchase at an auction were likely to have problems.", "ko": "예를 들어, 한 중고차 딜러가 경매에서 구입할 수 있는 차량들 중 어떤 차량에 문제가 발생할 가능성이 있는지를 예측하기 위한 데이터를 통계학자들에게 제공했다."}, {"n": 4, "en": "A correlation analysis showed that orange\u2011colored cars were far less likely to have defects.", "ko": "한 상관관계 분석은 주황색 차들이 결함이 있을 가능성이 훨씬 적다는 것을 보여 줬다."}, {"n": 5, "en": "Even as we read this, we already think about why it might be so: Are orange\u2011colored car owners likely to be car enthusiasts and take better care of their vehicles?", "ko": "심지어 우리가 이것을 읽으면서도, 우리는 이미 왜 그럴지에 대해 생각한다. 주황색 차를 소유한 사람들이 자동차 애호가여서 그들의 차량을 더 잘 관리할 가능성이 있는가?"}, {"n": 6, "en": "Or, is it because orange\u2011colored cars are more noticeable on the road and therefore less likely to be in accidents, so they\u2019re in better condition when resold?", "ko": "아니면, 주황색 차들이 도로에서 더 눈에 띄고, 그래서 사고가 날 가능성이 적어 재판매될 때 그것들이 상태가 더 좋은 것이기 때문인가?"}, {"n": 7, "en": "Quickly we are caught in a web of competing causal hypotheses.", "ko": "곧 우리는 경쟁적인 인과 가설의 함정에 빠진다."}, {"n": 8, "en": "But our attempts to illuminate things this way only make them cloudier.", "ko": "하지만 이런 식으로 무언가를 설명하려는 우리의 시도는 그것들을 더 흐리게 만들 뿐이다."}, {"n": 9, "en": "Correlations exist; we can show them mathematically.", "ko": "상관관계는 존재하며 우리는 그것들을 수학적으로 보여 줄 수 있다."}, {"n": 10, "en": "We can\u2019t easily do the same for causal links.", "ko": "우리는 인과 관계에 대해서는 쉽게 똑같이 할 수 없다."}, {"n": 11, "en": "So we would do well to hold off from trying to explain the reason behind the correlations.", "ko": "따라서 우리는 상관관계의 배후에 있는 이유를 설명하려 하지 않는 것이 좋다."}]}, {"id": "2311-34", "short": "23년 11월 34번", "group": "23년 11월", "num": 34, "topic_ko": "동물 종의 수명이 야생 생존 시간에 의해 결정되는 원리", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "야생 쥐는 외부 원인으로 일찍 죽어 평균 2년 넘게 살지 못함"}, {"n": 2, "label": "중심", "from": 4, "to": 5, "summary_ko": "종의 평균 수명은 야생에서 생존할 수 있는 평균 시간에 의해 결정됨"}, {"n": 3, "label": "마무리", "from": 6, "to": 8, "summary_ko": "박쥐는 날 수 있어 위험을 피하고 먹이를 잘 찾아 오래 사는 변화가 유용했음"}], "gloss": [{"w": "life span", "m": "수명"}, {"w": "starvation", "m": "굶주림"}, {"w": "predator", "m": "포식자", "form": "predators", "note": "명사 predator의 복수형"}, {"w": "external", "m": "외부의"}, {"w": "internal", "m": "내부의"}, {"w": "aging", "m": "노화"}, {"w": "species", "m": "(생물) 종"}, {"w": "determine", "m": "결정하다", "form": "determined", "note": "동사 determine의 과거분사형(is determined, 수동태)"}, {"w": "escape", "m": "도망치다, 벗어나다"}, {"w": "distance", "m": "거리", "form": "distances", "note": "명사 distance의 복수형"}, {"w": "genetic", "m": "유전적인"}, {"w": "flee", "m": "달아나다"}, {"w": "mouse", "m": "쥐", "form": "mice", "note": "명사 mouse의 불규칙 복수형"}, {"w": "bat", "m": "박쥐", "form": "bats", "note": "명사 bat의 복수형"}], "qa": [{"chunk": 1, "q": "지문에 따르면 야생 쥐가 죽는 주된 원인은?", "opts": ["노화와 같은 내부적인 원인", "유전적 변화로 인한 원인", "질병, 굶주림, 포식자와 같은 외부적인 원인"], "ans": 2, "why": ["2번 문장이 근거이다.", "쥐는 disease(질병), starvation(굶주림), predators(포식자) 같은 외부 원인으로 죽는다.", "노화 같은 내부 원인 때문이 아니라고 분명히 말한다.", "유전적 변화는 박쥐 이야기에서 나오는 내용이다."], "ev_en": "They die from external causes, such as disease, starvation, or predators, not due to internal causes, such as aging.", "ev_ko": "그들은 노화와 같은 \u2018내부적인 원인들\u2019 때문이 아니라 질병, 굶주림 또는 포식자와 같은 \u2018외부적인 원인들\u2019로 죽는다."}, {"chunk": 2, "q": "동물 종의 평균 수명을 결정하는 것은?", "opts": ["그 종의 몸집 크기", "그 종이 야생에서 생존할 수 있는 평균 시간", "그 종이 먹는 먹이의 양"], "ans": 1, "why": ["4번 문장이 근거이다.", "평균 수명이나 노화 속도는 야생에서 생존할 수 있는 평균 시간에 의해 정해진다.", "몸집이나 먹이의 양은 지문에 나오지 않는다."], "ev_en": "Now we have arrived at an important point: The average life span of an animal species, or the rate at which it ages, is determined by the average time that this animal species can survive in the wild.", "ev_ko": "이제 우리는 중요한 지점에 도달했다. 동물 종의 평균 수명, 또는 그것이 노화하는 속도는 이 동물 종이 야생에서 생존할 수 있는 평균 시간에 의해 결정된다."}, {"chunk": 3, "q": "박쥐가 쥐보다 오래 살 수 있는 이유로 알맞은 것은?", "opts": ["날 수 있어서 위험에서 훨씬 더 빨리 도망칠 수 있기 때문", "쥐보다 새끼를 더 많이 낳기 때문", "노화가 전혀 일어나지 않는 몸을 가졌기 때문"], "ans": 0, "why": ["6번 문장이 근거이다.", "박쥐는 쥐와 달리 날 수 있어서 위험에서 훨씬 더 빨리 도망칠 수 있다(escape from danger much faster).", "7번 문장은 날개 덕분에 더 긴 거리를 이동하고 먹이도 더 잘 찾는다고 덧붙인다.", "새끼를 더 많이 낳는다는 내용도, 노화가 전혀 일어나지 않는다는 내용도 지문에 없다."], "ev_en": "In contrast to mice, bats can fly, which is why they can escape from danger much faster.", "ev_ko": "쥐와 대조적으로 박쥐는 날 수 있고, 이것은 그들이 위험에서 훨씬 더 빨리 도망칠 수 있는 이유이다."}], "tf": [{"s": "야생의 쥐는 대부분 2년의 수명이 끝나기 전에 잡아먹히거나 죽는다.", "t": true, "why": ["1번 문장의 내용이다.", "쥐의 수명 2년이 끝나기 전에 대부분 잡아먹히거나 죽는다는 뜻이다."], "ev_en": "Most mice in the wild are eaten or die before their life span of two years is over.", "ev_ko": "야생에 있는 대부분의 쥐들은 2년의 수명이 끝나기 전에 잡아먹히거나 죽는다."}, {"s": "박쥐도 쥐와 비슷하게 2년 안팎까지만 살 수 있다.", "t": false, "why": ["수치가 바뀐 진술이다.", "5번 문장은 박쥐가 30세까지 살 수 있다고 한다."], "ev_en": "That explains why a bat can live to be 30 years old.", "ev_ko": "그것은 왜 박쥐가 30세까지 살 수 있는지를 설명해 준다."}, {"s": "박쥐는 날개 덕분에 더 긴 거리를 이동하고 먹이를 더 잘 찾을 수 있다.", "t": true, "why": ["7번 문장의 내용이다.", "thanks to their wings(날개 덕분에)가 이유이고, longer distances(더 긴 거리)와 find food(먹이를 찾다)가 결과이다."], "ev_en": "Thanks to their wings, bats can also cover longer distances and are better able to find food.", "ev_ko": "그들의 날개 덕분에, 박쥐들은 또한 더 긴 거리를 이동할 수 있고 먹이를 더 잘 찾을 수 있다."}, {"s": "자연은 쥐가 평균적으로 2년 넘게 살도록 만들었다.", "t": false, "why": ["방향이 반대로 바뀐 진술이다.", "3번 문장은 자연이 쥐를 평균적으로 2년 이상 살지 못하게 만들었다고 한다(no longer than two years)."], "ev_en": "That is why nature has made mice to live, on average, for no longer than two years.", "ev_ko": "그것이 자연이 쥐를 평균적으로 2년 이상 살지 못하게 만든 이유이다."}, {"s": "박쥐가 더 오래 사는 것을 가능하게 한 과거의 유전적 변화는 유용했다.", "t": true, "why": ["8번 문장의 내용이다.", "박쥐는 위험에서 도망치고 먹이를 찾고 생존하는 일을 쥐보다 훨씬 잘하기 때문이다.", "그래서 박쥐를 더 오래 살게 한 유전적 변화는 모두 쓸모가 있었다는 뜻이다."], "ev_en": "Every genetic change in the past that made it possible for a bat to live longer was useful, because bats are much better able than mice to flee from danger, find food, and survive.", "ev_ko": "박쥐가 더 오래 사는 것을 가능하게 해 준 과거의 모든 유전적 변화는 박쥐가 쥐보다 위험으로부터 도망치고, 먹이를 찾고, 생존하는 것을 훨씬 더 잘할 수 있기 때문에 유용했다."}], "flow": {"fixed": "야생의 쥐는 대부분 질병, 굶주림, 포식자 같은 외부 원인으로 일찍 죽기 때문에, 자연은 쥐를 평균 2년 넘게 살지 못하게 만들었다.", "order": ["여기서 중요한 점은 한 동물 종의 평균 수명이나 노화 속도가 그 종이 야생에서 생존할 수 있는 평균 시간에 따라 정해진다는 것이다.", "이것이 박쥐가 30세까지 살 수 있는 이유를 설명해 주는데, 쥐와 달리 박쥐는 날 수 있어서 위험에서 훨씬 빨리 벗어난다.", "게다가 날개 덕분에 더 멀리 이동하며 먹이도 더 잘 찾으므로, 박쥐를 더 오래 살게 한 유전적 변화는 모두 쓸모가 있었다."], "clue": ["'여기서 중요한 점'으로 쥐 사례에서 일반 원리를 끌어냄", "'이것'이 앞의 원리를 가리키며 박쥐 사례에 적용함", "'게다가'로 박쥐의 장점을 더하고 유전적 변화의 유용함으로 결론을 맺음"], "why": ["쥐는 외부 원인으로 일찍 죽어 수명이 짧음", "종의 수명은 야생 생존 시간이 결정", "그래서 날 수 있는 박쥐는 위험을 잘 피함", "먹이도 잘 찾아 오래 사는 변화가 유용했음"], "cards": ["게다가 날개 덕분에 더 멀리 이동하며 먹이도 더 잘 찾으므로, 박쥐를 더 오래 살게 한 유전적 변화는 모두 쓸모가 있었다.", "이것이 박쥐가 30세까지 살 수 있는 이유를 설명해 주는데, 쥐와 달리 박쥐는 날 수 있어서 위험에서 훨씬 빨리 벗어난다.", "여기서 중요한 점은 한 동물 종의 평균 수명이나 노화 속도가 그 종이 야생에서 생존할 수 있는 평균 시간에 따라 정해진다는 것이다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Most mice in the wild are eaten or die before their life span of two years is over.", "ko": "야생에 있는 대부분의 쥐들은 2년의 수명이 끝나기 전에 잡아먹히거나 죽는다."}, {"n": 2, "en": "They die from external causes, such as disease, starvation, or predators, not due to internal causes, such as aging.", "ko": "그들은 노화와 같은 \u2018내부적인 원인들\u2019 때문이 아니라 질병, 굶주림 또는 포식자와 같은 \u2018외부적인 원인들\u2019로 죽는다."}, {"n": 3, "en": "That is why nature has made mice to live, on average, for no longer than two years.", "ko": "그것이 자연이 쥐를 평균적으로 2년 이상 살지 못하게 만든 이유이다."}, {"n": 4, "en": "Now we have arrived at an important point: The average life span of an animal species, or the rate at which it ages, is determined by the average time that this animal species can survive in the wild.", "ko": "이제 우리는 중요한 지점에 도달했다. 동물 종의 평균 수명, 또는 그것이 노화하는 속도는 이 동물 종이 야생에서 생존할 수 있는 평균 시간에 의해 결정된다."}, {"n": 5, "en": "That explains why a bat can live to be 30 years old.", "ko": "그것은 왜 박쥐가 30세까지 살 수 있는지를 설명해 준다."}, {"n": 6, "en": "In contrast to mice, bats can fly, which is why they can escape from danger much faster.", "ko": "쥐와 대조적으로 박쥐는 날 수 있고, 이것은 그들이 위험에서 훨씬 더 빨리 도망칠 수 있는 이유이다."}, {"n": 7, "en": "Thanks to their wings, bats can also cover longer distances and are better able to find food.", "ko": "그들의 날개 덕분에, 박쥐들은 또한 더 긴 거리를 이동할 수 있고 먹이를 더 잘 찾을 수 있다."}, {"n": 8, "en": "Every genetic change in the past that made it possible for a bat to live longer was useful, because bats are much better able than mice to flee from danger, find food, and survive.", "ko": "박쥐가 더 오래 사는 것을 가능하게 해 준 과거의 모든 유전적 변화는 박쥐가 쥐보다 위험으로부터 도망치고, 먹이를 찾고, 생존하는 것을 훨씬 더 잘할 수 있기 때문에 유용했다."}]}, {"id": "2311-35", "short": "23년 11월 35번", "group": "23년 11월", "num": 35, "topic_ko": "도덕적 우수성을 가르치는 일에 대한 새로운 이해와 낙관", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "도덕적 우수성은 습관과 반복의 결과여서 이른 시기에 정해지므로 언제 가르칠지가 중요함"}, {"n": 2, "label": "Freud의 주장", "from": 3, "to": 4, "summary_ko": "Freud는 5세 무렵 이후 성격이 거의 안 바뀐다고 했지만 틀렸음(4번 문장은 흐름과 무관한 문장)"}, {"n": 3, "label": "최근 연구와 결론", "from": 5, "to": 6, "summary_ko": "뇌 발달이 20대 중반까지 이어져 성격 특성이 30세 무렵 안정되므로 가르치는 데 더 낙관적일 수 있음"}], "gloss": [{"w": "moral excellence", "m": "도덕적 우수성"}, {"w": "habit", "m": "습관"}, {"w": "repetition", "m": "반복"}, {"w": "innate", "m": "선천적인, 타고난"}, {"w": "genetic", "m": "유전의, 유전적인"}, {"w": "component", "m": "구성 요소"}, {"w": "broadly", "m": "대체로, 광범위하게"}, {"w": "personality", "m": "성격, 인격"}, {"w": "trait", "m": "특성", "form": "traits", "note": "명사 trait의 복수형"}, {"w": "stabilize", "m": "안정되다"}, {"w": "regardless of", "m": "~에 상관없이"}, {"w": "ethnicity", "m": "민족성, 인종적 배경"}, {"w": "cognitive", "m": "인지의, 인지적인"}, {"w": "optimistic", "m": "낙관적인"}], "qa": [{"chunk": 1, "q": "Aristotle에 따르면 도덕적 우수성은 무엇의 결과인가?", "opts": ["유전적 요소만", "습관과 반복", "5세 이후에는 변하지 않는 성격"], "ans": 1, "why": ["1번 문장이 근거이다.", "Aristotle에 따르면 도덕적 우수성은 습관과 반복의 결과이다.", "선천적, 유전적 요소를 말하는 쪽은 현대 과학이고, 그것도 가질 수도 있다고 덧붙이는 것일 뿐 유전적 요소만이라는 뜻은 아니다."], "ev_en": "Moral excellence, according to Aristotle, is the result of habit and repetition, though modern science would also suggest that it may have an innate, genetic component.", "ev_ko": "비록 현대 과학은 그것이 선천적, 즉, 유전적인 요소를 가질 수도 있다고 또한 주장하지만, Aristotle에 따르면 도덕적 우수성은 습관과 반복의 결과물이다."}, {"chunk": 2, "q": "Freud가 제시한 내용으로 알맞은 것은?", "opts": ["성격은 30세 무렵에 안정된다.", "5세 혹은 그 무렵 이후에는 성격을 많이 바꾸지 않는다.", "도덕적 우수성은 유전적으로만 결정된다."], "ans": 1, "why": ["3번 문장이 근거이다.", "Freud는 우리가 5세 무렵 이후에는 성격을 많이 바꾸지 않는다고 제시했지만, 글쓴이는 그가 틀렸다고 한다.", "30세 무렵 안정된다는 것은 최근 연구의 내용이다(5번 문장).", "참고로 4번 문장은 성격이 아니라 도덕적으로 우수한 사람이 좋은 일을 하는 자연스러움을 말하므로 전체 흐름과 무관한 문장이다."], "ev_en": "Freud suggested that we don\u2019t change our personality much after age five or thereabouts, but as in many other things, Freud was wrong.", "ev_ko": "Freud는 우리가 5세 혹은 그 무렵 이후에는 우리의 성격을 많이 바꾸지 않는다고 제시했지만, 다른 많은 것들에서처럼 Freud는 틀렸다."}, {"chunk": 3, "q": "최근의 심리 연구가 보여 주는 내용으로 알맞은 것은?", "opts": ["성격 특성은 민족에 따라 안정되는 나이가 크게 다르다.", "인간의 뇌는 5세 무렵 발달을 멈춘다.", "20대 중반까지 뇌가 계속 발달하면서 성격 특성은 30세 무렵 안정된다."], "ans": 2, "why": ["5번 문장이 근거이다.", "뇌는 20대 중반까지 계속 발달하고, 성격 특성은 30세 무렵에 안정된다.", "regardless of ethnicity(민족에 상관없이)이므로 민족에 따라 크게 다르다는 진술은 틀리다.", "뇌가 5세 무렵 발달을 멈춘다는 내용은 지문에 없다."], "ev_en": "Recent psychological research shows that personality traits stabilize around age thirty in both men and women and regardless of ethnicity as the human brain continues to develop, both neuroanatomically and in terms of cognitive skills, until the mid-twenties.", "ev_ko": "최근의 심리 연구는 20대 중반까지 신경 해부학적으로 그리고 인지 기능 면에서 인간의 뇌가 계속해서 발달함에 따라 남성과 여성 모두에게 있어서 그리고 민족에 상관없이 성격 특성이 30세 무렵에 안정된다는 것을 보여 준다."}], "tf": [{"s": "도덕적 우수성이 우리 삶의 이른 시기에 대체로 정해지기 때문에, 얼마나 일찍 가르칠지의 문제가 중요하다.", "t": true, "why": ["2번 문장의 내용이다.", "도덕적 우수성은 삶의 이른 시기에 광범위하게 설정되므로 얼마나 일찍 가르칠지가 중요한 질문이 된다."], "ev_en": "This means that moral excellence will be broadly set early in our lives, which is why the question of how early to teach it is so important.", "ev_ko": "이것은 도덕적 우수성이 우리 삶에 있어서 이른 시기에 광범위하게 설정될 것임을 의미하며, 이것이 얼마나 일찍 그것을 가르쳐야 할지에 대한 질문이 매우 중요한 이유이다."}, {"s": "현대 과학은 도덕적 우수성이 선천적, 유전적 요소를 가질 수도 있다고 말한다.", "t": true, "why": ["1번 문장의 내용이다.", "modern science would also suggest that it may have an innate, genetic component(현대 과학은 그것이 선천적, 유전적 요소를 가질 수도 있다고 또한 주장한다)라고 한다."], "ev_en": "Moral excellence, according to Aristotle, is the result of habit and repetition, though modern science would also suggest that it may have an innate, genetic component.", "ev_ko": "비록 현대 과학은 그것이 선천적, 즉, 유전적인 요소를 가질 수도 있다고 또한 주장하지만, Aristotle에 따르면 도덕적 우수성은 습관과 반복의 결과물이다."}, {"s": "최근 연구에 따르면 성격 특성은 20대 중반에 안정된다.", "t": false, "why": ["나이가 바뀐 진술이다.", "20대 중반은 인간의 뇌가 계속 발달하는 시기의 끝이다.", "성격 특성은 30세 무렵에 안정된다고 한다(5번 문장)."], "ev_en": "Recent psychological research shows that personality traits stabilize around age thirty in both men and women and regardless of ethnicity as the human brain continues to develop, both neuroanatomically and in terms of cognitive skills, until the mid-twenties.", "ev_ko": "최근의 심리 연구는 20대 중반까지 신경 해부학적으로 그리고 인지 기능 면에서 인간의 뇌가 계속해서 발달함에 따라 남성과 여성 모두에게 있어서 그리고 민족에 상관없이 성격 특성이 30세 무렵에 안정된다는 것을 보여 준다."}, {"s": "성격 특성이 안정되는 나이는 남성과 여성, 그리고 민족에 따라 크게 다르다.", "t": false, "why": ["지문과 반대이다.", "5번 문장은 남성과 여성 모두에게, 그리고 regardless of ethnicity(민족에 상관없이) 성격 특성이 30세 무렵에 안정된다고 한다."], "ev_en": "Recent psychological research shows that personality traits stabilize around age thirty in both men and women and regardless of ethnicity as the human brain continues to develop, both neuroanatomically and in terms of cognitive skills, until the mid-twenties.", "ev_ko": "최근의 심리 연구는 20대 중반까지 신경 해부학적으로 그리고 인지 기능 면에서 인간의 뇌가 계속해서 발달함에 따라 남성과 여성 모두에게 있어서 그리고 민족에 상관없이 성격 특성이 30세 무렵에 안정된다는 것을 보여 준다."}, {"s": "새로운 이해의 이점은 Aristotle이나 Freud보다 도덕적 우수성을 가르칠 수 있다는 점에서 조금 더 낙관적일 수 있다는 것이다.", "t": true, "why": ["6번 문장의 내용이다."], "ev_en": "The advantage of this new understanding is that we can be a bit more optimistic than Aristotle and Freud about being able to teach moral excellence.", "ev_ko": "이 새로운 이해의 이점은 우리가 Aristotle이나 Freud보다 도덕적 우수성을 가르칠 수 있다는 점에서 조금 더 낙관적일 수 있다는 것이다."}], "flow": {"fixed": "Aristotle에 따르면 도덕적 우수성은 습관과 반복의 결과이고, 그래서 삶의 이른 시기에 대체로 정해지므로 얼마나 일찍 가르칠지가 중요한 문제이다.", "order": ["그런데 Freud는 5세 무렵 이후에는 성격이 많이 바뀌지 않는다고 했지만, 그 주장은 틀렸다.", "최근 심리 연구에 따르면 뇌가 20대 중반까지 계속 발달하면서 성격 특성은 성별과 민족에 상관없이 30세 무렵에 안정된다.", "이 새로운 이해 덕분에 우리는 도덕적 우수성을 가르칠 수 있다는 점에서 Aristotle이나 Freud보다 조금 더 낙관적일 수 있다."], "clue": ["'그런데'로 앞의 이른 시기에 정해진다는 내용에서 성격이 언제 바뀌는지로 화제를 돌림", "Freud의 주장이 틀렸다는 말을 받아 최근 연구의 구체적 결과를 제시함", "'이 새로운 이해'가 앞의 최근 연구를 가리키며 결론을 말함"], "why": ["도덕적 우수성은 습관의 결과", "Freud의 주장은 틀림", "성격은 30세 무렵 안정됨", "그래서 가르치는 데 더 낙관적"], "cards": ["이 새로운 이해 덕분에 우리는 도덕적 우수성을 가르칠 수 있다는 점에서 Aristotle이나 Freud보다 조금 더 낙관적일 수 있다.", "최근 심리 연구에 따르면 뇌가 20대 중반까지 계속 발달하면서 성격 특성은 성별과 민족에 상관없이 30세 무렵에 안정된다.", "그런데 Freud는 5세 무렵 이후에는 성격이 많이 바뀌지 않는다고 했지만, 그 주장은 틀렸다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Moral excellence, according to Aristotle, is the result of habit and repetition, though modern science would also suggest that it may have an innate, genetic component.", "ko": "비록 현대 과학은 그것이 선천적, 즉, 유전적인 요소를 가질 수도 있다고 또한 주장하지만, Aristotle에 따르면 도덕적 우수성은 습관과 반복의 결과물이다."}, {"n": 2, "en": "This means that moral excellence will be broadly set early in our lives, which is why the question of how early to teach it is so important.", "ko": "이것은 도덕적 우수성이 우리 삶에 있어서 이른 시기에 광범위하게 설정될 것임을 의미하며, 이것이 얼마나 일찍 그것을 가르쳐야 할지에 대한 질문이 매우 중요한 이유이다."}, {"n": 3, "en": "Freud suggested that we don\u2019t change our personality much after age five or thereabouts, but as in many other things, Freud was wrong.", "ko": "Freud는 우리가 5세 혹은 그 무렵 이후에는 우리의 성격을 많이 바꾸지 않는다고 제시했지만, 다른 많은 것들에서처럼 Freud는 틀렸다."}, {"n": 4, "en": "A person of moral excellence cannot help doing good \u2015 it is as natural as the change of seasons or the rotation of the planets.", "ko": "도덕적으로 우수한 사람은 좋은 일을 하지 않을 수 없으며, 그것은 계절의 변화나 행성의 자전만큼이나 자연스럽다."}, {"n": 5, "en": "Recent psychological research shows that personality traits stabilize around age thirty in both men and women and regardless of ethnicity as the human brain continues to develop, both neuroanatomically and in terms of cognitive skills, until the mid-twenties.", "ko": "최근의 심리 연구는 20대 중반까지 신경 해부학적으로 그리고 인지 기능 면에서 인간의 뇌가 계속해서 발달함에 따라 남성과 여성 모두에게 있어서 그리고 민족에 상관없이 성격 특성이 30세 무렵에 안정된다는 것을 보여 준다."}, {"n": 6, "en": "The advantage of this new understanding is that we can be a bit more optimistic than Aristotle and Freud about being able to teach moral excellence.", "ko": "이 새로운 이해의 이점은 우리가 Aristotle이나 Freud보다 도덕적 우수성을 가르칠 수 있다는 점에서 조금 더 낙관적일 수 있다는 것이다."}]}, {"id": "2311-36", "short": "23년 11월 36번", "group": "23년 11월", "num": 36, "topic_ko": "동물 크기의 변화 경향과 기온 상승에 따른 소형화", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "종의 크기는 환경과 맞춰진 결과이며, 크기 변동은 환경 변화를 나타내 옴"}, {"n": 2, "label": "전개", "from": 4, "to": 5, "summary_ko": "지난 5억 년간 동물은 대체로 커져 왔고 해양 동물은 150배 커짐"}, {"n": 3, "label": "전환과 사례", "from": 6, "to": 10, "summary_ko": "최근 많은 동물이 작아지고 있으며 열이 한 원인으로, 알프스 샤무아 염소가 그 예임"}], "gloss": [{"w": "fine-tuned", "m": "미세 조정된"}, {"w": "inhabit", "m": "서식하다", "form": "inhabits", "note": "동사 inhabit의 3인칭 단수 현재형(관계절 it inhabits 안의 주어 it(=한 종)이 단수)"}, {"w": "fluctuation", "m": "변동", "form": "fluctuations", "note": "명사 fluctuation의 복수형"}, {"w": "significant", "m": "상당한, 중요한"}, {"w": "trend", "m": "경향"}, {"w": "notable", "m": "두드러지는, 주목할 만한"}, {"w": "marine", "m": "해양의"}, {"w": "average", "m": "평균의"}, {"w": "shrink", "m": "줄어들다, 작아지다", "form": "shrinking", "note": "동사 shrink의 현재분사형(are shrinking, 진행형)"}, {"w": "heat", "m": "열, 더위"}, {"w": "overheat", "m": "과열되다", "form": "overheating", "note": "동사 overheat의 동명사형(avoid 뒤에 목적어로 쓰임)"}, {"w": "rest", "m": "휴식을 취하다", "form": "resting", "note": "동사 rest의 동명사형(spend ... resting, 휴식하는 데 시간을 보냄)"}, {"w": "generation", "m": "세대", "form": "generations", "note": "명사 generation의 복수형"}, {"w": "species", "m": "종(생물 분류 단위)"}, {"w": "signal", "m": "나타내다, 신호를 보내다", "form": "signalled", "note": "동사 signal의 과거분사형(have signalled, 현재완료)"}], "qa": [{"chunk": 1, "q": "오랜 시간에 걸친 크기의 변동이 종종 나타내 온 것은?", "opts": ["종의 개체 수 증가", "환경에서의 상당한 변화", "먹이 종류의 감소"], "ans": 1, "why": ["3번 문장에서 크기의 변동은 종종 환경에서의 상당한 변화를 나타내 왔다고 함.", "개체 수나 먹이 종류에 대한 언급은 지문에 없음."], "ev_en": "Over large periods of time, size fluctuations have often signalled significant changes in the environment.", "ev_ko": "오랜 시간에 걸쳐, 크기의 변동은 종종 환경에서의 상당한 변화를 나타내 왔다."}, {"chunk": 2, "q": "지난 5억 년 동안 해양 동물의 평균 몸 크기는 어떻게 되었는가?", "opts": ["150분의 1로 줄었다", "거의 변하지 않았다", "150배로 커졌다"], "ans": 2, "why": ["5번 문장에서 해양 동물의 평균 몸 크기가 150배로 증가했다고 함.", "4번 문장에서 일반적인 경향도 동물이 커지는 쪽이었음.", "줄었다거나 변하지 않았다는 내용은 지문과 반대임."], "ev_en": "It\u2019s particularly notable in marine animals, whose average body size has increased 150-fold in this time.", "ev_ko": "그것은 특히 해양 동물들에게서 두드러지는데, 그들의 평균 몸 크기는 이 시기에 150배로 증가해 왔다."}, {"chunk": 3, "q": "새로운 세대의 샤무아 염소가 더 작아진 직접적인 과정은?", "opts": ["천적을 피해 더 높은 곳으로 이동했다.", "과열을 피하려고 먹이를 찾기보다 쉬는 시간이 늘었다.", "기온이 내려가서 몸을 작게 유지했다."], "ans": 1, "why": ["10번 문장에서 샤무아 염소는 과열을 피하려고 먹이를 찾기보다 쉬는 데 더 많은 시간을 보낸다고 함.", "그 결과 몇 십 년 만에 새 세대가 25% 더 작아졌음.", "천적 이야기는 없고, 9번 문장에서 기온은 내려간 것이 아니라 3~4도 올랐음."], "ev_en": "To avoid overheating, chamois goats now spend more of their days resting rather than searching for food, and as a result, in just a few decades, the new generations of chamois are 25 percent smaller.", "ev_ko": "과열을 피하기 위해서, 샤무아 염소들은 이제 먹이를 찾는 것보다 휴식을 취하는 데 더 많은 그들의 날들을 보내고, 결과적으로, 단지 몇 십 년 만에, 새로운 세대들의 샤무아는 25% 더 작아져 있다."}], "tf": [{"s": "종의 크기는 우연이 아니라 종과 그 종이 사는 세계 사이의 미세 조정된 상호 작용이다.", "t": true, "why": ["1번 문장은 크기가 우연이 아니라고 하고, 2번 문장은 종과 서식 환경 사이의 상호 작용이라고 하므로 맞음."], "ev_en": "It\u2019s a fine-tuned interaction between a species and the world it inhabits.", "ev_ko": "그것은 한 종과 그것이 서식하는 세계 사이의 미세 조정된 상호 작용이다."}, {"s": "지난 5억 년 동안 동물은 대체로 점점 커지는 쪽으로 변해 왔다.", "t": true, "why": ["4번 문장의 내용이므로 맞음."], "ev_en": "Generally speaking, over the last five hundred million years, the trend has been towards animals getting larger.", "ev_ko": "일반적으로 말해서, 지난 5억 년 동안, 그 경향은 동물들이 점점 커지는 쪽으로 되어 왔다."}, {"s": "해양 동물의 평균 몸 크기는 지난 5억 년 동안 150배로 줄어들었다.", "t": false, "why": ["틀린 부분은 \"줄어들었다\"임.", "5번 문장에 따르면 해양 동물의 평균 몸 크기는 150배로 증가함."], "ev_en": "It\u2019s particularly notable in marine animals, whose average body size has increased 150-fold in this time.", "ev_ko": "그것은 특히 해양 동물들에게서 두드러지는데, 그들의 평균 몸 크기는 이 시기에 150배로 증가해 왔다."}, {"s": "이탈리아 알프스에 사는 동물들은 1980년대 이후 기온이 3~4도 내려가는 것을 겪었다.", "t": false, "why": ["틀린 부분은 \"내려가는\"임.", "9번 문장에 따르면 기온은 섭씨 3에서 4도 상승함."], "ev_en": "Animals living in the Italian Alps, for example, have seen temperatures rise by three to four degrees Celsius since the 1980s.", "ev_ko": "예를 들어, 이탈리아 알프스에 살고 있는 동물들은 1980년대 이후로 기온이 섭씨 3에서 4도만큼 상승하는 것을 보아 왔다."}, {"s": "새로운 세대의 샤무아 염소는 단지 몇 십 년 만에 25% 더 작아졌다.", "t": true, "why": ["10번 문장의 내용이므로 맞음."], "ev_en": "To avoid overheating, chamois goats now spend more of their days resting rather than searching for food, and as a result, in just a few decades, the new generations of chamois are 25 percent smaller.", "ev_ko": "과열을 피하기 위해서, 샤무아 염소들은 이제 먹이를 찾는 것보다 휴식을 취하는 데 더 많은 그들의 날들을 보내고, 결과적으로, 단지 몇 십 년 만에, 새로운 세대들의 샤무아는 25% 더 작아져 있다."}], "flow": {"fixed": "종의 크기는 우연이 아니라 종과 그 서식 환경 사이의 미세 조정된 상호 작용이어서, 크기의 변동은 환경의 상당한 변화를 알려 주곤 했다.", "order": ["지난 5억 년 동안 동물은 대체로 점점 커져 왔고, 특히 해양 동물의 평균 몸 크기는 150배로 늘어났다.", "하지만 최근에는 이 경향에 변화가 나타나, 많은 동물이 작아지고 있으며 한 가지 주요 원인은 열인 것으로 보인다.", "예를 들어 알프스의 샤무아 염소는 과열을 피하려고 먹이를 찾기보다 쉬는 시간이 늘어, 몇 십 년 만에 새 세대가 25% 더 작아졌다."], "clue": ["도입 바로 뒤에서 \"지난 5억 년 동안\"으로 과거부터 이어진 일반적 경향을 설명함", "\"하지만 최근에는\"으로 앞의 커지는 경향과 반대되는 변화를 제시함", "\"예를 들어\"로 앞의 원인(열)을 구체적인 동물 사례로 보여 줌"], "why": ["환경과 크기의 관계 -> 과거에는 커지는 경향 -> 최근에는 작아짐 -> 샤무아 염소 사례 순서임."], "cards": ["지난 5억 년 동안 동물은 대체로 점점 커져 왔고, 특히 해양 동물의 평균 몸 크기는 150배로 늘어났다.", "예를 들어 알프스의 샤무아 염소는 과열을 피하려고 먹이를 찾기보다 쉬는 시간이 늘어, 몇 십 년 만에 새 세대가 25% 더 작아졌다.", "하지만 최근에는 이 경향에 변화가 나타나, 많은 동물이 작아지고 있으며 한 가지 주요 원인은 열인 것으로 보인다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "The size of a species is not accidental.", "ko": "종의 크기는 우연한 것이 아니다."}, {"n": 2, "en": "It\u2019s a fine-tuned interaction between a species and the world it inhabits.", "ko": "그것은 한 종과 그것이 서식하는 세계 사이의 미세 조정된 상호 작용이다."}, {"n": 3, "en": "Over large periods of time, size fluctuations have often signalled significant changes in the environment.", "ko": "오랜 시간에 걸쳐, 크기의 변동은 종종 환경에서의 상당한 변화를 나타내 왔다."}, {"n": 4, "en": "Generally speaking, over the last five hundred million years, the trend has been towards animals getting larger.", "ko": "일반적으로 말해서, 지난 5억 년 동안, 그 경향은 동물들이 점점 커지는 쪽으로 되어 왔다."}, {"n": 5, "en": "It\u2019s particularly notable in marine animals, whose average body size has increased 150-fold in this time.", "ko": "그것은 특히 해양 동물들에게서 두드러지는데, 그들의 평균 몸 크기는 이 시기에 150배로 증가해 왔다."}, {"n": 6, "en": "But we are beginning to see changes in this trend.", "ko": "하지만 우리는 이 경향에서 변화를 관찰하기 시작하고 있다."}, {"n": 7, "en": "Scientists have discovered that many animals are shrinking.", "ko": "과학자들은 많은 동물이 작아지고 있다는 것을 발견해 왔다."}, {"n": 8, "en": "Around the world, species in every category have been found to be getting smaller, and one major cause appears to be the heat.", "ko": "전 세계적으로, 모든 범주의 종들이 점점 작아지고 있는 것으로 발견되어 왔고, 한 가지 주요 원인은 열인 것으로 보인다."}, {"n": 9, "en": "Animals living in the Italian Alps, for example, have seen temperatures rise by three to four degrees Celsius since the 1980s.", "ko": "예를 들어, 이탈리아 알프스에 살고 있는 동물들은 1980년대 이후로 기온이 섭씨 3에서 4도만큼 상승하는 것을 보아 왔다."}, {"n": 10, "en": "To avoid overheating, chamois goats now spend more of their days resting rather than searching for food, and as a result, in just a few decades, the new generations of chamois are 25 percent smaller.", "ko": "과열을 피하기 위해서, 샤무아 염소들은 이제 먹이를 찾는 것보다 휴식을 취하는 데 더 많은 그들의 날들을 보내고, 결과적으로, 단지 몇 십 년 만에, 새로운 세대들의 샤무아는 25% 더 작아져 있다."}]}, {"id": "2311-37", "short": "23년 11월 37번", "group": "23년 11월", "num": 37, "topic_ko": "무작위 추출의 한계와 전체 데이터의 자유로움", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "무작위 추출법은 디지털 시대 이전에 좋은 지름길이었음"}, {"n": 2, "label": "반전", "from": 3, "to": 4, "summary_ko": "추출은 정보를 잃게 하지만 전체 데이터는 더 큰 탐색의 자유를 줌"}, {"n": 3, "label": "전개와 결말", "from": 5, "to": 9, "summary_ko": "라이트 필드 카메라처럼 모든 정보를 담으면 나중에 초점을 정할 수 있고 재사용성이 높음"}], "gloss": [{"w": "random sampling", "m": "무작위 추출법 (sample: 표본을 뽑다, 추출하다)"}, {"w": "shortcut", "m": "지름길"}, {"w": "pre\u2011digital", "m": "디지털 시대 이전의"}, {"w": "convert", "m": "변환하다", "form": "converting", "note": "동사 convert의 동명사형(주어 역할)"}, {"w": "dataset", "m": "데이터 세트"}, {"w": "explore", "m": "탐색하다"}, {"w": "fitting", "m": "적절한, 알맞은"}, {"w": "capture", "m": "포착하다", "form": "captures", "note": "동사 capture의 3인칭 단수 현재형(주어 which가 단수 camera)"}, {"w": "conventional", "m": "기존의, 전통적인"}, {"w": "ray", "m": "광선", "form": "rays", "note": "명사 ray의 복수형"}, {"w": "focus", "m": "초점을 맞추다"}, {"w": "reusable", "m": "재사용 가능한", "form": "reuseable", "note": "본문의 철자 reuseable은 reusable의 비표준 표기(뜻은 같음)"}, {"w": "shutter", "m": "(카메라) 셔터"}, {"w": "light\u2011field camera", "m": "라이트 필드 카메라(빛의 모든 방향 정보를 담는 카메라)"}], "qa": [{"chunk": 1, "q": "무작위 추출법이 과거에 가졌던 장점은?", "opts": ["디지털 시대 이전에 대규모 데이터 문제의 분석을 가능하게 했다.", "정보를 전혀 잃지 않고 분석할 수 있었다.", "전체 데이터보다 더 정확한 결과를 주었다."], "ans": 0, "why": ["2번 문장이 근거이다.", "무작위 추출은 디지털 시대 이전에 큰 데이터 문제 분석을 가능하게 한 좋은 지름길이었다.", "3번 문장에서 추출할 때는 정보가 손실된다고 하므로 \u2018정보를 전혀 잃지 않고 분석할 수 있었다\u2019는 진술은 틀리다.", "더 정확하다는 내용은 지문에 없다."], "ev_en": "It made analysis of large data problems possible in the pre\u2011digital era.", "ev_ko": "그것은 디지털 시대 이전에 상당한 데이터 문제 분석을 가능하게 했다."}, {"chunk": 2, "q": "전체(또는 전체에 가까운) 데이터 세트를 가질 때의 장점은?", "opts": ["파일 크기가 더 작아진다.", "데이터를 다른 각도에서 보거나 특정 측면을 자세히 볼 자유가 커진다.", "분석 시간이 크게 줄어든다."], "ans": 1, "why": ["4번 문장이 근거이다.", "전체 데이터는 탐색하고, 다른 각도에서 보고, 특정 측면을 더 자세히 볼 자유를 준다.", "작은 파일로 변환하면 오히려 데이터 손실이 생긴다는 것이 3번 문장의 내용이므로 파일 크기가 작아지는 것은 장점이 아니다.", "분석 시간이 크게 줄어든다는 내용은 지문에 없다."], "ev_en": "Having the full (or close to the full) dataset provides a lot more freedom to explore, to look at the data from different angles or to look closer at certain aspects of it.", "ev_ko": "전체(또는 전체에 가까운) 데이터 세트를 가지는 것은 탐색하거나 다른 각도에서 데이터를 살펴보거나 그것의 특정 측면들을 더 자세히 보게 하는 자유를 훨씬 더 많이 제공한다."}, {"chunk": 3, "q": "라이트 필드 카메라의 특징으로 알맞은 것은?", "opts": ["셔터를 누르기 전에 초점을 정해야 한다.", "한 평면의 빛만 포착한다.", "사진사가 나중에 이미지의 어느 요소에 초점을 맞출지 정할 수 있다."], "ans": 2, "why": ["6번 문장이 근거이다.", "전체 광선을 담기 때문에 초점은 나중에 정하면 된다.", "\u2018셔터를 누르기 전에 초점을 정해야 한다\u2019는 일반 사진의 특징이고(9번 문장), \u2018한 평면의 빛만 포착한다\u2019는 기존 카메라의 특징이다(5번 문장)."], "ev_en": "The photographers can decide later which element of an image to focus on in the digital file.", "ev_ko": "사진사들은 디지털 파일에서 이미지의 어느 요소에 초점을 맞출지를 나중에 결정할 수 있다."}], "tf": [{"s": "추출을 할 때 정보가 손실되는 것은 디지털 이미지를 더 작은 파일로 바꿀 때 데이터가 손실되는 것과 비슷하다.", "t": true, "why": ["3번 문장의 내용이다."], "ev_en": "But much as converting a digital image or song into a smaller file results in loss of data, information is lost when sampling.", "ev_ko": "그러나 디지털 이미지나 노래를 더 작은 파일로 변환하는 것이 데이터 손실을 유발하는 것과 마찬가지로, 추출을 할 때 정보가 손실된다."}, {"s": "라이트 필드 카메라는 기존 카메라처럼 한 평면의 빛만 포착한다.", "t": false, "why": ["기존 카메라의 특징을 라이트 필드 카메라에 바꿔 붙인 진술이다.", "5번 문장은 not just A but B 구조로, A(한 평면의 빛)뿐 아니라 B(전체 라이트 필드의 광선)도 포착한다는 뜻이다.", "\u2018한 평면의 빛\u2019은 as with conventional cameras(기존 카메라처럼), 즉 기존 카메라의 방식이다.", "공식 해석은 어순 때문에 \u2018한 평면의 빛만 포착할 뿐만 아니라\u2019로 읽혀 헷갈리기 쉬우므로, not just A but B는 \u2018A뿐 아니라 B도\u2019로 이해해야 한다."], "ev_en": "A fitting example may be the light\u2011field camera, which captures not just a single plane of light, as with conventional cameras, but rays from the entire light field, some 11 million of them.", "ev_ko": "라이트 필드 카메라가 적절한 비유가 될 수 있는데, 그것은 기존 카메라처럼 한 평면의 빛만 포착할 뿐만 아니라 약 1,100만 개에 달하는 전체 라이트 필드로부터의 광선들도 포착한다."}, {"s": "라이트 필드 카메라로 찍을 때는 모든 정보를 모아 두더라도 촬영을 시작할 때 초점부터 맞춰야 한다.", "t": false, "why": ["지문과 반대이다.", "7번 문장은 처음에 초점을 맞출 필요가 없다(no need to focus at the beginning)고 한다.", "모든 정보를 수집해 두면 나중에 초점을 맞추는 것이 가능하기 때문이다."], "ev_en": "There is no need to focus at the beginning, since collecting all the information makes it possible to do that afterwards.", "ev_ko": "모든 정보를 수집하는 것은 그것을 나중에 하는 것을 가능하게 만들기 때문에, 처음에 초점을 맞출 필요는 없다."}, {"s": "일반 사진에서는 사진사가 셔터를 누른 뒤에 초점을 맞출 대상을 결정한다.", "t": false, "why": ["시점이 바뀐 진술이다.", "일반 사진에서는 셔터를 누르기 전에 무엇에 초점을 맞출지 결정해야 한다."], "ev_en": "As a result, the information is more \u201creuseable\u201d than ordinary pictures, where the photographer has to decide what to focus on before she presses the shutter.", "ev_ko": "결과적으로 사진사가 셔터를 누르기 전에 그녀가 무엇에 초점을 맞출지를 결정해야 하는 일반 사진들보다 그 정보는 더 \u2018재사용 가능\u2019하다."}, {"s": "라이트 필드 카메라는 전체 라이트 필드의 광선이 포함되기 때문에 모든 데이터에 더 가깝다.", "t": true, "why": ["8번 문장의 내용이다.", "전체 라이트 필드의 광선이 포함되므로 모든 데이터에 더 가깝다는 뜻이다."], "ev_en": "Because rays from the entire light field are included, it is closer to all the data.", "ev_ko": "전체 라이트 필드의 빛이 포함되기 때문에, 그것은 모든 데이터에 더 가깝다."}], "flow": {"fixed": "무작위 추출법은 오랫동안 좋은 지름길이었고, 디지털 시대 이전에는 대규모 데이터 분석을 가능하게 해 주었다.", "order": ["그러나 추출을 하면 정보가 사라지는 반면, 전체에 가까운 데이터를 가지면 다른 각도에서 보거나 특정 측면을 자세히 볼 자유가 훨씬 커진다.", "이에 알맞은 예가 라이트 필드 카메라로, 한 평면이 아니라 전체 광선을 담아 두기 때문에 사진사는 무엇에 초점을 맞출지 나중에 정하면 된다.", "결과적으로 이 카메라의 정보는 전체 데이터에 더 가까워서, 촬영 전에 초점을 정해야 하는 일반 사진보다 더 재사용하기 쉽다."], "clue": ["'그러나'로 앞의 장점을 뒤집어 추출의 한계와 전체 데이터의 장점을 말함", "'이에 알맞은 예'가 앞의 전체 데이터의 자유로움을 예로 보여 줌", "'결과적으로'로 앞의 내용을 받아 일반 사진과 비교하며 마무리함"], "why": ["무작위 추출은 과거에 좋은 지름길", "추출은 정보를 잃고 전체 데이터는 더 자유로움", "라이트 필드 카메라가 좋은 예", "그래서 정보가 더 재사용 가능함"], "cards": ["결과적으로 이 카메라의 정보는 전체 데이터에 더 가까워서, 촬영 전에 초점을 정해야 하는 일반 사진보다 더 재사용하기 쉽다.", "이에 알맞은 예가 라이트 필드 카메라로, 한 평면이 아니라 전체 광선을 담아 두기 때문에 사진사는 무엇에 초점을 맞출지 나중에 정하면 된다.", "그러나 추출을 하면 정보가 사라지는 반면, 전체에 가까운 데이터를 가지면 다른 각도에서 보거나 특정 측면을 자세히 볼 자유가 훨씬 커진다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "For a long time, random sampling was a good shortcut.", "ko": "오랫동안, 무작위 추출법은 좋은 지름길이었다."}, {"n": 2, "en": "It made analysis of large data problems possible in the pre\u2011digital era.", "ko": "그것은 디지털 시대 이전에 상당한 데이터 문제 분석을 가능하게 했다."}, {"n": 3, "en": "But much as converting a digital image or song into a smaller file results in loss of data, information is lost when sampling.", "ko": "그러나 디지털 이미지나 노래를 더 작은 파일로 변환하는 것이 데이터 손실을 유발하는 것과 마찬가지로, 추출을 할 때 정보가 손실된다."}, {"n": 4, "en": "Having the full (or close to the full) dataset provides a lot more freedom to explore, to look at the data from different angles or to look closer at certain aspects of it.", "ko": "전체(또는 전체에 가까운) 데이터 세트를 가지는 것은 탐색하거나 다른 각도에서 데이터를 살펴보거나 그것의 특정 측면들을 더 자세히 보게 하는 자유를 훨씬 더 많이 제공한다."}, {"n": 5, "en": "A fitting example may be the light\u2011field camera, which captures not just a single plane of light, as with conventional cameras, but rays from the entire light field, some 11 million of them.", "ko": "라이트 필드 카메라가 적절한 비유가 될 수 있는데, 그것은 기존 카메라처럼 한 평면의 빛만 포착할 뿐만 아니라 약 1,100만 개에 달하는 전체 라이트 필드로부터의 광선들도 포착한다."}, {"n": 6, "en": "The photographers can decide later which element of an image to focus on in the digital file.", "ko": "사진사들은 디지털 파일에서 이미지의 어느 요소에 초점을 맞출지를 나중에 결정할 수 있다."}, {"n": 7, "en": "There is no need to focus at the beginning, since collecting all the information makes it possible to do that afterwards.", "ko": "모든 정보를 수집하는 것은 그것을 나중에 하는 것을 가능하게 만들기 때문에, 처음에 초점을 맞출 필요는 없다."}, {"n": 8, "en": "Because rays from the entire light field are included, it is closer to all the data.", "ko": "전체 라이트 필드의 빛이 포함되기 때문에, 그것은 모든 데이터에 더 가깝다."}, {"n": 9, "en": "As a result, the information is more \u201creuseable\u201d than ordinary pictures, where the photographer has to decide what to focus on before she presses the shutter.", "ko": "결과적으로 사진사가 셔터를 누르기 전에 그녀가 무엇에 초점을 맞출지를 결정해야 하는 일반 사진들보다 그 정보는 더 \u2018재사용 가능\u2019하다."}]}, {"id": "2311-38", "short": "23년 11월 38번", "group": "23년 11월", "num": 38, "topic_ko": "외향적 리더가 낫다는 고정 관념과 내향적 리더의 서번트 리더십", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 4, "summary_ko": "내향적 리더는 외향적 리더가 낫다는 억측을 극복해야 하며 이 고정 관념은 재검토해야 함"}, {"n": 2, "label": "뒷받침 1", "from": 5, "to": 5, "summary_ko": "남을 돕고 성장시키려는 열망은 리더십의 핵심이며 내향적인 사람에게 더 흔함"}, {"n": 3, "label": "뒷받침 2", "from": 6, "to": 7, "summary_ko": "서번트 리더십은 타인의 목표 달성을 도우며 겸손이 결국 보답받음"}], "gloss": [{"w": "introverted", "m": "내향적인", "form": "Introverted", "note": "형용사 introverted가 문장 첫머리라 대문자로 시작함"}, {"w": "extrovert", "m": "외향적인 사람", "form": "extroverts", "note": "명사 extrovert의 복수형(2번 문장에는 형용사 extroverted도 쓰임)"}, {"w": "presumption", "m": "억측, 추정"}, {"w": "executive", "m": "임원", "form": "executives", "note": "명사 executive의 복수형"}, {"w": "barrier", "m": "장애물"}, {"w": "stereotype", "m": "고정 관념"}, {"w": "reexamine", "m": "재검토하다"}, {"w": "empower", "m": "힘을 주다, 권한을 주다"}, {"w": "retain", "m": "유지하다", "form": "retaining", "note": "동사 retain의 동명사형(전치사 in 뒤)"}, {"w": "so-called", "m": "소위, 이른바", "form": "So\u2011called", "note": "형용사 so-called가 문장 첫머리라 대문자로 시작함"}, {"w": "adhere to", "m": "~을 고수하다", "form": "adheres", "note": "동사 adhere의 3인칭 단수 현재형(주어 leadership이 단수)"}, {"w": "humility", "m": "겸손"}, {"w": "pay off", "m": "결실을 맺다", "form": "pays off", "note": "동사 pay의 3인칭 단수 현재형(주어 humility가 단수)"}, {"w": "servant", "m": "하인, 남을 위해 봉사하는 사람"}], "qa": [{"chunk": 1, "q": "내향적인 리더가 극복해야 하는 것은?", "opts": ["리더는 겸손해서는 안 된다는 믿음", "내향성은 타고나서 바꿀 수 없다는 믿음", "외향적인 사람이 더 유능한 리더라는 강한 문화적 억측"], "ans": 2, "why": ["1번 문장이 근거이다.", "strong cultural presumption(강한 문화적 억측)을 극복해야 한다고 한다.", "\u201c리더는 겸손해서는 안 된다는 믿음\u201d은 극복 대상으로 나오지 않는다. 겸손은 7번 문장에서 오히려 결국 결실을 맺는다고 한다.", "\u201c내향성은 타고나서 바꿀 수 없다는 믿음\u201d도 지문에 없는 내용이다."], "ev_en": "Introverted leaders do have to overcome the strong cultural presumption that extroverts are more effective leaders.", "ev_ko": "내향적인 리더들은 외향적인 사람들이 더 유능한 리더라는 강력한 문화적 억측을 극복해야 한다."}, {"chunk": 2, "q": "Regent 대학교 연구에서 발견한 내용으로 알맞은 것은?", "opts": ["남을 돕고 성장시키려는 열망은 리더십과 관련이 없다.", "그런 열망은 내향적인 사람보다 외향적인 사람 사이에서 더 흔하다.", "그런 열망은 리더가 되고 리더십을 유지하는 핵심 요소이며 내향적인 사람 사이에서 더 흔하다."], "ans": 2, "why": ["5번 문장이 근거이다.", "열망이 a key factor(핵심 요소)이고 외향적인 사람들보다 내향적인 사람들 사이에서 더 일반적이라고 한다.", "\u201c리더십과 관련이 없다\u201d는 진술은 핵심 요소라는 말과 반대이다.", "\u201c외향적인 사람 사이에서 더 흔하다\u201d는 진술은 비교 대상이 거꾸로이다."], "ev_en": "Regent University found that a desire to be of service to others and to empower them to grow, which is more common among introverts than extroverts, is a key factor in becoming a leader and retaining leadership.", "ev_ko": "Regent 대학교는 다른 사람들에게 도움이 되고 그들이 성장할 수 있도록 힘을 주고자 하는 열망이 리더가 되고 리더십을 유지하는 데 핵심적인 요소이고, 그것이 외향적인 사람들보다 내향적인 사람들 사이에서 더 일반적이라는 것을 발견했다."}, {"chunk": 3, "q": "서번트 리더십의 설명으로 알맞은 것은?", "opts": ["리더가 관심을 끌어 구성원을 이끄는 것을 중요하게 여긴다.", "회사의 목표를 먼저 이루고 나서 근로자를 돕는다.", "근로자나 고객이 목표를 달성하도록 도와 회사의 목표를 이룬다고 믿는다."], "ans": 2, "why": ["6번 문장이 근거이다.", "회사의 목표는 근로자나 고객이 그들의 목표를 달성하도록 도울 때 가장 잘 달성된다고 믿는다.", "\u201c관심을 끌어 구성원을 이끈다\u201d는 진술은 7번 문장에서 이런 리더는 관심을 추구하지 않는다고 하므로 틀리다.", "\u201c회사의 목표를 먼저 이루고 나서 근로자를 돕는다\u201d는 진술은 순서가 거꾸로이다. 근로자를 도움으로써 회사의 목표가 이루어진다."], "ev_en": "So\u2011called servant leadership, dating back to ancient philosophical literature, adheres to the belief that a company\u2019s goals are best achieved by helping workers or customers achieve their goals.", "ev_ko": "고대 철학 문헌으로 거슬러 올라가는 소위 서번트 리더십은 한 회사의 목표가 근로자나 고객이 그들의 목표를 달성하도록 도움으로써 가장 잘 달성된다는 믿음을 고수한다."}], "tf": [{"s": "관리자와 임원의 96% 이상이 외향적이다.", "t": true, "why": ["2번 문장이 근거이다.", "more than 96 percent of managers and executives are extroverted(관리자와 임원의 96% 이상이 외향적이다)라고 한다.", "인구는 거의 반반인데도 이렇게 쏠려 있다는 점이 핵심이다."], "ev_en": "Although the population splits into almost equal parts between introverts and extroverts, more than 96 percent of managers and executives are extroverted.", "ev_ko": "비록 인구는 내향적인 사람과 외향적인 사람 사이에서 거의 동등한 비율로 나뉘지만, 관리자와 임원의 96% 이상이 외향적이다."}, {"s": "필자는 외향적인 리더가 낫다는 고정 관념이 언제나 들어맞는다고 본다.", "t": false, "why": ["4번 문장은 이 고정 관념이 늘 들어맞지는 않는다(it doesn\u2019t always hold true)고 말한다.", "그래서 고정 관념을 다시 따져 봐야 한다(We must reexamine this stereotype)고 한다.", "올바른 내용은 고정 관념을 재검토해야 한다는 것이다."], "ev_en": "We must reexamine this stereotype, however, as it doesn\u2019t always hold true.", "ev_ko": "하지만 그것이 항상 맞는 것은 아니기 때문에 우리는 이 고정 관념을 재검토해야 한다."}, {"s": "2006년의 한 연구에서 기업 고위 임원의 65%가 내향성을 리더십의 장애물로 보았다.", "t": true, "why": ["3번 문장이 근거이다.", "2006년 연구에서 기업 고위 임원의 65%가 내향성을 리더십의 장애물(a barrier to leadership)로 보았다."], "ev_en": "In a study done in 2006, 65 percent of senior corporate executives viewed introversion as a barrier to leadership.", "ev_ko": "2006년에 실시된 한 연구에서, 기업 고위 임원의 65%가 내향성을 리더십의 장애물로 간주했다."}, {"s": "서번트 리더는 자신의 성과를 돋보이게 해 관심을 얻으려 한다.", "t": false, "why": ["7번 문장은 이런 리더가 관심을 추구하지 않는다(do not seek attention)고 한다.", "오히려 다른 사람들의 승리와 업적에 빛을 비추고 싶어 한다(shine a light on others\u2019 wins and achievements)고 한다.", "올바른 내용은 자신이 아니라 남을 돋보이게 하려 한다는 것이다."], "ev_en": "Such leaders do not seek attention but rather want to shine a light on others\u2019 wins and achievements; servant leadership requires humility, but that humility ultimately pays off.", "ev_ko": "그런 리더들은 관심을 추구하는 것이 아니라 오히려 다른 사람들의 승리와 업적에 빛을 비추고 싶어 하고, 서번트 리더십은 겸손을 필요로 하지만, 그 겸손은 궁극적으로 결실을 맺는다."}, {"s": "서번트 리더십은 고대 철학 문헌으로 거슬러 올라간다.", "t": true, "why": ["6번 문장이 근거이다.", "dating back to ancient philosophical literature(고대 철학 문헌으로 거슬러 올라가는)는 서번트 리더십을 꾸미는 말이다."], "ev_en": "So\u2011called servant leadership, dating back to ancient philosophical literature, adheres to the belief that a company\u2019s goals are best achieved by helping workers or customers achieve their goals.", "ev_ko": "고대 철학 문헌으로 거슬러 올라가는 소위 서번트 리더십은 한 회사의 목표가 근로자나 고객이 그들의 목표를 달성하도록 도움으로써 가장 잘 달성된다는 믿음을 고수한다."}], "flow": {"fixed": "내향적인 리더는 외향적인 사람이 더 유능한 리더라는 강한 문화적 억측을 넘어서야 하며, 실제로 관리자와 임원의 96% 이상이 외향적이다.", "order": ["이를 뒷받침하는 수치로, 2006년의 한 연구에서 기업 고위 임원 상당수가 내향성을 리더십의 장애물로 보았지만, 이런 고정 관념은 늘 들어맞지는 않으므로 다시 따져 봐야 한다.", "고정 관념을 다시 따져 봐야 하는 근거로, 먼저 한 대학 연구는 남을 돕고 성장시키려는 열망이 리더가 되고 리더십을 유지하는 핵심이며 외향적인 사람보다 내향적인 사람에게 더 흔하다고 밝혔다.", "이어서 소개되는 이른바 서번트 리더십은, 근로자나 고객의 목표 달성을 도우면 회사의 목표도 가장 잘 이루어진다고 믿으며, 이 리더는 관심을 구하지 않고 겸손하게 남을 빛내어 결국 보답받는다."], "clue": ["'이를 뒷받침하는 수치'가 맨 위 덩어리의 96% 수치에 이어지고, '하지만'식 반전으로 재검토를 제기함", "'고정 관념을 다시 따져 봐야 하는 근거로'는 재검토 주장이 먼저 나온 뒤에만 올 수 있고, '먼저'가 이 연구 소개를 다음 덩어리보다 앞에 놓음", "앞 덩어리의 열망 제시가 끝난 뒤 '이어서'로 새 개념인 서번트 리더십을 소개함"], "why": ["내향적 리더는 억측을 넘어야 함", "관련 수치와 함께 고정 관념은 재검토해야 함", "재검토의 근거로 내향적인 사람에게 흔한 열망을 제시함", "이 열망과 통하는 서번트 리더십을 소개하며 겸손이 결국 보답받음을 말함"], "cards": ["이어서 소개되는 이른바 서번트 리더십은, 근로자나 고객의 목표 달성을 도우면 회사의 목표도 가장 잘 이루어진다고 믿으며, 이 리더는 관심을 구하지 않고 겸손하게 남을 빛내어 결국 보답받는다.", "고정 관념을 다시 따져 봐야 하는 근거로, 먼저 한 대학 연구는 남을 돕고 성장시키려는 열망이 리더가 되고 리더십을 유지하는 핵심이며 외향적인 사람보다 내향적인 사람에게 더 흔하다고 밝혔다.", "이를 뒷받침하는 수치로, 2006년의 한 연구에서 기업 고위 임원 상당수가 내향성을 리더십의 장애물로 보았지만, 이런 고정 관념은 늘 들어맞지는 않으므로 다시 따져 봐야 한다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Introverted leaders do have to overcome the strong cultural presumption that extroverts are more effective leaders.", "ko": "내향적인 리더들은 외향적인 사람들이 더 유능한 리더라는 강력한 문화적 억측을 극복해야 한다."}, {"n": 2, "en": "Although the population splits into almost equal parts between introverts and extroverts, more than 96 percent of managers and executives are extroverted.", "ko": "비록 인구는 내향적인 사람과 외향적인 사람 사이에서 거의 동등한 비율로 나뉘지만, 관리자와 임원의 96% 이상이 외향적이다."}, {"n": 3, "en": "In a study done in 2006, 65 percent of senior corporate executives viewed introversion as a barrier to leadership.", "ko": "2006년에 실시된 한 연구에서, 기업 고위 임원의 65%가 내향성을 리더십의 장애물로 간주했다."}, {"n": 4, "en": "We must reexamine this stereotype, however, as it doesn\u2019t always hold true.", "ko": "하지만 그것이 항상 맞는 것은 아니기 때문에 우리는 이 고정 관념을 재검토해야 한다."}, {"n": 5, "en": "Regent University found that a desire to be of service to others and to empower them to grow, which is more common among introverts than extroverts, is a key factor in becoming a leader and retaining leadership.", "ko": "Regent 대학교는 다른 사람들에게 도움이 되고 그들이 성장할 수 있도록 힘을 주고자 하는 열망이 리더가 되고 리더십을 유지하는 데 핵심적인 요소이고, 그것이 외향적인 사람들보다 내향적인 사람들 사이에서 더 일반적이라는 것을 발견했다."}, {"n": 6, "en": "So\u2011called servant leadership, dating back to ancient philosophical literature, adheres to the belief that a company\u2019s goals are best achieved by helping workers or customers achieve their goals.", "ko": "고대 철학 문헌으로 거슬러 올라가는 소위 서번트 리더십은 한 회사의 목표가 근로자나 고객이 그들의 목표를 달성하도록 도움으로써 가장 잘 달성된다는 믿음을 고수한다."}, {"n": 7, "en": "Such leaders do not seek attention but rather want to shine a light on others\u2019 wins and achievements; servant leadership requires humility, but that humility ultimately pays off.", "ko": "그런 리더들은 관심을 추구하는 것이 아니라 오히려 다른 사람들의 승리와 업적에 빛을 비추고 싶어 하고, 서번트 리더십은 겸손을 필요로 하지만, 그 겸손은 궁극적으로 결실을 맺는다."}]}, {"id": "2311-39", "short": "23년 11월 39번", "group": "23년 11월", "num": 39, "topic_ko": "정확한 측정에 대한 추구와 부정확성 허용의 이점", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "프랑스가 정밀한 측정 단위 체계를 만들었으나 양자 역학이 완벽한 측정의 꿈을 깸"}, {"n": 2, "label": "전개", "from": 3, "to": 4, "summary_ko": "그래도 완벽한 측정을 향한 정신은 공학자와 과학자, 비즈니스 세계에서 이어지고 확장됨"}, {"n": 3, "label": "반전과 결말", "from": 5, "to": 7, "summary_ko": "부정확성을 허용하면 훨씬 더 많은 데이터를 얻을 수 있어 때로는 더 많은 것이 더 훌륭함"}], "gloss": [{"w": "precisely", "m": "정확하게, 정밀하게"}, {"w": "unit", "m": "단위", "form": "units", "note": "명사 unit의 복수형"}, {"w": "measurement", "m": "측정"}, {"w": "adopt", "m": "채택하다"}, {"w": "quantum mechanics", "m": "양자 역학"}, {"w": "destroy", "m": "파괴하다, 깨뜨리다", "form": "destroyed", "note": "동사 destroy의 과거형"}, {"w": "flawlessly", "m": "흠 없이, 완벽하게"}, {"w": "mindset", "m": "사고방식, 정신 자세"}, {"w": "commerce", "m": "상업"}, {"w": "precision", "m": "정확성"}, {"w": "imprecision", "m": "부정확성"}, {"w": "shortcoming", "m": "단점"}, {"w": "tradeoff", "m": "맞교환, 절충"}, {"w": "relax", "m": "완화하다", "form": "relaxing", "note": "동사 relax의 동명사형(전치사 for 뒤에 쓰임)"}], "qa": [{"chunk": 1, "q": "1920년대 양자 역학의 발견이 가져온 결과는?", "opts": ["프랑스가 측정 단위 체계를 처음 개발했다.", "다른 나라들이 프랑스의 기준을 채택하기 시작했다.", "포괄적이고 완벽한 측정에 대한 꿈이 영원히 깨졌다."], "ans": 2, "why": ["2번 문장에서 양자 역학의 발견이 완벽한 측정에 대한 꿈을 영원히 깨 버렸다고 함.", "프랑스의 단위 체계 개발과 다른 나라의 채택은 1번 문장에서 19세기까지의 일로 나오며, 1920년대의 일이 아님."], "ev_en": "Just half a century later, in the 1920s, the discoveries of quantum mechanics forever destroyed the dream of comprehensive and perfect measurement.", "ev_ko": "불과 반세기 후, 1920년대에, 양자 역학의 발견은 포괄적이고 완벽한 측정에 대한 꿈을 영원히 깨 버렸다."}, {"chunk": 2, "q": "4번 문장에 따르면 비즈니스 세계에서 완벽하게 측정하려는 정신은 어떻게 되었는가?", "opts": ["줄어들었다.", "소수 물리학자 집단 안에서만 이어졌다.", "수학과 통계학의 영향으로 오히려 확장되었다."], "ans": 2, "why": ["4번 문장에서 비즈니스 세계에서는 그것이 심지어 확장되었다고 함.", "그 이유는 수학과 통계학이 상업의 모든 영역에 영향을 미치기 시작했기 때문임.", "소수 물리학자 집단은 오히려 그 정신에서 제외된 쪽임(3번 문장)."], "ev_en": "In the world of business it even expanded, as the precision-oriented sciences of mathematics and statistics began to influence all areas of commerce.", "ev_ko": "정확성을 지향하는 수학과 통계학이라는 과학이 상업의 모든 영역에 영향을 미치기 시작하면서 비즈니스의 세계에서 그것은 심지어 확장되었다."}, {"chunk": 3, "q": "허용 가능한 오류의 기준을 완화하는 대가로 얻을 수 있는 것은?", "opts": ["더 정밀한 측정 단위", "훨씬 더 많은 데이터", "완벽한 측정 결과"], "ans": 1, "why": ["6번 문장에서 오류의 기준을 완화하면 훨씬 더 많은 데이터를 얻을 수 있다고 함.", "정밀한 단위와 완벽한 측정은 오히려 지금까지 추구해 온 것임."], "ev_en": "As a tradeoff for relaxing the standards of allowable errors, one can get a hold of much more data.", "ev_ko": "허용 가능한 오류의 기준을 완화하는 것에 대한 맞교환으로서, 사람은 훨씬 더 많은 데이터를 얻을 수 있다."}], "tf": [{"s": "19세기까지 프랑스는 정밀하게 규정된 측정 단위 체계를 개발했고, 다른 국가들도 같은 기준을 채택하게 하려 했다.", "t": true, "why": ["1번 문장의 내용이므로 맞음."], "ev_en": "By the nineteenth century, France had developed a system of precisely defined units of measurement to capture space, time, and more, and had begun to get other nations to adopt the same standards.", "ev_ko": "19세기까지, 프랑스는 공간, 시간, 그리고 더 많은 것을 포착하기 위해 정밀하게 규정된 측정 단위의 체계를 개발했고, 다른 국가들이 동일한 기준을 채택하도록 만들기 시작했었다."}, {"s": "양자 역학의 발견 이후 공학자와 과학자 모두 완벽하게 측정하려는 노력을 곧바로 멈췄다.", "t": false, "why": ["틀린 부분은 \"모두 곧바로 멈췄다\"임.", "3번 문장에 따르면 비교적 소수의 물리학자를 제외하고는 공학자와 과학자 사이에서 그 정신이 계속됨."], "ev_en": "And yet, outside a relatively small circle of physicists, the mindset of humankind\u2019s drive to flawlessly measure continued among engineers and scientists.", "ev_ko": "그러나 비교적 소수 집단의 물리학자를 제외하고는 공학자와 과학자 사이에서 완벽하게 측정하려고 하는 인류의 추진 정신은 계속되었다."}, {"s": "수학과 통계학이 상업의 모든 영역에 영향을 미치기 시작하면서 비즈니스 세계에서 정확성을 추구하는 정신이 확장되었다.", "t": true, "why": ["4번 문장의 내용이므로 맞음."], "ev_en": "In the world of business it even expanded, as the precision-oriented sciences of mathematics and statistics began to influence all areas of commerce.", "ev_ko": "정확성을 지향하는 수학과 통계학이라는 과학이 상업의 모든 영역에 영향을 미치기 시작하면서 비즈니스의 세계에서 그것은 심지어 확장되었다."}, {"s": "오늘날 많은 새로운 상황에서 부정확성을 허용하는 것은 단점일 뿐이다.", "t": false, "why": ["틀린 부분은 \"단점일 뿐\"임.", "5번 문장에 따르면 부정확성을 허용하는 것은 단점이 아니라 긍정적인 특성이 될 수 있음."], "ev_en": "However, contrary to the trend of the past several decades, in many new situations that are occurring today, allowing for imprecision \u2015 for messiness \u2015 may be a positive feature, not a shortcoming.", "ev_ko": "그러나, 지난 수십 년간의 경향과 반대로, 오늘날 발생하는 많은 새로운 상황에서 부정확성, 즉, 번잡함을 허용하는 것은 단점이 아니라 긍정적인 특성이 될 수 있다."}, {"s": "허용 오류의 기준을 완화하면 훨씬 더 많은 데이터를 얻을 수 있다.", "t": true, "why": ["6번 문장의 내용이므로 맞음."], "ev_en": "As a tradeoff for relaxing the standards of allowable errors, one can get a hold of much more data.", "ev_ko": "허용 가능한 오류의 기준을 완화하는 것에 대한 맞교환으로서, 사람은 훨씬 더 많은 데이터를 얻을 수 있다."}], "flow": {"fixed": "19세기에 프랑스는 정밀하게 규정된 측정 단위 체계를 만들어 다른 나라에도 퍼뜨리기 시작했지만, 1920년대 양자 역학의 발견은 완벽한 측정에 대한 꿈을 영원히 깨 버렸다.", "order": ["그럼에도 공학자와 과학자 사이에서는 완벽하게 측정하려는 정신이 계속되었고, 비즈니스 세계에서는 수학과 통계학의 영향으로 오히려 확대되었다.", "그러나 오늘날 많은 새로운 상황에서는 부정확성을 허용하는 것이 단점이 아니라 긍정적인 특성이 될 수 있다.", "허용 가능한 오류의 기준을 완화하는 대가로 훨씬 더 많은 데이터를 얻을 수 있고, 때로는 더 많은 것이 더 좋은 것보다 더 훌륭하다."], "clue": ["\"그럼에도\"로 앞의 꿈이 깨진 일과 반대로 정신이 이어졌음을 말함", "\"그러나 오늘날\"로 지난 수십 년의 경향과 반대되는 내용을 제시함", "\"오류의 기준을 완화\"가 앞의 \"부정확성을 허용\"을 이어 받아 그 대가를 설명함"], "why": ["완벽한 측정의 꿈과 좌절 -> 그래도 이어진 추구 -> 부정확성의 장점 -> 더 많은 데이터 순서임."], "cards": ["그러나 오늘날 많은 새로운 상황에서는 부정확성을 허용하는 것이 단점이 아니라 긍정적인 특성이 될 수 있다.", "그럼에도 공학자와 과학자 사이에서는 완벽하게 측정하려는 정신이 계속되었고, 비즈니스 세계에서는 수학과 통계학의 영향으로 오히려 확대되었다.", "허용 가능한 오류의 기준을 완화하는 대가로 훨씬 더 많은 데이터를 얻을 수 있고, 때로는 더 많은 것이 더 좋은 것보다 더 훌륭하다."], "answer": [1, 0, 2]}, "sents": [{"n": 1, "en": "By the nineteenth century, France had developed a system of precisely defined units of measurement to capture space, time, and more, and had begun to get other nations to adopt the same standards.", "ko": "19세기까지, 프랑스는 공간, 시간, 그리고 더 많은 것을 포착하기 위해 정밀하게 규정된 측정 단위의 체계를 개발했고, 다른 국가들이 동일한 기준을 채택하도록 만들기 시작했었다."}, {"n": 2, "en": "Just half a century later, in the 1920s, the discoveries of quantum mechanics forever destroyed the dream of comprehensive and perfect measurement.", "ko": "불과 반세기 후, 1920년대에, 양자 역학의 발견은 포괄적이고 완벽한 측정에 대한 꿈을 영원히 깨 버렸다."}, {"n": 3, "en": "And yet, outside a relatively small circle of physicists, the mindset of humankind\u2019s drive to flawlessly measure continued among engineers and scientists.", "ko": "그러나 비교적 소수 집단의 물리학자를 제외하고는 공학자와 과학자 사이에서 완벽하게 측정하려고 하는 인류의 추진 정신은 계속되었다."}, {"n": 4, "en": "In the world of business it even expanded, as the precision-oriented sciences of mathematics and statistics began to influence all areas of commerce.", "ko": "정확성을 지향하는 수학과 통계학이라는 과학이 상업의 모든 영역에 영향을 미치기 시작하면서 비즈니스의 세계에서 그것은 심지어 확장되었다."}, {"n": 5, "en": "However, contrary to the trend of the past several decades, in many new situations that are occurring today, allowing for imprecision \u2015 for messiness \u2015 may be a positive feature, not a shortcoming.", "ko": "그러나, 지난 수십 년간의 경향과 반대로, 오늘날 발생하는 많은 새로운 상황에서 부정확성, 즉, 번잡함을 허용하는 것은 단점이 아니라 긍정적인 특성이 될 수 있다."}, {"n": 6, "en": "As a tradeoff for relaxing the standards of allowable errors, one can get a hold of much more data.", "ko": "허용 가능한 오류의 기준을 완화하는 것에 대한 맞교환으로서, 사람은 훨씬 더 많은 데이터를 얻을 수 있다."}, {"n": 7, "en": "It isn\u2019t just that \u201cmore is better than some,\u201d but that, in fact, sometimes \u201cmore is greater than better.\u201d", "ko": "그것은 단순히 \u2018더 많은 것이 조금보다 더 나을\u2019 뿐만 아니라, 사실은 때때로 \u2018더 많은 것이 더 좋은 것보다 더 훌륭하기\u2019도 하다."}]}, {"id": "2311-40", "short": "23년 11월 40번", "group": "23년 11월", "num": 40, "topic_ko": "협력하는 사람이 받는 사회적 혜택", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "협력적인 사람은 사회적 혜택을 받으며, 이를 보이려면 기여자에게 반응할 기회를 줌"}, {"n": 2, "label": "실험 사례", "from": 3, "to": 4, "summary_ko": "기금 게임에서 더 많이 기부한 사람이 더 많은 돈에 대한 책임을 맡음"}, {"n": 3, "label": "확장과 대비", "from": 5, "to": 7, "summary_ko": "기여자는 파트너와 리더로 선호되고 신뢰받지만 비협조적인 사람은 비판과 벌을 받음"}], "gloss": [{"w": "cooperative", "m": "협력적인"}, {"w": "advantage", "m": "이점, 혜택", "form": "advantages", "note": "명사 advantage의 복수형"}, {"w": "demonstrate", "m": "증명하다, 보여 주다"}, {"w": "contributor", "m": "기여자", "form": "contributors", "note": "명사 contributor의 복수형"}, {"w": "contribute", "m": "기여하다, 기부하다"}, {"w": "fund", "m": "기금"}, {"w": "reputation", "m": "평판", "form": "reputations", "note": "명사 reputation의 복수형"}, {"w": "responsibility", "m": "책임"}, {"w": "participant", "m": "참가자", "form": "participants", "note": "명사 participant의 복수형"}, {"w": "perceive", "m": "인식하다", "form": "perceived", "note": "동사 perceive의 과거분사형(are perceived, 수동태)"}, {"w": "trustworthy", "m": "신뢰할 수 있는"}, {"w": "verbal", "m": "언어적인"}, {"w": "criticism", "m": "비판"}, {"w": "punishment", "m": "벌, 처벌"}], "qa": [{"chunk": 1, "q": "여러 실험실 연구가 보여 주는, 협력적인 사람들에 대한 내용은?", "opts": ["다른 사람들로부터 사회적 혜택을 받는 경향이 있다.", "다른 사람들에게서 언어적 비판을 받는 경향이 있다.", "다른 사람들보다 돈을 더 적게 기부하는 경향이 있다."], "ans": 0, "why": ["1번 문장에서 협력적인 사람들은 다른 사람들로부터 사회적 혜택을 받는 경향이 있다고 함.", "언어적 비판은 7번 문장에서 비협조적인 사람들이 받는 것임."], "ev_en": "Multiple laboratory studies show that cooperative people tend to receive social advantages from others.", "ev_ko": "여러 실험실 연구들은 협력적인 사람들이 다른 사람들로부터 사회적인 혜택들을 받는 경향이 있다는 것을 보여 준다."}, {"chunk": 2, "q": "Pat Barclay의 협동 게임에서 집단 기금에 더 많이 기부한 사람들은 어떻게 되었는가?", "opts": ["덜 기부한 사람들보다 더 적은 돈에 대한 책임이 주어졌다.", "덜 기부한 사람들보다 더 많은 돈에 대한 책임이 주어졌다.", "다른 참가자에게 돈을 줄 수 없게 되었다."], "ans": 1, "why": ["4번 문장에서 더 많이 기부한 사람들은 덜 기부한 사람들보다 더 많은 돈에 대한 책임이 주어졌다고 함.", "더 적은 돈에 대한 책임은 지문과 반대임.", "3번 문장에서 참가자들은 평판을 바탕으로 다른 참가자에게 돈을 줄 수 있었음."], "ev_en": "People who contributed more to the group fund were given responsibility for more money than people who contributed less.", "ev_ko": "집단 기금에 더 많이 기부한 사람들은 덜 기부한 사람들보다 더 많은 돈에 대한 책임이 주어졌다."}, {"chunk": 3, "q": "비협조적인 사람들이 받는 경향이 있는 것은?", "opts": ["리더로서의 선호", "장기적인 관계를 위한 높은 평가", "언어적인 비판이나 더 심한 벌"], "ans": 2, "why": ["7번 문장에서 비협조적인 사람들은 언어적인 비판이나 심지어 더 심한 벌을 받는 경향이 있다고 함.", "리더로서의 선호와 장기 관계를 위한 높은 평가는 6번 문장에서 집단에 기여하는 사람들이 받는 것임."], "ev_en": "Uncooperative people tend to receive verbal criticism or even more severe punishment.", "ev_ko": "비협조적인 사람들은 언어적인 비판이나 심지어 더 심한 벌을 받는 경향이 있다."}], "tf": [{"s": "협력적인 사람들은 다른 사람들로부터 사회적 혜택을 받는 경향이 있다.", "t": true, "why": ["1번 문장의 내용이므로 맞음."], "ev_en": "Multiple laboratory studies show that cooperative people tend to receive social advantages from others.", "ev_ko": "여러 실험실 연구들은 협력적인 사람들이 다른 사람들로부터 사회적인 혜택들을 받는 경향이 있다는 것을 보여 준다."}, {"s": "Barclay의 실험에서 참가자들은 평판과 상관없이 다른 참가자에게 돈을 주었다.", "t": false, "why": ["틀린 부분은 \"평판과 상관없이\"임.", "3번 문장에 따르면 참가자들은 평판을 바탕으로 다른 참가자들에게 돈을 줄 수 있었음."], "ev_en": "For example, Pat Barclay, a professor at the University of Guelph, had participants play a cooperative game where people could contribute money toward a group fund which helped all group members, and then allowed participants to give money to other participants based on their reputations.", "ev_ko": "예를 들어, Guelph 대학교의 교수인, Pat Barclay는 참가자들로 하여금 모든 집단 구성원들을 도와주는 집단 기금에 사람들이 돈을 기부할 수 있는 협동 게임을 하도록 한 다음, 참가자들이 그들의 평판을 바탕으로 다른 참가자들에게 돈을 줄 수 있도록 허락했다."}, {"s": "집단 기금에 더 적게 기부한 사람들이 더 많은 돈에 대한 책임을 받았다.", "t": false, "why": ["틀린 부분은 \"더 적게\"임.", "4번 문장에 따르면 더 많이 기부한 사람들이 더 많은 돈에 대한 책임을 받음."], "ev_en": "People who contributed more to the group fund were given responsibility for more money than people who contributed less.", "ev_ko": "집단 기금에 더 많이 기부한 사람들은 덜 기부한 사람들보다 더 많은 돈에 대한 책임이 주어졌다."}, {"s": "집단에 기여하는 사람들은 상호 작용 파트너로 더 자주 선택된다.", "t": true, "why": ["6번 문장의 내용이므로 맞음."], "ev_en": "People who contribute toward their groups are also chosen more often as interaction partners, preferred as leaders, rated as more desirable partners for long-term relationships, and are perceived to be trustworthy and have high social status.", "ev_ko": "또한 그들의 집단에 기여하는 사람들은 상호 작용 파트너로서 더 자주 선택되고, 리더로서 선호되며, 장기적인 관계를 위한 더 바람직한 파트너들로서 평가되고, 신뢰할 수 있고 사회적 지위가 높은 것으로 인식된다."}, {"s": "비협조적인 사람들은 언어적인 비판이나 더 심한 벌을 받는 경향이 있다.", "t": true, "why": ["7번 문장의 내용이므로 맞음."], "ev_en": "Uncooperative people tend to receive verbal criticism or even more severe punishment.", "ev_ko": "비협조적인 사람들은 언어적인 비판이나 심지어 더 심한 벌을 받는 경향이 있다."}], "flow": {"fixed": "여러 실험실 연구에 따르면 협력적인 사람들은 다른 사람들로부터 사회적 혜택을 받는 경향이 있다.", "order": ["이를 보이는 한 가지 방법은 사람들이 기여자에게 긍정적이거나 부정적으로 행동할 기회를 주는 것으로, 한 협동 게임 실험에서는 기금에 더 많이 기부한 사람이 더 많은 돈에 대한 책임을 맡았다.", "다른 연구자들도 비슷한 결과를 발견했는데, 집단에 기여하는 사람은 파트너로 더 자주 선택되고 리더로 선호되며 신뢰할 만하고 지위가 높다고 인식되었다.", "반면 비협조적인 사람들은 언어적인 비판이나 더 심한 벌을 받는 경향이 있다."], "clue": ["\"이를 보이는 한 가지 방법\"에서 \"이\"가 앞의 사회적 혜택을 가리킴", "\"비슷한 결과\"는 앞의 실험 결과가 먼저 나와야 성립함", "\"반면\"으로 앞의 협력하는 사람과 대비되는 비협조적인 사람을 제시함"], "why": ["주장 -> 실험으로 증명 -> 다른 연구의 비슷한 결과 -> 비협조적인 사람과의 대비 순서임."], "cards": ["반면 비협조적인 사람들은 언어적인 비판이나 더 심한 벌을 받는 경향이 있다.", "이를 보이는 한 가지 방법은 사람들이 기여자에게 긍정적이거나 부정적으로 행동할 기회를 주는 것으로, 한 협동 게임 실험에서는 기금에 더 많이 기부한 사람이 더 많은 돈에 대한 책임을 맡았다.", "다른 연구자들도 비슷한 결과를 발견했는데, 집단에 기여하는 사람은 파트너로 더 자주 선택되고 리더로 선호되며 신뢰할 만하고 지위가 높다고 인식되었다."], "answer": [1, 2, 0]}, "sents": [{"n": 1, "en": "Multiple laboratory studies show that cooperative people tend to receive social advantages from others.", "ko": "여러 실험실 연구들은 협력적인 사람들이 다른 사람들로부터 사회적인 혜택들을 받는 경향이 있다는 것을 보여 준다."}, {"n": 2, "en": "One way to demonstrate this is to give people the opportunity to act positively or negatively toward contributors.", "ko": "이것을 증명하는 한 가지 방법은 사람들에게 기여자들을 향해 긍정적이거나 부정적으로 행동할 기회를 주는 것이다."}, {"n": 3, "en": "For example, Pat Barclay, a professor at the University of Guelph, had participants play a cooperative game where people could contribute money toward a group fund which helped all group members, and then allowed participants to give money to other participants based on their reputations.", "ko": "예를 들어, Guelph 대학교의 교수인, Pat Barclay는 참가자들로 하여금 모든 집단 구성원들을 도와주는 집단 기금에 사람들이 돈을 기부할 수 있는 협동 게임을 하도록 한 다음, 참가자들이 그들의 평판을 바탕으로 다른 참가자들에게 돈을 줄 수 있도록 허락했다."}, {"n": 4, "en": "People who contributed more to the group fund were given responsibility for more money than people who contributed less.", "ko": "집단 기금에 더 많이 기부한 사람들은 덜 기부한 사람들보다 더 많은 돈에 대한 책임이 주어졌다."}, {"n": 5, "en": "Similar results have been found by other researchers.", "ko": "유사한 결과들이 다른 연구자들에 의해 발견되었다."}, {"n": 6, "en": "People who contribute toward their groups are also chosen more often as interaction partners, preferred as leaders, rated as more desirable partners for long-term relationships, and are perceived to be trustworthy and have high social status.", "ko": "또한 그들의 집단에 기여하는 사람들은 상호 작용 파트너로서 더 자주 선택되고, 리더로서 선호되며, 장기적인 관계를 위한 더 바람직한 파트너들로서 평가되고, 신뢰할 수 있고 사회적 지위가 높은 것으로 인식된다."}, {"n": 7, "en": "Uncooperative people tend to receive verbal criticism or even more severe punishment.", "ko": "비협조적인 사람들은 언어적인 비판이나 심지어 더 심한 벌을 받는 경향이 있다."}]}, {"id": "2311-41", "short": "23년 11월 41번", "group": "23년 11월", "num": 41, "topic_ko": "공연자와 청중 사이의 거리를 줄이는 방법", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "서양 음악 공연은 공연자와 청중을 구분하고 청중은 공연자에 대한 접근 기회를 가치 있게 여김"}, {"n": 2, "label": "방법 1과 2", "from": 4, "to": 6, "summary_ko": "청중 참여를 넣으면 호응이 크고, 불편한 공연자는 공연자 관점을 보여 줌으로써 이어질 수 있음"}, {"n": 3, "label": "프로그램 해설", "from": 7, "to": 11, "summary_ko": "공연자 자신과 곡 선택 이유를 알려 주면 청중이 더 가깝게 느껴 경험이 향상됨"}], "gloss": [{"w": "distinction", "m": "구분, 차이"}, {"w": "passive", "m": "수동적인"}, {"w": "reinforce", "m": "강화하다"}, {"w": "separation", "m": "분리"}, {"w": "access", "m": "접근"}, {"w": "afford", "m": "제공하다", "form": "affords", "note": "동사 afford의 3인칭 단수 현재형(주어 \"access\"가 단수)"}, {"w": "incorporate", "m": "포함시키다", "form": "incorporating", "note": "동사 incorporate의 동명사형(by 뒤에 쓰임)"}, {"w": "approval", "m": "호응, 승인"}, {"w": "engagement", "m": "참여, 몰입"}, {"w": "boost", "m": "높이다, 북돋우다"}, {"w": "glimpse", "m": "흘끗 봄, 엿봄"}, {"w": "program notes", "m": "프로그램 해설(공연 안내서의 설명 글)"}, {"w": "insight", "m": "통찰력"}, {"w": "enhance", "m": "향상시키다"}], "qa": [{"chunk": 1, "q": "서양 사회의 많은 음악 공연에서 청중이 맡는 역할은?", "opts": ["공연자와 같은 행위자 역할", "분명히 수동적인 역할", "공연 장소를 정하는 역할"], "ans": 1, "why": ["1번 문장에서 공연자는 \"행위자들\"이고 청중 속 사람들은 분명히 수동적인 역할을 맡는다고 함.", "청중이 행위자 역할을 한다거나 장소를 정한다는 내용은 없음."], "ev_en": "In Western society, many music performance settings make a clear distinction between performers and audience members: the performers are the \u201cdoers\u201d and those in the audience take a decidedly passive role.", "ev_ko": "서양 사회에서, 많은 음악 공연 상황은 공연자와 청중 사이에 명확한 구분을 만든다. 공연자들은 \u2018행위자들\u2019이고, 청중 속 사람들은 분명히 수동적인 역할을 맡는다."}, {"chunk": 2, "q": "청중 참여를 이끄는 것이 불편한 공연자가 청중과 이어질 수 있는 방법은?", "opts": ["무대와 청중석 사이의 물리적 분리를 더 늘린다.", "공연자 관점을 특별히 엿볼 수 있게 해 준다.", "청중에게 함께 노래 부르기를 이끌게 한다."], "ans": 1, "why": ["6번 문장에서 불편한 공연자도 공연자 관점을 특별히 흘끗 보여 줌으로써 이어질 수 있다고 함.", "물리적 분리는 2번 문장에서 구분을 강화하는 요소이므로 이어지는 방법이 아님.", "함께 노래 부르기는 5번 문장의 청중 참여 활동이며, 이것이 불편한 경우를 말하는 것임."], "ev_en": "Performers who are uncomfortable leading audience participation can still connect with the audience simply by giving a special glimpse of the performer perspective.", "ev_ko": "청중 참여를 이끄는 것에 불편함을 느끼는 공연자들은 단순히 그 공연자 관점을 특별히 흘끗 보여줌으로써 청중과 여전히 이어질 수 있다."}, {"chunk": 3, "q": "청중에게 더 흥미로울 수도 있다고 한 프로그램 해설의 내용은?", "opts": ["연주되는 작품에 관한 배경 정보", "역사적으로 중요한 작곡가들의 전기 정보", "무대 위 공연자들에 관한 배경 정보와 곡 선택 이유"], "ans": 2, "why": ["9번 문장에서 청중에게 더 흥미로울 수 있는 것은 무대 위 공연자들에 관한 배경 정보라고 함.", "여기에는 공연자들이 그 음악을 왜 선택했는지 설명이 포함됨.", "작품의 배경과 작곡가의 전기는 8번 문장에서 전형적으로 들어가는 내용으로 소개됨."], "ev_en": "What may be of more interest to audience members is background information about the very performers who are onstage, including an explanation of why they have chosen the music they are presenting.", "ev_ko": "청중들에게 더 흥미로울 수도 있는 것은 공연자들이 그들이 선보이고 있는 음악을 왜 선택했는지에 대한 설명을 포함한, 무대 위에 있는 바로 그 공연자들에 관한 배경 정보이다."}], "tf": [{"s": "공연 공간 그 자체가 무대와 청중석의 물리적 분리로 구분을 더 강화할 수 있다.", "t": true, "why": ["2번 문장의 내용이므로 맞음."], "ev_en": "The performance space itself may further reinforce the distinction with a physical separation between the stage and audience seating.", "ev_ko": "공연 공간 그 자체가 무대와 청중석 사이의 물리적 분리로 구분을 더 강화할 수 있다."}, {"s": "청중은 공연자에게 특별히 접근할 기회에 큰 가치를 두지 않는 것처럼 보인다.", "t": false, "why": ["틀린 부분은 \"큰 가치를 두지 않는\"임.", "3번 문장에 따르면 청중은 그런 기회에 크게 가치를 부여하는 것처럼 보임."], "ev_en": "Perhaps because this distinction is so common, audiences seem to greatly value opportunities to have special \u201caccess\u201d to performers that affords understanding about performers\u2019 style of music.", "ev_ko": "아마도 이러한 구분이 너무 흔하기 때문에, 청중들은 공연자의 음악 스타일에 대한 이해를 제공하는 공연자에 대한 특별한 \u2018접근\u2019을 할 기회들에 크게 가치를 부여하는 것처럼 보인다."}, {"s": "일부 음악가는 콘서트에 청중 참여를 정기적으로 포함해 큰 호응을 받아 왔다.", "t": true, "why": ["4번 문장의 내용이므로 맞음."], "ev_en": "Some performing musicians have won great approval by regularly incorporating \u201caudience participation\u201d into their concerts.", "ev_ko": "일부 공연 음악가는 정기적으로 그들의 콘서트에 \u2018청중 참여\u2019를 포함함으로써 큰 호응을 받아 왔다."}, {"s": "클래식 음악에서 청중에게 프로그램 해설을 제공하는 일은 드물다.", "t": false, "why": ["틀린 부분은 \"드물다\"임.", "7번 문장에 따르면 클래식 음악에서 프로그램 해설을 제공하는 것은 상당히 흔함."], "ev_en": "It is quite common in classical music to provide audiences with program notes.", "ev_ko": "클래식 음악에서는 청중에게 프로그램 해설을 제공하는 것이 상당히 흔하다."}, {"s": "공연자에 관한 정보는 청중이 무대 위 음악가에게 비유적이고 감정적으로 더 가깝게 느끼게 만들 수 있다.", "t": true, "why": ["10번 문장의 내용이므로 맞음."], "ev_en": "Such insight can make audience members feel closer to the musicians onstage, both metaphorically and emotionally.", "ev_ko": "그러한 통찰력은 청중들이 무대 위에 있는 음악가들에게 비유적이고 감정적으로 더 가까이 느끼게 만들 수 있다."}], "flow": {"fixed": "서양 사회의 많은 공연은 공연자와 청중을 뚜렷이 구분하고 청중에게 수동적인 역할을 맡기며, 그래서 청중은 공연자에게 특별히 접근할 기회를 크게 가치 있게 여기는 듯하다.", "order": ["이 구분을 좁히는 한 방법으로, 일부 음악가는 함께 노래 부르기나 박수 리듬 가르치기 같은 청중 참여를 넣어 모두의 참여와 즐거움을 높일 수 있었다.", "청중 참여를 이끄는 것이 불편한 공연자는 대신 공연자의 관점을 살짝 보여 주는 것만으로도 청중과 여전히 이어질 수 있다.", "예를 들어 프로그램 해설에 공연자 자신과 곡을 고른 이유를 담으면, 청중이 음악가를 더 가깝게 느껴 표현적이고 소통적인 경험이 향상될 가능성이 크다."], "clue": ["\"이 구분을 좁히는 한 방법\"이 앞의 구분과 접근 이야기를 이어 받음", "\"대신\"과 \"불편한\"이 앞의 청중 참여 방법을 받아 다른 길을 제시함", "\"예를 들어\"로 앞의 공연자 관점 보여 주기를 프로그램 해설 사례로 구체화함"], "why": ["공연자와 청중의 구분 -> 청중 참여 -> 참여가 불편하면 관점 보여 주기 -> 프로그램 해설 예 순서임."], "cards": ["이 구분을 좁히는 한 방법으로, 일부 음악가는 함께 노래 부르기나 박수 리듬 가르치기 같은 청중 참여를 넣어 모두의 참여와 즐거움을 높일 수 있었다.", "예를 들어 프로그램 해설에 공연자 자신과 곡을 고른 이유를 담으면, 청중이 음악가를 더 가깝게 느껴 표현적이고 소통적인 경험이 향상될 가능성이 크다.", "청중 참여를 이끄는 것이 불편한 공연자는 대신 공연자의 관점을 살짝 보여 주는 것만으로도 청중과 여전히 이어질 수 있다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "In Western society, many music performance settings make a clear distinction between performers and audience members: the performers are the \u201cdoers\u201d and those in the audience take a decidedly passive role.", "ko": "서양 사회에서, 많은 음악 공연 상황은 공연자와 청중 사이에 명확한 구분을 만든다. 공연자들은 \u2018행위자들\u2019이고, 청중 속 사람들은 분명히 수동적인 역할을 맡는다."}, {"n": 2, "en": "The performance space itself may further reinforce the distinction with a physical separation between the stage and audience seating.", "ko": "공연 공간 그 자체가 무대와 청중석 사이의 물리적 분리로 구분을 더 강화할 수 있다."}, {"n": 3, "en": "Perhaps because this distinction is so common, audiences seem to greatly value opportunities to have special \u201caccess\u201d to performers that affords understanding about performers\u2019 style of music.", "ko": "아마도 이러한 구분이 너무 흔하기 때문에, 청중들은 공연자의 음악 스타일에 대한 이해를 제공하는 공연자에 대한 특별한 \u2018접근\u2019을 할 기회들에 크게 가치를 부여하는 것처럼 보인다."}, {"n": 4, "en": "Some performing musicians have won great approval by regularly incorporating \u201caudience participation\u201d into their concerts.", "ko": "일부 공연 음악가는 정기적으로 그들의 콘서트에 \u2018청중 참여\u2019를 포함함으로써 큰 호응을 받아 왔다."}, {"n": 5, "en": "Whether by leading a sing-along activity or teaching a rhythm to be clapped at certain points, including audience members in the music making can boost the level of engagement and enjoyment for all involved.", "ko": "함께 노래 부르기 활동을 하든지 지정된 지점에서 박수를 치도록 리듬을 가르치든지, 음악을 만드는 데 있어서 청중 구성원을 포함하는 것은 모든 참여자의 참여와 즐거움의 수준을 높일 수 있다."}, {"n": 6, "en": "Performers who are uncomfortable leading audience participation can still connect with the audience simply by giving a special glimpse of the performer perspective.", "ko": "청중 참여를 이끄는 것에 불편함을 느끼는 공연자들은 단순히 그 공연자 관점을 특별히 흘끗 보여줌으로써 청중과 여전히 이어질 수 있다."}, {"n": 7, "en": "It is quite common in classical music to provide audiences with program notes.", "ko": "클래식 음악에서는 청중에게 프로그램 해설을 제공하는 것이 상당히 흔하다."}, {"n": 8, "en": "Typically, this text in a program gives background information about pieces of music being performed and perhaps biographical information about historically significant composers.", "ko": "전형적으로, 이러한 프로그램의 텍스트는 연주되는 음악 작품에 대한 배경 정보와 아마도 역사적으로 중요한 작곡가들에 대한 전기(\u50b3\u8a18) 정보를 제공한다."}, {"n": 9, "en": "What may be of more interest to audience members is background information about the very performers who are onstage, including an explanation of why they have chosen the music they are presenting.", "ko": "청중들에게 더 흥미로울 수도 있는 것은 공연자들이 그들이 선보이고 있는 음악을 왜 선택했는지에 대한 설명을 포함한, 무대 위에 있는 바로 그 공연자들에 관한 배경 정보이다."}, {"n": 10, "en": "Such insight can make audience members feel closer to the musicians onstage, both metaphorically and emotionally.", "ko": "그러한 통찰력은 청중들이 무대 위에 있는 음악가들에게 비유적이고 감정적으로 더 가까이 느끼게 만들 수 있다."}, {"n": 11, "en": "This connection will likely enhance the expressive and communicative experience.", "ko": "이러한 연결은 표현적이고 소통적인 경험을 아마 향상시킬 것이다."}]}, {"id": "2410-22", "short": "24년 10월 22번", "group": "24년 10월", "num": 22, "topic_ko": "별의 질량 측정이 이론에 바탕을 둔 계산이라는 점", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "볼링공의 질량은 저울로 쉽게 재지만, 먼 별의 질량은 훨씬 복잡함"}, {"n": 2, "label": "전개", "from": 4, "to": 5, "summary_ko": "별의 질량 측정에는 이론이 쓰이며, 쌍성은 질량 중심\u00b7거리\u00b7주기\u00b7케플러 법칙으로 계산함"}, {"n": 3, "label": "결론", "from": 6, "to": 7, "summary_ko": "다른 수치를 측정해 계산하므로, 측정은 정립된 이론을 바탕으로 한 결정임"}], "gloss": [{"w": "determine", "m": "결정하다, 알아내다"}, {"w": "balance", "m": "저울, 균형"}, {"w": "complicated", "m": "복잡한"}, {"w": "involve", "m": "포함하다", "form": "involves", "note": "동사 involve의 3인칭 단수 현재형(주어 measuring이 단수)"}, {"w": "binary star", "m": "쌍성(서로 도는 두 별)"}, {"w": "center of mass", "m": "질량 중심"}, {"w": "period", "m": "주기"}, {"w": "calculate", "m": "계산하다"}, {"w": "quantity", "m": "양, 수치", "form": "quantities", "note": "명사 quantity의 복수형"}, {"w": "equation", "m": "방정식", "form": "equations", "note": "명사 equation의 복수형"}, {"w": "unmediated", "m": "중재되지 않은, 직접적인"}, {"w": "property", "m": "특성", "form": "properties", "note": "명사 property의 복수형"}, {"w": "magnitude", "m": "크기", "form": "magnitudes", "note": "명사 magnitude의 복수형"}, {"w": "estimation", "m": "추정, 추산"}, {"w": "determination", "m": "결정, (값을) 구하는 일"}], "qa": [{"chunk": 1, "q": "볼링공의 질량을 재는 방법으로 글쓴이가 든 것은?", "opts": ["여러 이론과 방정식을 이용해 계산한다.", "질량 중심을 구해 거리를 잰다.", "저울에 올려 이미 알고 있는 질량과 비교한다."], "ans": 2, "why": ["1번 문장에서 볼링공을 저울에 올려 알고 있는 질량(금속 큐브)과 비교한다고 함.", "이론\u00b7방정식 계산은 먼 별의 질량을 구할 때의 방법임(4~5번 문장).", "질량 중심은 쌍성에 쓰이는 개념임."], "ev_en": "To determine the mass of my bowling ball, I might put it onto a balance and compare it with a known mass, such as a number of metal cubes each weighing 1, 10, or 100 grams.", "ev_ko": "내 볼링공의 질량을 측정하기 위해, 나는 그것을 저울에 올려놓고 각각 1g, 10g, 또는 100g이 나가는 여러 개의 금속 큐브 같은 이미 알고 있는 질량과 그것을 비교할 수 있다."}, {"chunk": 2, "q": "쌍성의 질량을 계산하기 위해 가장 먼저 하는 일은?", "opts": ["두 별 사이의 질량 중심을 구한다.", "케플러 제3 법칙의 값을 대입한다.", "별을 저울에 올려 알고 있는 질량과 비교한다."], "ans": 0, "why": ["5번 문장에서 먼저 두 별 사이의 질량 중심을 구한다고 함.", "그 다음에 그 중심으로부터의 거리를 구하고, 주기와 케플러 제3 법칙과 함께 질량을 계산함.", "케플러 제3 법칙은 마지막 계산 단계에 쓰이므로 먼저 하는 일이 아님.", "별을 저울에 올리는 것은 지문에 없는 내용임."], "ev_en": "If we want to measure the mass of a binary star, we first determine a center of mass between the two stars, then their distance from that center which we can then use, together with a value for the period and a certain instance of Kepler\u2019s Third Law, to calculate the mass.", "ev_ko": "우리가 쌍성의 질량을 측정하기를 원한다면, 우리는 먼저 두 별 사이의 질량 중심을 구하고, 그 다음 그 중심으로부터 떨어진 그것들의 거리를 구하는데, 우리는 그 다음에 그것을 공전 주기의 값 및 케플러 제3 법칙의 특정한 사례와 함께 사용하여 질량을 계산할 수 있다."}, {"chunk": 3, "q": "글쓴이가 말하는 '측정'의 성격은?", "opts": ["독립적으로 존재하는 특성을 단순하게 추정하는 일이다.", "이미 정립된 여러 이론을 바탕으로 특정 크기를 결정하는 일이다.", "이론과 상관없이 직접 눈으로 비교하는 일이다."], "ans": 1, "why": ["7번 문장에서 측정은 단순하고 중재되지 않은 추정이 아니라, 정립된 이론들을 바탕으로 특정 크기를 결정하는 것이라고 함. (determination은 공식 해석에서 \u2018계산\u2019으로 옮겼으며, 여기서는 \u2018결정\u2019과 같은 뜻으로 봄)", "첫 번째 보기는 7번 문장이 부정한 내용 그대로임.", "이론과 상관없다는 말은 지문과 반대임."], "ev_en": "Measurement is not a simple and unmediated estimation of independently existing properties, but a determination of certain magnitudes before the background of a number of accepted theories.", "ev_ko": "측정은 독립적으로 존재하는 특성들의 단순하고 중재되지 않은 추정이 아니라, 이미 정립된 여러 이론들을 바탕으로 특정 크기들을 계산하는 것이다."}], "tf": [{"s": "볼링공의 질량은 저울 위에서 이미 알고 있는 질량과 비교해 잴 수 있다.", "t": true, "why": ["1번 문장의 내용임."], "ev_en": "To determine the mass of my bowling ball, I might put it onto a balance and compare it with a known mass, such as a number of metal cubes each weighing 1, 10, or 100 grams.", "ev_ko": "내 볼링공의 질량을 측정하기 위해, 나는 그것을 저울에 올려놓고 각각 1g, 10g, 또는 100g이 나가는 여러 개의 금속 큐브 같은 이미 알고 있는 질량과 그것을 비교할 수 있다."}, {"s": "먼 별의 질량을 알고 싶을 때의 상황은 볼링공의 질량을 잴 때보다 훨씬 단순하다.", "t": false, "why": ["틀린 부분은 '훨씬 단순하다'임.", "먼 별의 질량을 알고 싶으면 상황이 훨씬 더 복잡해짐."], "ev_en": "Things get much more complicated if I want to know the mass of a distant star.", "ev_ko": "만약 내가 먼 별의 질량을 알고 싶다면 상황은 훨씬 더 복잡해진다."}, {"s": "쌍성의 질량은 질량 중심으로부터의 거리, 주기, 케플러 제3 법칙을 함께 사용해 계산한다.", "t": true, "why": ["5번 문장의 내용임."], "ev_en": "If we want to measure the mass of a binary star, we first determine a center of mass between the two stars, then their distance from that center which we can then use, together with a value for the period and a certain instance of Kepler\u2019s Third Law, to calculate the mass.", "ev_ko": "우리가 쌍성의 질량을 측정하기를 원한다면, 우리는 먼저 두 별 사이의 질량 중심을 구하고, 그 다음 그 중심으로부터 떨어진 그것들의 거리를 구하는데, 우리는 그 다음에 그것을 공전 주기의 값 및 케플러 제3 법칙의 특정한 사례와 함께 사용하여 질량을 계산할 수 있다."}, {"s": "별의 질량은 다른 수치를 쓰지 않고 질량 자체를 직접 재어 얻는다.", "t": false, "why": ["틀린 부분은 '직접 재어 얻는다'임.", "별의 질량을 '측정'하려면 다른 수치들을 측정하고, 그 값을 방정식과 함께 써서 계산함."], "ev_en": "In other words, in order to \u201cmeasure\u201d the star mass, we measure other quantities and use those values, together with certain equations, to calculate the mass.", "ev_ko": "다시 말해서, 별의 질량을 \u2018측정\u2019하기 위해서 우리는 다른 수치들을 측정하고 그 값들을 특정 방정식들과 함께 사용하여 질량을 계산한다."}, {"s": "측정은 이미 정립된 이론과 관계없이 이루어지는 독립적이고 단순한 추정이다.", "t": false, "why": ["지문과 반대임.", "측정은 단순하고 중재되지 않은 추정이 아니라, 정립된 여러 이론을 바탕으로 한 결정임."], "ev_en": "Measurement is not a simple and unmediated estimation of independently existing properties, but a determination of certain magnitudes before the background of a number of accepted theories.", "ev_ko": "측정은 독립적으로 존재하는 특성들의 단순하고 중재되지 않은 추정이 아니라, 이미 정립된 여러 이론들을 바탕으로 특정 크기들을 계산하는 것이다."}], "flow": {"fixed": "볼링공의 질량은 저울 위에서 이미 알고 있는 질량과 비교하면 쉽게 알 수 있지만, 먼 별의 질량을 알고 싶다면 상황이 훨씬 더 복잡해진다.", "order": ["별의 질량을 측정하는 데에는 다양한 이론이 관련되는데, 예를 들어 쌍성이라면 먼저 질량 중심을 구하고 그 중심으로부터의 거리를 구해 주기 및 케플러 제3 법칙과 함께 질량을 계산한다.", "다시 말해 별의 질량을 '측정'하려면 질량 자체가 아니라 다른 수치들을 측정하고, 그 값들을 방정식과 함께 사용해 질량을 계산하는 것이다.", "결국 측정은 단순한 추정이 아니라 이미 정립된 여러 이론을 바탕으로 특정 크기를 결정하는 일이다."], "clue": ["'예를 들어'로 앞의 복잡함을 쌍성 사례로 구체화함", "'다시 말해'로 앞의 사례를 한 문장으로 바꿔 말함", "'결국'으로 앞의 내용을 받아 결론을 내림"], "why": ["쉬운 질량 측정 -> 별은 복잡함 -> 쌍성 계산 사례 -> 다른 수치를 재어 계산함 -> 측정은 이론 바탕의 결정임"], "cards": ["결국 측정은 단순한 추정이 아니라 이미 정립된 여러 이론을 바탕으로 특정 크기를 결정하는 일이다.", "다시 말해 별의 질량을 '측정'하려면 질량 자체가 아니라 다른 수치들을 측정하고, 그 값들을 방정식과 함께 사용해 질량을 계산하는 것이다.", "별의 질량을 측정하는 데에는 다양한 이론이 관련되는데, 예를 들어 쌍성이라면 먼저 질량 중심을 구하고 그 중심으로부터의 거리를 구해 주기 및 케플러 제3 법칙과 함께 질량을 계산한다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "To determine the mass of my bowling ball, I might put it onto a balance and compare it with a known mass, such as a number of metal cubes each weighing 1, 10, or 100 grams.", "ko": "내 볼링공의 질량을 측정하기 위해, 나는 그것을 저울에 올려놓고 각각 1g, 10g, 또는 100g이 나가는 여러 개의 금속 큐브 같은 이미 알고 있는 질량과 그것을 비교할 수 있다."}, {"n": 2, "en": "Things get much more complicated if I want to know the mass of a distant star.", "ko": "만약 내가 먼 별의 질량을 알고 싶다면 상황은 훨씬 더 복잡해진다."}, {"n": 3, "en": "How do I measure it?", "ko": "나는 어떻게 그것을 측정할까?"}, {"n": 4, "en": "We can roughly say that measuring the mass of a star involves various theories.", "ko": "우리는 별의 질량을 측정하는 것은 다양한 이론을 포함한다고 대략적으로 말할 수 있다."}, {"n": 5, "en": "If we want to measure the mass of a binary star, we first determine a center of mass between the two stars, then their distance from that center which we can then use, together with a value for the period and a certain instance of Kepler\u2019s Third Law, to calculate the mass.", "ko": "우리가 쌍성의 질량을 측정하기를 원한다면, 우리는 먼저 두 별 사이의 질량 중심을 구하고, 그 다음 그 중심으로부터 떨어진 그것들의 거리를 구하는데, 우리는 그 다음에 그것을 공전 주기의 값 및 케플러 제3 법칙의 특정한 사례와 함께 사용하여 질량을 계산할 수 있다."}, {"n": 6, "en": "In other words, in order to \u201cmeasure\u201d the star mass, we measure other quantities and use those values, together with certain equations, to calculate the mass.", "ko": "다시 말해서, 별의 질량을 \u2018측정\u2019하기 위해서 우리는 다른 수치들을 측정하고 그 값들을 특정 방정식들과 함께 사용하여 질량을 계산한다."}, {"n": 7, "en": "Measurement is not a simple and unmediated estimation of independently existing properties, but a determination of certain magnitudes before the background of a number of accepted theories.", "ko": "측정은 독립적으로 존재하는 특성들의 단순하고 중재되지 않은 추정이 아니라, 이미 정립된 여러 이론들을 바탕으로 특정 크기들을 계산하는 것이다."}]}, {"id": "2410-23", "short": "24년 10월 23번", "group": "24년 10월", "num": 23, "topic_ko": "고통을 피하려는 시도가 오히려 비참함을 키우고, 고통을 허용하면 균형이 돌아온다는 점", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "고통과 쾌락은 뇌의 같은 영역에서 처리되고, 몸은 항상성을 추구함"}, {"n": 2, "label": "전개", "from": 4, "to": 5, "summary_ko": "쾌락과 고통은 동전의 양면처럼 저울 위 두 지점이라 한쪽이 오르면 다른 쪽이 내려감"}, {"n": 3, "label": "결론", "from": 6, "to": 9, "summary_ko": "Lembke에 따르면 고통을 피하려는 시도가 더 비참하게 하며, 고통을 허용해야 균형이 돌아옴"}], "gloss": [{"w": "neuroscience", "m": "뇌과학, 신경과학"}, {"w": "process", "m": "처리하다", "form": "processed", "note": "동사 process의 과거분사형(수동태 are processed)"}, {"w": "strive", "m": "노력하다, 추구하다"}, {"w": "homeostasis", "m": "항상성(몸의 균형을 유지하려는 성질)"}, {"w": "define", "m": "정의하다", "form": "defined", "note": "동사 define의 과거분사형(수동태 is defined)"}, {"w": "compensatory", "m": "보상하는"}, {"w": "mechanism", "m": "기제, 작동 방식", "form": "mechanisms", "note": "명사 mechanism의 복수형"}, {"w": "cushion", "m": "완화하다, 충격을 줄이다"}, {"w": "reliant", "m": "의존하는"}, {"w": "correspondingly", "m": "상응하여, 그에 맞춰"}, {"w": "miserable", "m": "비참한"}, {"w": "essential", "m": "필수적인"}, {"w": "component", "m": "구성 요소"}, {"w": "neutral", "m": "중립적인"}, {"w": "scale", "m": "저울, 눈금", "form": "scale", "note": "여기서는 \u2018규모\u2019가 아니라 \u2018저울\u2019"}], "qa": [{"chunk": 1, "q": "지문에서 말하는 항상성은?", "opts": ["고통과 쾌락을 구분하는 능력", "몸이 변동을 더 크게 만드는 작용", "몸의 기능들의 균형"], "ans": 2, "why": ["2번 문장에서 항상성은 몸의 기능들의 균형이라고 정의됨.", "3번 문장에 따르면 보상 기제는 변동(highs and lows)을 완화함.", "변동을 더 크게 만든다는 말은 지문과 반대임."], "ev_en": "Our bodies constantly strive for homeostasis, which is defined as the balance of bodily functions.", "ev_ko": "우리 몸은 끊임없이 항상성을 추구하는데, 그것은 몸의 기능들의 균형이라고 정의된다."}, {"chunk": 2, "q": "쾌락과 고통을 저울 위의 두 반대 지점으로 상상할 때, 한 지점이 올라가면 다른 지점은?", "opts": ["함께 올라간다.", "변화가 없다.", "상응하여 내려간다."], "ans": 2, "why": ["5번 문장에서 두 지점 중 한 지점이 올라가면 다른 지점은 상응하여 틀림없이 내려간다고 함.", "함께 올라간다거나 변화가 없다는 내용은 지문에 없음."], "ev_en": "If you imagine pleasure and pain as the two opposite points on a scale, you can easily understand that as one of the two points rises, the other must correspondingly fall.", "ev_ko": "만약에 여러분이 쾌락과 고통을 저울 위의 두 반대 지점으로 상상한다면, 여러분은 두 지점 중 한 지점이 올라가면 다른 한 지점이 상응하여 틀림없이 내려갈 것임을 쉽게 이해할 수 있을 것이다."}, {"chunk": 3, "q": "정신과 의사 Lembke에 따르면 비참함에서 벗어나려는 우리의 시도는 어떤 결과를 낳는가?", "opts": ["우리가 중립적인 상태를 유지하게 돕는다.", "쾌락을 더 오래 느끼게 한다.", "우리를 훨씬 더 비참하게 만든다."], "ans": 2, "why": ["8번 문장에서 비참함에서 벗어나려는 시도가 사실 우리를 훨씬 더 비참하게 만든다고 함.", "중립 상태를 유지하는 데 도움이 되는 것은 고통을 허용하는 쪽임(9번 문장).", "쾌락이 오래간다는 내용은 지문에 없음."], "ev_en": "She says that our attempts to escape being miserable are in fact making us even more miserable.", "ev_ko": "그녀는 우리가 비참함에서 벗어나려는 우리의 시도가 사실 우리를 훨씬 더 비참하게 만들고 있다고 말한다."}], "tf": [{"s": "고통과 쾌락은 뇌의 같은 영역에서 형성되고 처리된다.", "t": true, "why": ["1번 문장의 내용임."], "ev_en": "Based on discoveries in neuroscience, pain and pleasure are formed and processed in the same area of the brain.", "ev_ko": "뇌 과학의 발견들에 따르면, 고통과 쾌락은 뇌의 같은 영역에서 형성되고 처리된다."}, {"s": "몸의 보상 기제가 없어도 우리는 생존할 수 있다.", "t": false, "why": ["지문과 반대임.", "잠재적인 변동을 완화하는 효과적인 보상 기제가 없다면 우리는 생존할 수 없음."], "ev_en": "Without the body\u2019s effective compensatory mechanisms, which may cushion potential highs and lows, we would not be capable of surviving.", "ev_ko": "잠재적인 변동을 완화시킬 수 있는 몸의 효과적인 보상 기제가 없다면 우리는 생존할 수 없을 것이다."}, {"s": "쾌락과 고통은 서로 크게 의존하며 균형을 유지하는 것처럼 보인다.", "t": true, "why": ["4번 문장의 내용임.", "두 가지를 한 동전의 양면에 비유함."], "ev_en": "Pleasure and pain are like two sides of the same coin; they seem to work together and are heavily reliant on one another and keep balance.", "ev_ko": "쾌락과 고통은 동일한 동전의 두 면과 같아서 그들은 함께 작동하는 것 같으며 서로 상당히 의존하고 있고 균형을 유지한다."}, {"s": "Lembke는 비참함에서 벗어나려는 시도가 우리를 덜 비참하게 만든다고 말한다.", "t": false, "why": ["틀린 부분은 '덜 비참하게'임.", "Lembke는 그런 시도가 사실 우리를 훨씬 더 비참하게 만든다고 말함."], "ev_en": "She says that our attempts to escape being miserable are in fact making us even more miserable.", "ev_ko": "그녀는 우리가 비참함에서 벗어나려는 우리의 시도가 사실 우리를 훨씬 더 비참하게 만들고 있다고 말한다."}, {"s": "고통을 허용하면 우리의 내부 저울이 균형 상태로 다시 맞춰진다.", "t": true, "why": ["9번 문장의 내용임.", "고통은 중립 상태를 유지하는 능력의 필수 구성 요소이기 때문임."], "ev_en": "This is because pain is actually an essential component of our ability to maintain a neutral state, and allowing it will in turn reset our internal scale back to balance.", "ev_ko": "이는 고통이 실제로 중립적인 상태를 유지하기 위한 우리 능력의 필수적인 구성 요소이기 때문이고, 그것을 허용하는 것은 결과적으로 우리의 내부 저울을 균형 상태로 다시 맞출 것이다."}], "flow": {"fixed": "뇌 과학에 따르면 고통과 쾌락은 뇌의 같은 영역에서 처리되고, 우리 몸은 몸의 기능들의 균형인 항상성을 끊임없이 추구하며 보상 기제로 변동을 완화한다.", "order": ["이런 점에서 쾌락과 고통은 한 동전의 양면처럼 서로 의존하며 균형을 유지하는데, 저울 위에서 한쪽이 올라가면 다른 쪽은 상응하여 내려간다.", "그런데 정신과 의사 Anna Lembke는 '고통 없이는 얻는 것도 없다'는 말에 일리가 있을 수 있다며, 비참함에서 벗어나려는 시도가 오히려 우리를 더 비참하게 만든다고 한다.", "이는 고통이 중립적인 상태를 유지하는 능력의 필수 요소이기 때문이며, 고통을 허용하면 내부 저울이 균형으로 돌아온다."], "clue": ["'이런 점에서'로 항상성과 균형 설명을 이어받아 쾌락과 고통의 관계를 말함", "'그런데'로 화제를 전환해 Lembke의 주장을 소개함", "'이는 ... 때문'으로 바로 앞 주장의 이유를 설명함"], "why": ["몸의 균형 추구 -> 쾌락과 고통은 저울의 두 끝 -> 고통을 피하면 더 비참함 -> 이유는 고통이 필수 요소이기 때문"], "cards": ["이는 고통이 중립적인 상태를 유지하는 능력의 필수 요소이기 때문이며, 고통을 허용하면 내부 저울이 균형으로 돌아온다.", "이런 점에서 쾌락과 고통은 한 동전의 양면처럼 서로 의존하며 균형을 유지하는데, 저울 위에서 한쪽이 올라가면 다른 쪽은 상응하여 내려간다.", "그런데 정신과 의사 Anna Lembke는 '고통 없이는 얻는 것도 없다'는 말에 일리가 있을 수 있다며, 비참함에서 벗어나려는 시도가 오히려 우리를 더 비참하게 만든다고 한다."], "answer": [1, 2, 0]}, "sents": [{"n": 1, "en": "Based on discoveries in neuroscience, pain and pleasure are formed and processed in the same area of the brain.", "ko": "뇌 과학의 발견들에 따르면, 고통과 쾌락은 뇌의 같은 영역에서 형성되고 처리된다."}, {"n": 2, "en": "Our bodies constantly strive for homeostasis, which is defined as the balance of bodily functions.", "ko": "우리 몸은 끊임없이 항상성을 추구하는데, 그것은 몸의 기능들의 균형이라고 정의된다."}, {"n": 3, "en": "Without the body\u2019s effective compensatory mechanisms, which may cushion potential highs and lows, we would not be capable of surviving.", "ko": "잠재적인 변동을 완화시킬 수 있는 몸의 효과적인 보상 기제가 없다면 우리는 생존할 수 없을 것이다."}, {"n": 4, "en": "Pleasure and pain are like two sides of the same coin; they seem to work together and are heavily reliant on one another and keep balance.", "ko": "쾌락과 고통은 동일한 동전의 두 면과 같아서 그들은 함께 작동하는 것 같으며 서로 상당히 의존하고 있고 균형을 유지한다."}, {"n": 5, "en": "If you imagine pleasure and pain as the two opposite points on a scale, you can easily understand that as one of the two points rises, the other must correspondingly fall.", "ko": "만약에 여러분이 쾌락과 고통을 저울 위의 두 반대 지점으로 상상한다면, 여러분은 두 지점 중 한 지점이 올라가면 다른 한 지점이 상응하여 틀림없이 내려갈 것임을 쉽게 이해할 수 있을 것이다."}, {"n": 6, "en": "We\u2019ve all heard the expression, \u201cNo pain, no gain.\u201d", "ko": "우리는 \u2018고통 없이는, 얻는 것도 없다.\u2019라는 표현을 모두 들어본 적이 있다."}, {"n": 7, "en": "Well, according to psychiatrist Dr. Anna Lembke, there may be some truth to these words.", "ko": "자, 정신과 의사인 Dr. Anna Lembke에 따르면, 이 말에는 어느 정도의 진실이 있을 수 있다."}, {"n": 8, "en": "She says that our attempts to escape being miserable are in fact making us even more miserable.", "ko": "그녀는 우리가 비참함에서 벗어나려는 우리의 시도가 사실 우리를 훨씬 더 비참하게 만들고 있다고 말한다."}, {"n": 9, "en": "This is because pain is actually an essential component of our ability to maintain a neutral state, and allowing it will in turn reset our internal scale back to balance.", "ko": "이는 고통이 실제로 중립적인 상태를 유지하기 위한 우리 능력의 필수적인 구성 요소이기 때문이고, 그것을 허용하는 것은 결과적으로 우리의 내부 저울을 균형 상태로 다시 맞출 것이다."}]}, {"id": "2410-24", "short": "24년 10월 24번", "group": "24년 10월", "num": 24, "topic_ko": "제조업체가 만든 업그레이드 순환이 원하는 것과 필요한 것의 구분을 흐리게 함", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "제조업체가 현재 기기에 대한 의심을 심어 진짜 필요 전에 업그레이드 욕구가 시작됨"}, {"n": 2, "label": "전개", "from": 4, "to": 6, "summary_ko": "이 순환은 거의 모든 소비자 전자 기기로 번져 모든 제품이 다음 세대를 향해 나아가는 듯함"}, {"n": 3, "label": "결론", "from": 7, "to": 10, "summary_ko": "순환은 욕구를 형성하는 데 효과적이며, 원함과 필요의 구분이 흐려지고 유혹은 여전히 강함"}], "gloss": [{"w": "manufacturer", "m": "제조업체", "form": "manufacturers", "note": "명사 manufacturer의 복수형"}, {"w": "masterfully", "m": "능숙하게, 노련하게"}, {"w": "sow", "m": "(씨를) 뿌리다"}, {"w": "adequacy", "m": "적절성, 충분함"}, {"w": "lifeline", "m": "생명줄"}, {"w": "genuine", "m": "진짜의"}, {"w": "confine", "m": "국한하다", "form": "confined", "note": "동사 confine의 과거분사형(수동태 is confined)"}, {"w": "spill over", "m": "넘쳐 퍼지다, 번져나가다", "form": "spills over", "note": "동사구 spill over의 3인칭 단수 현재형(주어 It이 단수)"}, {"w": "revolutionize", "m": "혁신하다, 크게 바꾸다"}, {"w": "fascinating", "m": "흥미로운"}, {"w": "efficacy", "m": "효과, 효능"}, {"w": "blur", "m": "흐릿해지다", "form": "blurs", "note": "동사 blur의 3인칭 단수 현재형(주어 The distinction이 단수)"}, {"w": "temptation", "m": "유혹"}, {"w": "compelling", "m": "강력한, 거부하기 힘든"}], "qa": [{"chunk": 1, "q": "제조업체들이 우리에게 심어 주는 의심은 무엇에 대한 것인가?", "opts": ["새 기기의 가격이 적절한지", "기기의 안전성이 충분한지", "현재 우리가 가진 기기가 적절한지"], "ans": 2, "why": ["1번 문장에서 제조업체가 현재 기기들의 적절성에 대한 의심의 씨앗을 뿌린다고 함.", "새 기기의 가격이나 안전성은 지문에 나오지 않음."], "ev_en": "Manufacturers masterfully sow seeds of doubt about the adequacy of our current devices.", "ev_ko": "생산자들은 노련하게 우리의 현재 기기들의 적절성에 대한 의심의 씨앗을 뿌린다."}, {"chunk": 2, "q": "글쓴이가 말하는 이 순환이 퍼지는 범위는?", "opts": ["휴대폰에만 한정된다.", "소비자 전자 기기의 거의 모든 영역으로 번진다.", "자율 주행 자동차 산업에만 한정된다."], "ans": 1, "why": ["4번 문장에서 이 순환은 디지털 용품에만 국한되지 않는다고 함.", "5번 문장에서 자율 주행 자동차부터 스마트 냉장고까지 거의 모든 영역으로 번진다고 함.", "휴대폰이나 자동차에만 한정된다는 말은 지문과 반대임."], "ev_en": "This cycle isn\u2019t just confined to our digital companions. It spills over into almost every aspect of consumer electronics, from the self-driving car to the smart fridge.", "ev_ko": "이러한 순환은 단지 우리의 디지털 용품에 국한되지 않는다. 이것은 자율 주행 자동차부터 스마트 냉장고에 이르기까지 소비자 전자 기기들의 거의 모든 영역까지 번져나간다."}, {"chunk": 3, "q": "이 순환의 결과로 지문에서 말하는 것은?", "opts": ["원하는 것과 필요한 것의 구분이 흐릿해진다.", "사람들이 최신 기기를 필요 없다고 믿게 된다.", "논리적인 반대 주장 때문에 유혹이 사라진다."], "ans": 0, "why": ["9번 문장에서 원하는 것과 필요한 것 사이의 구분이 흐릿해진다고 함.", "8번 문장에서 사람들은 최신 기기를 필요로 한다고 믿도록 유도되므로 '필요 없다고 믿는다'는 보기는 틀림.", "10번 문장에서 논리적인 반대 주장에도 유혹은 여전히 강력하다고 하므로 사라진다는 보기는 틀림."], "ev_en": "The distinction between want and need blurs, shifting our financial priorities in favor of staying current with trends.", "ev_ko": "최신 트렌드를 유지하는 것을 선호하는 쪽으로 우리의 재정적인 우선순위를 바꾸면서, 원하는 것과 필요한 것 사이의 구분이 흐릿해진다."}], "tf": [{"s": "제조업체는 우리의 현재 기기가 적절한지에 대한 의심을 능숙하게 심어 준다.", "t": true, "why": ["1번 문장의 내용임."], "ev_en": "Manufacturers masterfully sow seeds of doubt about the adequacy of our current devices.", "ev_ko": "생산자들은 노련하게 우리의 현재 기기들의 적절성에 대한 의심의 씨앗을 뿌린다."}, {"s": "업그레이드에 대한 욕구는 대개 진짜 필요가 생긴 뒤에 시작된다.", "t": false, "why": ["틀린 부분은 '필요가 생긴 뒤'임.", "업그레이드 욕구는 종종 진짜 필요가 있기 이전에 시작됨."], "ev_en": "And thus, the itch to upgrade begins, often before there\u2019s a genuine need.", "ev_ko": "그래서 종종 진짜 필요가 있기 이전에 업그레이드에 대한 욕구가 시작된다."}, {"s": "이 순환은 자율 주행 자동차부터 스마트 냉장고에 이르기까지 소비자 전자 기기 전반으로 번져 나간다.", "t": true, "why": ["5번 문장의 내용임."], "ev_en": "It spills over into almost every aspect of consumer electronics, from the self-driving car to the smart fridge.", "ev_ko": "이것은 자율 주행 자동차부터 스마트 냉장고에 이르기까지 소비자 전자 기기들의 거의 모든 영역까지 번져나간다."}, {"s": "우리는 최신 기기를 필요로 한다고 믿도록 유도되기보다, 단순히 원해서 사게 되는 것이다.", "t": false, "why": ["지문과 반대임.", "우리가 최신 기기를 원하는 것이라기보다는 그것을 필요로 한다고 믿도록 유도되는 것임."], "ev_en": "It\u2019s not so much that we want the newest device; we\u2019re led to believe we need it.", "ev_ko": "우리가 가장 최신 기기를 원하는 것이라기보다는, 우리가 그것을 필요로 한다고 믿도록 유도된 것이다."}, {"s": "끊임없는 업그레이드에 반대하는 논리적인 주장이 있어도 유혹은 여전히 강력하다.", "t": true, "why": ["10번 문장의 내용임."], "ev_en": "For all the logical arguments against this ceaseless upgrading, the temptation remains compelling.", "ev_ko": "이런 끊임없는 업그레이드에 반대하는 논리적인 주장들에도 불구하고, 유혹은 여전히 강력하다."}], "flow": {"fixed": "제조업체는 현재 기기의 적절성에 대한 의심의 씨앗을 노련하게 뿌려, 종종 진짜 필요가 생기기도 전에 업그레이드에 대한 욕구가 시작되는 순환을 만든다.", "order": ["이런 순환은 휴대폰에 국한되지 않고 자율 주행 자동차부터 스마트 냉장고까지 거의 모든 소비자 전자 기기로 번지며, 모든 제품이 다음 세대를 향해 멈출 수 없이 나아가는 것처럼 보인다.", "흥미로운 점은 이 순환이 욕구를 형성하는 데 매우 효과적이라는 것으로, 사람들은 최신 기기를 원하기보다 필요하다고 믿도록 유도된다.", "그 결과 원하는 것과 필요한 것의 구분이 흐려져 재정적 우선순위가 바뀌고, 끊임없는 업그레이드에 반대하는 논리적 주장이 있어도 유혹은 여전히 강력하다."], "clue": ["'이런 순환은'이 앞에서 만들어진 업그레이드 욕구의 순환을 가리키며 그 범위를 넓혀 설명함", "'흥미로운 점은'으로 순환의 효과라는 새 논점을 열음", "'그 결과'로 앞의 믿음이 낳은 결과를 말함"], "why": ["의심의 씨앗 -> 순환이 모든 전자 기기로 번짐 -> 필요하다고 믿게 됨 -> 원함과 필요의 구분이 흐려짐"], "cards": ["흥미로운 점은 이 순환이 욕구를 형성하는 데 매우 효과적이라는 것으로, 사람들은 최신 기기를 원하기보다 필요하다고 믿도록 유도된다.", "이런 순환은 휴대폰에 국한되지 않고 자율 주행 자동차부터 스마트 냉장고까지 거의 모든 소비자 전자 기기로 번지며, 모든 제품이 다음 세대를 향해 멈출 수 없이 나아가는 것처럼 보인다.", "그 결과 원하는 것과 필요한 것의 구분이 흐려져 재정적 우선순위가 바뀌고, 끊임없는 업그레이드에 반대하는 논리적 주장이 있어도 유혹은 여전히 강력하다."], "answer": [1, 0, 2]}, "sents": [{"n": 1, "en": "Manufacturers masterfully sow seeds of doubt about the adequacy of our current devices.", "ko": "생산자들은 노련하게 우리의 현재 기기들의 적절성에 대한 의심의 씨앗을 뿌린다."}, {"n": 2, "en": "Suddenly, the phone that was your lifeline a year ago is now a museum piece, unable to keep pace with your digital demands.", "ko": "갑자기, 1년 전의 당신의 목숨줄이었던 휴대폰이 지금은 당신의 디지털 수요를 따라가지 못하는, 시대에 뒤떨어진 것이 되었다."}, {"n": 3, "en": "And thus, the itch to upgrade begins, often before there\u2019s a genuine need.", "ko": "그래서 종종 진짜 필요가 있기 이전에 업그레이드에 대한 욕구가 시작된다."}, {"n": 4, "en": "This cycle isn\u2019t just confined to our digital companions.", "ko": "이러한 순환은 단지 우리의 디지털 용품에 국한되지 않는다."}, {"n": 5, "en": "It spills over into almost every aspect of consumer electronics, from the self-driving car to the smart fridge.", "ko": "이것은 자율 주행 자동차부터 스마트 냉장고에 이르기까지 소비자 전자 기기들의 거의 모든 영역까지 번져나간다."}, {"n": 6, "en": "Every product seems to be on an unstoppable march towards the next version, the next generation that promises to revolutionize your life.", "ko": "모든 제품은 다음 버전, 즉, 당신의 삶에 변혁을 일으키겠다는 약속을 하는 다음 세대를 향한 멈출 수 없는 행진을 하는 것으로 보인다."}, {"n": 7, "en": "What\u2019s fascinating, or perhaps disturbing, is the utter efficacy of this cycle in shaping our desires.", "ko": "흥미로운 점, 또는 어쩌면 당황스러운 점은 우리의 욕구를 형성하는 이 순환의 절대적인 효과이다."}, {"n": 8, "en": "It\u2019s not so much that we want the newest device; we\u2019re led to believe we need it.", "ko": "우리가 가장 최신 기기를 원하는 것이라기보다는, 우리가 그것을 필요로 한다고 믿도록 유도된 것이다."}, {"n": 9, "en": "The distinction between want and need blurs, shifting our financial priorities in favor of staying current with trends.", "ko": "최신 트렌드를 유지하는 것을 선호하는 쪽으로 우리의 재정적인 우선순위를 바꾸면서, 원하는 것과 필요한 것 사이의 구분이 흐릿해진다."}, {"n": 10, "en": "For all the logical arguments against this ceaseless upgrading, the temptation remains compelling.", "ko": "이런 끊임없는 업그레이드에 반대하는 논리적인 주장들에도 불구하고, 유혹은 여전히 강력하다."}]}, {"id": "2410-29", "short": "24년 10월 29번", "group": "24년 10월", "num": 29, "topic_ko": "조건부 장소 선호도로 동물이 원하는 것을 알아내는 방법", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "조건부 장소 선호도는 동물이 무엇을 원하는지 알아내는 방법이며, 두 장소를 서로 다른 경험과 연관시키도록 훈련시킴"}, {"n": 2, "label": "과정", "from": 3, "to": 6, "summary_ko": "두 장소를 명백히 다르게 만들고 경험 전후의 선호도를 측정해, 선택의 변화로 좋아했는지 싫어했는지 해석함"}, {"n": 3, "label": "예시", "from": 7, "to": 8, "summary_ko": "암에 걸린 쥐만 모르핀이 주어진 장소를 선호해, 그 쥐가 모르핀을 원했음을 보여 줌"}], "gloss": [{"w": "preference", "m": "선호(도)"}, {"w": "associate", "m": "연관시키다"}, {"w": "measure", "m": "측정하다", "form": "measured", "note": "동사 measure의 과거분사형(수동태 is measured)"}, {"w": "shift", "m": "변화, 이동"}, {"w": "reward", "m": "보상"}, {"w": "conversely", "m": "반대로"}, {"w": "avoid", "m": "피하다", "form": "avoids", "note": "동사 avoid의 3인칭 단수형(주어 it이 단수)"}, {"w": "stimulus", "m": "자극"}, {"w": "unpleasant", "m": "불쾌한"}, {"w": "relieve", "m": "완화하다, 덜어 주다"}, {"w": "saline", "m": "식염수"}, {"w": "mouse", "m": "쥐", "form": "mice", "note": "명사 mouse의 복수형(불규칙)"}], "qa": [{"chunk": 1, "q": "조건부 장소 선호도는 어떤 방법인가?", "opts": ["동물의 병을 치료하는 방법", "동물이 무엇을 원하는지 알아내는 방법", "동물이 새 장소에 적응하게 하는 방법"], "ans": 1, "why": ["첫 문장이 정의 그 자체임.", "조건부 장소 선호도(Conditioned Place Preference)는 동물이 무엇을 원하는지 알아내는 방법임.", "치료나 적응은 지문에 나오지 않음."], "ev_en": "Conditioned Place Preference is a way of finding out what animals want.", "ev_ko": "조건부 장소 선호도는 동물들이 무엇을 원하는지 알아내는 하나의 방법이다."}, {"chunk": 2, "q": "두 장소를 명백히 다르게 만드는 이유는?", "opts": ["동물이 두 장소를 경험과 쉽게 연관시키게 하려고", "동물이 두 장소 모두 싫어하게 하려고", "동물이 두 장소에서 오래 머물지 못하게 하려고"], "ans": 0, "why": ["두 장소를 다르게 하는 목적은 동물이 장소와 거기서 일어난 일을 쉽게 연관시키도록 하기 위함임.", "'두 장소를 모두 싫어하게 한다'거나 '오래 머물지 못하게 한다'는 내용은 지문에 없고, 장소와 경험을 쉽게 연관시키려는 것이 목적임."], "ev_en": "The two places are made obviously different to make it as easy as possible for the animal to associate each place with what happened to it there.", "ev_ko": "그 두 장소는 그 동물이 각 장소를 거기에서 그것에게 일어난 일과 연관시키는 것을 가능한 한 쉽게 만들기 위해 명백히 다르게 만들어진다."}, {"chunk": 3, "q": "암에 걸린 쥐가 모르핀이 주어진 장소를 선호한 것은 무엇을 시사하는가?", "opts": ["그 쥐가 식염수를 싫어했다는 것", "그 쥐가 모르핀을 원했다는 것", "건강한 쥐도 모르핀을 원했다는 것"], "ans": 1, "why": ["마지막 문장에서 암에 걸린 쥐가 모르핀을 원했음을 시사한다고 결론 내림.", "건강한 쥐는 그런 선호가 생기지 않았으므로 '건강한 쥐도 모르핀을 원했다'는 내용은 틀림.", "식염수를 싫어했다는 내용은 없음. 선호의 대상은 모르핀이 주어진 장소임."], "ev_en": "This suggests that the mice with cancer wanted the morphine.", "ev_ko": "이것은 암에 걸린 쥐가 그 모르핀을 원했음을 시사한다."}], "tf": [{"s": "동물의 선호도는 두 장소에서의 경험이 끝난 뒤에만 측정된다.", "t": false, "why": ["틀린 부분은 \"뒤에만\"임.", "선호도는 경험 전과 후에 모두 측정됨."], "ev_en": "The animal\u2019s preference for being in one place or another is measured both before and after its experiences in the two places.", "ev_ko": "한 장소나 다른 장소에 있는 것에 대한 그 동물의 선호도는 두 장소에서 경험하기 전과 후에 모두 측정된다."}, {"s": "연구자는 한 장소는 어떤 경험과, 다른 장소는 대개 아무 일도 일어나지 않는 것과 연관시키도록 동물을 훈련시킨다.", "t": true, "why": ["한 장소는 음식이나 시끄러운 소리 같은 경험, 다른 장소는 대개 아무 일도 없음으로 훈련하므로 맞음."], "ev_en": "Researchers train them to associate one place with an experience such as food or a loud noise and another place with something completely different, usually where nothing happens.", "ev_ko": "연구자들은 그것들이 한 장소를 음식이나 시끄러운 소리와 같은 경험과 연관시키고 또 다른 장소를 완벽히 다른 어떤 것과 연관시키도록 훈련시키는데 대개 그곳에서는 아무것도 일어나지 않는다."}, {"s": "동물이 자극이 나타났던 장소를 피하기 시작하면, 그 자극을 불쾌하게 느꼈음을 시사한다.", "t": true, "why": ["자극이 있던 장소를 피하고 반대쪽을 선호하면 불쾌했다는 뜻이므로 맞음."], "ev_en": "Conversely, if it now avoids the place the stimulus appeared and starts to prefer the place it did not experience it, then this suggests that it found the stimulus unpleasant.", "ev_ko": "반대로, 만약 그것이 이제 자극이 나타났던 장소를 피하고 그것이 그것을 경험하지 않았던 장소를 선호하기 시작한다면, 그러면 이것은 그것이 그 자극을 불쾌하게 느꼈다는 것을 시사한다."}, {"s": "동물이 보상을 위해 시간을 보내는 장소를 바꾸면, 그 경험을 좋아해서 반복하려는 것으로 해석할 수 있다.", "t": true, "why": ["선택하는 장소에 변화가 있으면 동물이 그 경험을 좋아했고 반복하려 한다는 뜻이므로 맞음."], "ev_en": "If there is a shift in where the animal chooses to spend its time for the reward, this suggests that it liked the experience and is trying to repeat it.", "ev_ko": "만약 동물이 보상을 위해 어디에서 시간을 보내기로 선택하는지에 변화가 있다면, 이것은 그것이 그 경험을 좋아했고 그것을 반복하려고 노력하는 중이라는 것을 시사한다."}, {"s": "건강한 쥐도 암에 걸린 쥐처럼 모르핀이 주어진 장소를 선호하게 되었다.", "t": false, "why": ["틀린 부분은 건강한 쥐도 선호했다는 점임.", "건강한 쥐는 그러한 선호가 생기지 않았음."], "ev_en": "For example, mice with cancer show a preference for the place where they have been given morphine, a drug used to relieve pain, rather than where they have received saline whereas healthy mice developed no such preference.", "ev_ko": "예를 들어, 암에 걸린 쥐가 식염수를 받아 왔었던 곳보다 통증을 완화시키는 데 사용되는 약인 모르핀이 주어졌었던 장소에 대한 선호를 보여 준 반면, 건강한 쥐는 그러한 선호가 생기지 않았다."}], "flow": {"fixed": "조건부 장소 선호도는 동물이 무엇을 원하는지 알아내는 하나의 방법이다.", "order": ["이를 위해 구체적으로 연구자는 동물이 한 장소는 음식이나 시끄러운 소리 같은 경험과, 다른 장소는 아무 일도 없는 상태와 연관시키도록 훈련시키며, 두 장소는 확연히 다르게 만든다.", "그 뒤 경험 전후의 선호도를 비교해, 경험이 있던 장소를 더 택하면 그 경험을 좋아한 것이고 그곳을 피하면 불쾌하게 여긴 것으로 해석한다.", "예를 들어 암에 걸린 쥐는 진통제인 모르핀이 주어진 장소를 선호했지만 건강한 쥐는 그러지 않아, 암에 걸린 쥐가 모르핀을 원했음을 알 수 있다."], "clue": ["\"이를 위해 구체적으로\"로 앞 문장의 목적(원하는 것 알아내기)을 받아 방법(훈련)을 설명함", "\"그 뒤\"로 훈련 다음 단계인 선호도 비교\u00b7해석을 이어 감", "\"예를 들어\"로 마지막에 구체적 사례를 제시함"], "why": ["정의 -> 훈련 방법 -> 결과 해석 -> 쥐 실험 예시 순서임."], "cards": ["이를 위해 구체적으로 연구자는 동물이 한 장소는 음식이나 시끄러운 소리 같은 경험과, 다른 장소는 아무 일도 없는 상태와 연관시키도록 훈련시키며, 두 장소는 확연히 다르게 만든다.", "예를 들어 암에 걸린 쥐는 진통제인 모르핀이 주어진 장소를 선호했지만 건강한 쥐는 그러지 않아, 암에 걸린 쥐가 모르핀을 원했음을 알 수 있다.", "그 뒤 경험 전후의 선호도를 비교해, 경험이 있던 장소를 더 택하면 그 경험을 좋아한 것이고 그곳을 피하면 불쾌하게 여긴 것으로 해석한다."], "answer": [0, 2, 1]}, "sents": [{"n": 1, "en": "Conditioned Place Preference is a way of finding out what animals want.", "ko": "조건부 장소 선호도는 동물들이 무엇을 원하는지 알아내는 하나의 방법이다."}, {"n": 2, "en": "Researchers train them to associate one place with an experience such as food or a loud noise and another place with something completely different, usually where nothing happens.", "ko": "연구자들은 그것들이 한 장소를 음식이나 시끄러운 소리와 같은 경험과 연관시키고 또 다른 장소를 완벽히 다른 어떤 것과 연관시키도록 훈련시키는데 대개 그곳에서는 아무것도 일어나지 않는다."}, {"n": 3, "en": "The two places are made obviously different to make it as easy as possible for the animal to associate each place with what happened to it there.", "ko": "그 두 장소는 그 동물이 각 장소를 거기에서 그것에게 일어난 일과 연관시키는 것을 가능한 한 쉽게 만들기 위해 명백히 다르게 만들어진다."}, {"n": 4, "en": "The animal\u2019s preference for being in one place or another is measured both before and after its experiences in the two places.", "ko": "한 장소나 다른 장소에 있는 것에 대한 그 동물의 선호도는 두 장소에서 경험하기 전과 후에 모두 측정된다."}, {"n": 5, "en": "If there is a shift in where the animal chooses to spend its time for the reward, this suggests that it liked the experience and is trying to repeat it.", "ko": "만약 동물이 보상을 위해 어디에서 시간을 보내기로 선택하는지에 변화가 있다면, 이것은 그것이 그 경험을 좋아했고 그것을 반복하려고 노력하는 중이라는 것을 시사한다."}, {"n": 6, "en": "Conversely, if it now avoids the place the stimulus appeared and starts to prefer the place it did not experience it, then this suggests that it found the stimulus unpleasant.", "ko": "반대로, 만약 그것이 이제 자극이 나타났던 장소를 피하고 그것이 그것을 경험하지 않았던 장소를 선호하기 시작한다면, 그러면 이것은 그것이 그 자극을 불쾌하게 느꼈다는 것을 시사한다."}, {"n": 7, "en": "For example, mice with cancer show a preference for the place where they have been given morphine, a drug used to relieve pain, rather than where they have received saline whereas healthy mice developed no such preference.", "ko": "예를 들어, 암에 걸린 쥐가 식염수를 받아 왔었던 곳보다 통증을 완화시키는 데 사용되는 약인 모르핀이 주어졌었던 장소에 대한 선호를 보여 준 반면, 건강한 쥐는 그러한 선호가 생기지 않았다."}, {"n": 8, "en": "This suggests that the mice with cancer wanted the morphine.", "ko": "이것은 암에 걸린 쥐가 그 모르핀을 원했음을 시사한다."}]}, {"id": "2410-30", "short": "24년 10월 30번", "group": "24년 10월", "num": 30, "topic_ko": "새들의 번식기 결정 요인과 그 예외", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 3, "summary_ko": "적도 근처 새는 일 년 내내 번식하지만, 온대\u00b7극지방 새는 낮의 길이 변화로 번식기가 뚜렷이 정해짐"}, {"n": 2, "label": "전개", "from": 4, "to": 6, "summary_ko": "먹이가 최고조일 때 새끼를 기르며, 다른 때에는 번식 기관이 줄어 번식이 불가능함"}, {"n": 3, "label": "예외와 다양성", "from": 7, "to": 13, "summary_ko": "유목성 사막 종은 비가 오면 번식을 시작하며, 종마다 번식기를 나누는 방식이 다름"}], "gloss": [{"w": "breed", "m": "번식하다"}, {"w": "temperate", "m": "온화한, 온대의"}, {"w": "trigger", "m": "촉발하다", "form": "triggered", "note": "동사 trigger의 과거분사형(수동태 are triggered)"}, {"w": "reluctant", "m": "꺼리는"}, {"w": "incapable", "m": "~할 수 없는"}, {"w": "reproductive", "m": "번식의, 생식의"}, {"w": "shrink", "m": "줄어들다", "form": "shrinks", "note": "동사 shrink의 3인칭 단수 현재형(주어 their reproductive system이 단수)"}, {"w": "exception", "m": "예외"}, {"w": "nomadic", "m": "유목하는"}, {"w": "initiate", "m": "시작하다"}, {"w": "brood", "m": "한배에서 태어난 새끼 무리 (본문의 broods는 복수형)"}, {"w": "exceptionally", "m": "유난히"}, {"w": "successive", "m": "잇따른"}, {"w": "songbird", "m": "명금(\u9cf4\u79bd), 노래하는 작은 새", "form": "songbirds", "note": "명사 songbird의 복수형"}], "qa": [{"chunk": 1, "q": "온대와 극지방에서 새의 번식기를 촉발하는 주된 요인은?", "opts": ["먹이 종류의 변화", "낮의 길이 변화", "기온의 급격한 상승"], "ans": 1, "why": ["3번 문장에서 번식기는 주로 낮의 길이 변화에 의해 촉발된다고 함.", "먹이나 기온은 이 문장의 요인이 아님."], "ev_en": "They are triggered mainly by changes in day length.", "ev_ko": "그것들은 주로 낮의 길이의 변화에 의해 촉발된다."}, {"chunk": 2, "q": "대부분의 새가 번식기가 아닌 때 번식하지 못하는 이유는?", "opts": ["먹이를 구할 수 없어서 죽기 때문", "번식 기관이 줄어들어 신체적으로 불가능하기 때문", "천적을 피해 이동하기 때문"], "ans": 1, "why": ["5번 문장: 새들은 다른 때에 번식을 꺼릴 뿐 아니라 신체적으로도 불가능함.", "6번 문장: 번식 기관이 줄어들며, 이는 나는 새가 몸무게를 줄이게 도움.", "죽음이나 천적은 지문에 없음."], "ev_en": "This is because their reproductive system shrinks, which helps flying birds save weight.", "ev_ko": "이것은 왜냐하면 그들의 번식 기관이 줄어들기 때문이고, 이 사실은 나는 새들이 몸무게를 줄일 수 있도록 도와준다."}, {"chunk": 3, "q": "유목성 사막 종이 비가 온 지 며칠 안에 번식 주기를 시작할 수 있는 이유는?", "opts": ["갑작스러운 번식 기회를 최대한 활용하기 위해", "낮의 길이 변화에 맞추기 위해", "번식 기관을 줄여 몸무게를 줄이기 위해"], "ans": 0, "why": ["8번 문장에서 비 온 뒤 며칠 안에 번식을 시작한다고 했고, 그 이유를 9번 문장이 밝힘: 갑작스러운 번식 기회를 최대한 활용하기 위함.", "낮의 길이와 번식 기관 축소는 일반 규칙이며, 사막 종은 그 규칙의 예외임."], "ev_en": "It\u2019s for making the most of the sudden breeding opportunity.", "ev_ko": "그것은 갑작스러운 번식 기회를 최대한으로 활용하기 위한 것이다."}], "tf": [{"s": "적도 근처에서는 많은 종의 새가 일 년 내내 번식한다.", "t": true, "why": ["적도 근처 새의 많은 종은 일 년 내내 번식하므로 맞음."], "ev_en": "Near the equator, many species of bird breed all year round.", "ev_ko": "적도 근처에서, 새의 많은 종들은 일 년 내내 번식한다."}, {"s": "유난히 좋은 해에도 참새 한 쌍은 한 무리의 새끼만 기를 수 있다.", "t": false, "why": ["틀린 부분은 \"한 무리만\"임.", "유난히 좋은 해에는 참새 한 쌍이 잇따라 여러 무리의 새끼를 기를 수 있음."], "ev_en": "In an exceptionally good year, a pair of House Sparrows, a kind of songbird, can raise successive broods through a marathon reproductive effort.", "ev_ko": "유난히 좋은 해에는 명금(\u9cf4\u79bd)의 한 종류인 참새 한 쌍은 마라톤과 같은 번식 노력을 통해 잇따라 태어난 여러 무리의 함께 태어난 새끼들을 기를 수 있다."}, {"s": "대부분의 새는 번식기가 아닌 때에도 신체적으로는 번식할 수 있지만 꺼릴 뿐이다.", "t": false, "why": ["틀린 부분은 \"신체적으로는 할 수 있다\"임.", "대부분의 새는 꺼릴 뿐 아니라 신체적으로도 번식할 수 없음."], "ev_en": "Most birds are not simply reluctant to breed at other times but they are also physically incapable of doing so.", "ev_ko": "대부분의 새들은 다른 때에 번식하기를 단지 꺼리는 것뿐만 아니라 또한 신체적으로 그렇게 할 수 없는 것이다."}, {"s": "대부분의 바닷새는 한 무리의 새끼를 기른다.", "t": true, "why": ["대부분의 바닷새는 한 배에서 난 새끼 무리(brood) 하나를 기르므로 맞음."], "ev_en": "Most seabirds raise a single brood.", "ev_ko": "대부분의 바닷새들은 한 무리의 함께 태어난 새끼를 기른다."}, {"s": "따뜻한 지역의 명금은 몇 달 안에 여러 무리의 새끼를 기를 수도 있다.", "t": true, "why": ["명금이 몇 달 안에 여러 가족(여러 무리의 새끼)을 기를 수도 있으므로 맞음."], "ev_en": "In warm regions, however, songbirds may raise several families in a few months.", "ev_ko": "그러나, 따뜻한 지역에서는, 명금(\u9cf4\u79bd)들이 몇 달 안에 여러 자녀들을 기를 수도 있다."}], "flow": {"fixed": "적도 근처에서는 많은 종의 새가 일 년 내내 번식하지만, 온대와 극지방에서는 번식기가 뚜렷이 정해져 있고 그 계기는 주로 낮의 길이 변화이다.", "order": ["그 결과 새들은 먹이 공급이 최고조일 때 새끼를 기르게 되며, 대부분의 새는 다른 때에는 번식 기관이 줄어들어 번식하고 싶어도 할 수 없다.", "그러나 유목성 사막 종은 이 규칙의 예외여서, 비가 내리면 며칠 안에 번식 주기를 시작해 갑작스러운 기회를 최대한 활용한다.", "또한 이런 예외 말고도 종마다 번식 기간을 나누는 방식이 달라서, 대부분의 바닷새는 한 무리만 기르지만 따뜻한 지역의 명금은 여러 무리를 기를 수도 있다."], "clue": ["\"그 결과\"로 앞의 번식기 결정(낮의 길이)의 결과를 설명함", "\"그러나 ... 예외\"로 앞의 일반 규칙에 반대되는 사례를 제시함", "\"또한 이런 예외 말고도\"가 앞의 예외 설명을 받아 종별 차이를 덧붙임"], "why": ["일반 규칙 -> 그 결과 -> 사막 종 예외 -> 종별 번식 방식 차이 순서임."], "cards": ["또한 이런 예외 말고도 종마다 번식 기간을 나누는 방식이 달라서, 대부분의 바닷새는 한 무리만 기르지만 따뜻한 지역의 명금은 여러 무리를 기를 수도 있다.", "그 결과 새들은 먹이 공급이 최고조일 때 새끼를 기르게 되며, 대부분의 새는 다른 때에는 번식 기관이 줄어들어 번식하고 싶어도 할 수 없다.", "그러나 유목성 사막 종은 이 규칙의 예외여서, 비가 내리면 며칠 안에 번식 주기를 시작해 갑작스러운 기회를 최대한 활용한다."], "answer": [1, 2, 0]}, "sents": [{"n": 1, "en": "Near the equator, many species of bird breed all year round.", "ko": "적도 근처에서, 새의 많은 종들은 일 년 내내 번식한다."}, {"n": 2, "en": "But in temperate and polar regions, the breeding seasons of birds are often sharply defined.", "ko": "하지만 온대와 극지방에서는 새들의 번식기들이 대개 뚜렷하게 정해진다."}, {"n": 3, "en": "They are triggered mainly by changes in day length.", "ko": "그것들은 주로 낮의 길이의 변화에 의해 촉발된다."}, {"n": 4, "en": "If all goes well, the outcome is that birds raise their young when the food supply is at its peak.", "ko": "만약에 모든 것이 잘 진행된다면, 결과는 새들이 먹이 공급이 최고조에 이를 때 새끼들을 기르는 것이다."}, {"n": 5, "en": "Most birds are not simply reluctant to breed at other times but they are also physically incapable of doing so.", "ko": "대부분의 새들은 다른 때에 번식하기를 단지 꺼리는 것뿐만 아니라 또한 신체적으로 그렇게 할 수 없는 것이다."}, {"n": 6, "en": "This is because their reproductive system shrinks, which helps flying birds save weight.", "ko": "이것은 왜냐하면 그들의 번식 기관이 줄어들기 때문이고, 이 사실은 나는 새들이 몸무게를 줄일 수 있도록 도와준다."}, {"n": 7, "en": "The main exception to this rule are nomadic desert species.", "ko": "유목성 사막 종은 이 규칙의 주요 예외이다."}, {"n": 8, "en": "These can initiate their breeding cycle within days of rain.", "ko": "이들은 비가 오는 날들에 번식 주기를 시작할 수 있다."}, {"n": 9, "en": "It\u2019s for making the most of the sudden breeding opportunity.", "ko": "그것은 갑작스러운 번식 기회를 최대한으로 활용하기 위한 것이다."}, {"n": 10, "en": "Also, different species divide the breeding season up in different ways.", "ko": "또한, 다른 종들은 번식 기간을 다른 방식으로 나눈다."}, {"n": 11, "en": "Most seabirds raise a single brood.", "ko": "대부분의 바닷새들은 한 무리의 함께 태어난 새끼를 기른다."}, {"n": 12, "en": "In warm regions, however, songbirds may raise several families in a few months.", "ko": "그러나, 따뜻한 지역에서는, 명금(\u9cf4\u79bd)들이 몇 달 안에 여러 자녀들을 기를 수도 있다."}, {"n": 13, "en": "In an exceptionally good year, a pair of House Sparrows, a kind of songbird, can raise successive broods through a marathon reproductive effort.", "ko": "유난히 좋은 해에는 명금(\u9cf4\u79bd)의 한 종류인 참새 한 쌍은 마라톤과 같은 번식 노력을 통해 잇따라 태어난 여러 무리의 함께 태어난 새끼들을 기를 수 있다."}]}, {"id": "2410-33", "short": "24년 10월 33번", "group": "24년 10월", "num": 33, "topic_ko": "읽기를 하나로 정의할 수 없고 폭넓은 스펙트럼으로 이해해야 함", "chunks": [{"n": 1, "label": "도입", "from": 1, "to": 2, "summary_ko": "읽기가 다른 행동과 깔끔히 분리되는 단일한 개념이라는 주장에 대해 정말 그렇게 단순한지 의문을 제기함"}, {"n": 2, "label": "전개", "from": 3, "to": 5, "summary_ko": "읽기는 공통된 하나의 특성 없는 느슨한 행동의 묶음이어서 읽기와 비읽기의 구분은 실패함"}, {"n": 3, "label": "마무리", "from": 6, "to": 7, "summary_ko": "예외적 읽기 형태를 모으는 시도는 가치가 있으며, 읽기를 폭넓은 스펙트럼으로 이해하게 함"}], "gloss": [{"w": "consistent", "m": "일관된"}, {"w": "concept", "m": "개념"}, {"w": "productive", "m": "생산적인"}, {"w": "resemblance", "m": "닮음, 유사성", "form": "resemblances", "note": "명사 resemblance의 복수형"}, {"w": "trait", "m": "특성"}, {"w": "distinguish", "m": "구별하다"}, {"w": "destined", "m": "~할 운명인"}, {"w": "qualify", "m": "자격이 있다, 자격을 얻다", "form": "qualifies", "note": "동사 qualify의 3인칭 단수 현재형 (주어 what이 단수로 취급됨)"}, {"w": "boundary", "m": "경계", "form": "boundaries", "note": "명사 boundary의 복수형(y를 i로 바꾸고 es)"}, {"w": "exceptional", "m": "예외적인"}, {"w": "expansive", "m": "광범위한"}, {"w": "accommodate", "m": "수용하다"}, {"w": "edge case", "m": "특이 사례, 경계 사례", "form": "edge cases", "note": "명사 edge case의 복수형"}, {"w": "forum", "m": "토론의 장, 공개 토론 마당"}], "qa": [{"chunk": 1, "q": "1~2번 문장에서 일부 사람들의 주장에 대한 필자의 태도는?", "opts": ["주장이 옳다고 확신한다", "읽기가 그렇게 단순한지 의문을 제기한다", "주장을 근거 없이 무시한다"], "ans": 1, "why": ["1번 문장은 일부 사람들의 주장을 소개함.", "2번 문장 \"읽기는 정말로 그렇게 단순할까?\"는 그 주장에 대한 의문 제기임."], "ev_en": "Is reading really that simple?", "ev_ko": "읽기는 정말로 그렇게 단순할까?"}, {"chunk": 2, "q": "읽기와 읽기가 아닌 것을 구분하려는 노력이 실패하는 이유는?", "opts": ["읽기를 가르치는 사람이 부족하기 때문", "책 이외의 읽기 자료가 너무 적기 때문", "무엇이 읽기인지에 대한 동의가 애초에 없기 때문"], "ans": 2, "why": ["4번 문장에서 이유를 직접 밝힘: 애초에 무엇이 읽기로서 자격이 있는지에 대한 합의가 없음.", "교사 수나 자료 양은 지문에 없음."], "ev_en": "Consequently, efforts to distinguish reading from nonreading are destined to fail because there is no agreement on what qualifies as reading in the first place.", "ev_ko": "결론적으로, 읽기와 읽기가 아닌 것을 구분하려는 노력은 실패로 돌아가는데, 왜냐하면 애초에 무엇이 읽기로서의 자격을 주는가에 대한 동의가 없기 때문이다."}, {"chunk": 3, "q": "필자가 예외적인 읽기 형태를 모으는 시도로 도달하려는 이해는?", "opts": ["하나의 명확한 기준으로 정리된 읽기", "다양한 읽기 활동을 수용할 만큼 넓은 스펙트럼으로서의 읽기", "책 읽기와 다른 행동의 엄격한 구분"], "ans": 1, "why": ["7번 문장: 그 시도는 별개의 읽기 활동들을 수용할 만큼 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전함.", "필자는 읽기를 하나의 명확한 기준으로 정리하거나 책 읽기와 다른 행동을 엄격히 구분하는 것에 반대하고, 폭넓은 스펙트럼으로 이해하려 함."], "ev_en": "The attempt moves toward an understanding of reading as a spectrum that is expansive enough to accommodate the distinct reading activities.", "ev_ko": "그러한 시도는 별개의 읽기 활동들을 다 수용할 만큼 충분히 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전한다."}], "tf": [{"s": "필자는 읽기가 다른 행동과 분리되는 단일하고 일관된 개념이라는 주장에 동의한다.", "t": false, "why": ["틀린 부분은 \"동의한다\"임.", "단일하고 일관된 개념은 일부 사람들의 주장이고, 필자는 \"읽기는 정말 그렇게 단순할까?\"라고 의문을 제기함.", "필자는 읽기를 공통된 하나의 특성 없이 느슨하게 묶인 행동의 묶음으로 봄."], "ev_en": "The most productive way to think about reading is as a loosely related set of behaviors that belong together owing to family resemblances, as Ludwig Wittgenstein used the phrase, without having in common a single defining trait.", "ev_ko": "읽기에 대해 생각하는 가장 생산적인 방식은 하나의 명백한 특성을 공통적으로 가지지 않은 채 Ludwig Wittgenstein이 그 어구를 사용한 것처럼 가족 유사성 때문에 함께 속하게 되는 헐겁게 연결된 행동의 묶음으로서이다."}, {"s": "일부 사람들은 읽기가 책으로 하는 다른 행동들과 깔끔히 분리되는 하나의 개념이라고 주장한다.", "t": true, "why": ["읽기를 다른 행동과 깔끔히 분리되는 단일하고 일관된 개념으로 보는 것은 일부 사람들의 주장이므로 맞음."], "ev_en": "Some people argue that there is a single, logically consistent concept known as reading that can be neatly set apart from everything else people do with books.", "ev_ko": "몇몇 사람들은 사람들이 책을 가지고 하는 모든 다른 행동들로부터 깔끔하게 분리될 수 있는, 읽기로 알려진 유일하고 논리적으로 일관성 있는 개념이 있다고 주장한다."}, {"s": "필자는 예외적인 읽기 형태를 모으는 시도가 읽기를 폭넓은 스펙트럼으로 이해하는 쪽으로 이어진다고 본다.", "t": true, "why": ["그 시도는 별개의 읽기 활동들을 수용할 만큼 광범위한 스펙트럼으로 읽기를 이해하는 것으로 발전한다고 했으므로 맞음."], "ev_en": "The attempt moves toward an understanding of reading as a spectrum that is expansive enough to accommodate the distinct reading activities.", "ev_ko": "그러한 시도는 별개의 읽기 활동들을 다 수용할 만큼 충분히 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전한다."}, {"s": "읽기의 경계를 알아내려 할수록 경계를 넓히는 특이 사례는 줄어든다.", "t": false, "why": ["틀린 부분은 \"줄어든다\"임.", "경계를 알려 할수록 특이 사례가 더 많이 발견됨."], "ev_en": "The more one tries to figure out where the border lies between reading and not\u2011reading, the more edge cases will be found to stretch the term\u2019s flexible boundaries.", "ev_ko": "읽기와 읽기가 아닌 것 사이의 경계가 어디에 있는가를 알려고 하면 할수록, 더욱 많은 특이 사례들이 그 용어의 유연한 경계를 확장하고 있다는 것이 밝혀질 것이다."}, {"s": "예외적인 읽기 형태들을 한데 모아 놓은 하나의 토론의 장(forum, 의견을 나누는 자리)은, 읽기의 경계를 정하려는 사람들이 겪는 어려움을 부각한다.", "t": true, "why": ["모아 놓은 하나의 토론의 장(forum, 의견을 나누는 마당)이 경계를 정하려는 누구나 겪는 어려움을 부각한다고 했으므로 맞음."], "ev_en": "Thus, it is worth attempting to collect together these exceptional forms of reading into a single forum, one highlighting the challenges faced by anyone wishing to establish the boundaries where reading begins and ends.", "ev_ko": "그러므로, 이러한 예외적인 읽기의 형태들을 모두 함께 하나의 토론의 장으로 모으려는 시도는 해 볼 가치가 있으며, 그 토론의 장은 어디서 읽기가 시작되고 끝나는가에 대한 경계를 정하기를 원하는 누구나에 의해 마주하게 될 어려움들을 돋보이게 한다."}], "flow": {"fixed": "일부 사람들은 읽기가 책으로 하는 다른 행동들과 깔끔히 구분되는 하나의 일관된 개념이라고 주장하지만, 읽기가 정말 그렇게 단순할까?", "order": ["그렇지 않다. 읽기는 하나의 공통된 특성 없이 가족 유사성 때문에 묶이는, 헐겁게 연결된 행동의 묶음으로 보는 것이 가장 생산적이다.", "따라서 읽기와 읽기가 아닌 것을 가르려는 노력은 무엇이 읽기인지에 대한 합의가 없어 실패하고, 경계를 찾을수록 특이 사례는 더 늘어난다.", "그러므로 이런 예외적인 읽기 형태들을 한데 모으는 시도는 가치가 있으며, 읽기를 폭넓은 스펙트럼으로 이해하게 해 준다."], "clue": ["'그렇지 않다'가 고정 덩어리의 의문(\"그렇게 단순할까?\")에 직접 답하며 새 관점을 제시함", "\"따라서\"로 앞의 관점의 귀결(구분 실패)을 이끎", "\"그러므로\"로 앞 내용을 바탕으로 한 최종 제안을 제시함"], "why": ["단순한 정의 주장 -> 느슨한 묶음이라는 관점 -> 구분 실패 -> 스펙트럼 이해 순서임."], "cards": ["그러므로 이런 예외적인 읽기 형태들을 한데 모으는 시도는 가치가 있으며, 읽기를 폭넓은 스펙트럼으로 이해하게 해 준다.", "따라서 읽기와 읽기가 아닌 것을 가르려는 노력은 무엇이 읽기인지에 대한 합의가 없어 실패하고, 경계를 찾을수록 특이 사례는 더 늘어난다.", "그렇지 않다. 읽기는 하나의 공통된 특성 없이 가족 유사성 때문에 묶이는, 헐겁게 연결된 행동의 묶음으로 보는 것이 가장 생산적이다."], "answer": [2, 1, 0]}, "sents": [{"n": 1, "en": "Some people argue that there is a single, logically consistent concept known as reading that can be neatly set apart from everything else people do with books.", "ko": "몇몇 사람들은 사람들이 책을 가지고 하는 모든 다른 행동들로부터 깔끔하게 분리될 수 있는, 읽기로 알려진 유일하고 논리적으로 일관성 있는 개념이 있다고 주장한다."}, {"n": 2, "en": "Is reading really that simple?", "ko": "읽기는 정말로 그렇게 단순할까?"}, {"n": 3, "en": "The most productive way to think about reading is as a loosely related set of behaviors that belong together owing to family resemblances, as Ludwig Wittgenstein used the phrase, without having in common a single defining trait.", "ko": "읽기에 대해 생각하는 가장 생산적인 방식은 하나의 명백한 특성을 공통적으로 가지지 않은 채 Ludwig Wittgenstein이 그 어구를 사용한 것처럼 가족 유사성 때문에 함께 속하게 되는 헐겁게 연결된 행동의 묶음으로서이다."}, {"n": 4, "en": "Consequently, efforts to distinguish reading from nonreading are destined to fail because there is no agreement on what qualifies as reading in the first place.", "ko": "결론적으로, 읽기와 읽기가 아닌 것을 구분하려는 노력은 실패로 돌아가는데, 왜냐하면 애초에 무엇이 읽기로서의 자격을 주는가에 대한 동의가 없기 때문이다."}, {"n": 5, "en": "The more one tries to figure out where the border lies between reading and not\u2011reading, the more edge cases will be found to stretch the term\u2019s flexible boundaries.", "ko": "읽기와 읽기가 아닌 것 사이의 경계가 어디에 있는가를 알려고 하면 할수록, 더욱 많은 특이 사례들이 그 용어의 유연한 경계를 확장하고 있다는 것이 밝혀질 것이다."}, {"n": 6, "en": "Thus, it is worth attempting to collect together these exceptional forms of reading into a single forum, one highlighting the challenges faced by anyone wishing to establish the boundaries where reading begins and ends.", "ko": "그러므로, 이러한 예외적인 읽기의 형태들을 모두 함께 하나의 토론의 장으로 모으려는 시도는 해 볼 가치가 있으며, 그 토론의 장은 어디서 읽기가 시작되고 끝나는가에 대한 경계를 정하기를 원하는 누구나에 의해 마주하게 될 어려움들을 돋보이게 한다."}, {"n": 7, "en": "The attempt moves toward an understanding of reading as a spectrum that is expansive enough to accommodate the distinct reading activities.", "ko": "그러한 시도는 별개의 읽기 활동들을 다 수용할 만큼 충분히 광범위한 스펙트럼으로서 읽기를 이해하는 것으로 발전한다."}]}];
